        private static OptionItem Pick(IEnumerable<OptionItem> list, string value)
        {
            if (string.IsNullOrEmpty(value)) return null;
            return list.FirstOrDefault(o => string.Equals(o.Value, value, StringComparison.OrdinalIgnoreCase));
        }

        private void RefreshArchs(string preferred)
        {
            _archs.Clear();
            if (_version != null)
            {
                foreach (UupRow r in _rows)
                {
                    if (r.Version == _version.Value && !_archs.Any(a => a.Value == r.Arch)) _archs.Add(new OptionItem(r.Arch, r.Arch));
                }
            }
            _arch = Pick(_archs, preferred) ?? _archs.FirstOrDefault();
            Raise("SelectedArch");
        }

        private void Fetch()
        {
            if (_version == null || _arch == null || _language == null) return;
            UupRow row = _rows.FirstOrDefault(r => r.Version == _version.Value && r.Arch == _arch.Value);
            if (row == null)
            {
                Main.Dialog.ShowMessage("error", Loc.T("Msg_ErrorTitle"), Loc.F("Msg_NoVersion", _version.Value, _arch.Value));
                return;
            }
            if (row.UpdateId.StartsWith("NOT_IN_UUP", StringComparison.OrdinalIgnoreCase))
            {
                Main.Dialog.ShowMessage("info", Loc.T("Info_NotInUupTitle"), Loc.T("Info_NotInUup"));
                Main.SetStatus(Loc.T("St_NotInUup"), "warn");
                return;
            }
            UiRequest req = new UiRequest("LangFetch");
            req.Args["UpdateId"] = row.UpdateId;
            req.Args["Version"] = row.Version;
            req.Args["Arch"] = row.Arch;
            req.Args["Lang"] = _language.Value;
            req.Args["IsServer"] = row.IsServer || row.Version.IndexOf("Server", StringComparison.OrdinalIgnoreCase) >= 0;
            req.Args["IsWin11"] = row.IsWin11;
            if (Host.Submit(req, "lang", Loc.T("Job_LangFetch"))) _pendingFetch = req;
        }

        internal void SetItems(PackageItem[] items, string info)
        {
            if (_pendingFetch != null)
            {
                _listedVersion = _pendingFetch.GetString("Version");
                _listedArch = _pendingFetch.GetString("Arch");
                _listedLang = _pendingFetch.GetString("Lang");
                _pendingFetch = null;
            }
            ReplaceItems(items);
            SetInfo(info, false);
        }

        private void Download()
        {
            PackageItem[] sel = CheckedItems();
            if (sel.Length == 0)
            {
                Main.Dialog.ShowMessage("warn", Loc.T("Msg_WarnTitle"), Loc.T("Msg_SelectFiles"));
                return;
            }
            foreach (PackageItem it in sel) it.SetStateCore(ItemState.Queued, null, -1);
            UiRequest req = new UiRequest("LangDownload");
            req.Args["Items"] = sel;
            req.Args["Arch"] = _listedArch ?? (_arch != null ? _arch.Value : "x64");
            req.Args["Version"] = _listedVersion;
            req.Args["Lang"] = _listedLang;
            req.Args["Root"] = Main.Settings.OutputRoot;
            req.Args["SkipExisting"] = Main.Settings.SkipExisting;
            req.Args["Verify"] = Main.Settings.VerifyHash;
            if (!Host.Submit(req, "lang", Loc.F("Job_DownloadStart", sel.Length)))
            {
                foreach (PackageItem it in sel) it.SetStateCore(ItemState.Idle, null, -1);
            }
        }

        private void Clean()
        {
            string root = Main.Settings.OutputRoot;
            Main.Dialog.Confirm("clean", Loc.T("Dlg_CleanTitle"), Loc.T("Dlg_CleanLang"),
                new KeyValueRow[] { new KeyValueRow(Loc.T("Dlg_Folder"), root) }, null, Loc.T("Btn_Delete"),
                delegate(bool ok)
                {
                    if (!ok) return;
                    UiRequest req = new UiRequest("LangClean");
                    req.Args["Root"] = root;
                    Host.Submit(req, "lang", Loc.T("Job_Clean"));
                });
        }
    }

    // Windows PE page
    public sealed class PePageViewModel : ListPageViewModel
    {
        private sealed class PeVersion
        {
            public string Label, BuildId;
            public bool IsServer;
        }

        private readonly List<PeVersion> _peVersions = new List<PeVersion>();
        private readonly Dictionary<string, Dictionary<string, List<string>>> _avail = new Dictionary<string, Dictionary<string, List<string>>>(StringComparer.OrdinalIgnoreCase);
        private readonly Dictionary<string, string> _regionNames = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        private readonly Dictionary<string, string[]> _deps = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase);
        private readonly Dictionary<string, long> _containerSizes = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
        private readonly ObservableCollection<OptionItem> _versions = new ObservableCollection<OptionItem>();
        private readonly ObservableCollection<OptionItem> _archs = new ObservableCollection<OptionItem>();
        private readonly ObservableCollection<OptionItem> _languages = new ObservableCollection<OptionItem>();
        private OptionItem _version, _arch, _language;
        private UiRequest _pendingFetch;
        private string _listedBuild, _listedArch, _listedLang, _listedVersion, _buildInfo = string.Empty;
        private long _dlBytes;
        private int _dlCount;

        public PePageViewModel(MainViewModel main, UiHost host) : base(main, host)
        {
            foreach (string line in host.Options.PeVersions ?? new string[0])
            {
                string[] p = (line ?? string.Empty).Split('|');
                if (p.Length < 2) continue;
                PeVersion v = new PeVersion();
                v.Label = p[0];
                v.BuildId = p[1];
                v.IsServer = p.Length > 2 ? string.Equals(p[2], "true", StringComparison.OrdinalIgnoreCase) : p[0].IndexOf("Server", StringComparison.OrdinalIgnoreCase) >= 0;
                _peVersions.Add(v);
                _versions.Add(new OptionItem(v.Label, v.Label, v.BuildId));
            }
            foreach (string line in host.Options.Regions ?? new string[0])
            {
                string[] p = (line ?? string.Empty).Split('|');
                if (p.Length >= 2) _regionNames[p[0]] = p[1];
            }
            foreach (string line in host.Options.OcDependencies ?? new string[0])
            {
                string[] p = (line ?? string.Empty).Split('|');
                if (p.Length < 2) continue;
                _deps[p[0]] = p[1].Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).ToArray();
            }

            AppSettings s = host.Settings;
            _version = Pick(_versions, s.Get("PeVersion", null)) ?? _versions.FirstOrDefault();
            RefreshArchs(s.Get("PeArch", null));
            RefreshLanguages(s.Get("PeLang", null));

            FetchCommand = new RelayCommand(p => Fetch(), p => Main.IsIdle && _version != null && _arch != null && _language != null);
            DownloadCommand = new RelayCommand(p => Download(), p => Main.IsIdle && SelectedCount > 0);
            CleanCommand = new RelayCommand(p => Clean(), p => Main.IsIdle);
            OpenFolderCommand = new RelayCommand(p => MainViewModel.OpenInExplorer(Path.Combine(Main.Settings.OutputRoot ?? string.Empty, "WinPE"), true));
        }

        public ICommand FetchCommand { get; private set; }
        public ICommand DownloadCommand { get; private set; }
        public ICommand CleanCommand { get; private set; }
        public ICommand OpenFolderCommand { get; private set; }
        public ObservableCollection<OptionItem> Versions { get { return _versions; } }
        public ObservableCollection<OptionItem> Archs { get { return _archs; } }
        public ObservableCollection<OptionItem> Languages { get { return _languages; } }
        protected override string EmptyKey { get { return "Pe_Empty"; } }

        protected override void OnListCleared()
        {
            _listedBuild = _listedArch = _listedLang = _listedVersion = null;
            _containerSizes.Clear();
            _buildInfo = string.Empty;
            Raise("BuildInfoText");
            OnSelectionChanged();
        }
