        $attrib.Add("IsFutureKeyEnabled=1")
    }
    return [System.Net.WebUtility]::HtmlEncode('E:' + ($attrib -join '&'))
}
# FE3 SOAP request: curl.exe when available, otherwise Invoke-WebRequest
function Invoke-Fe3SoapRequest {
    param([string]$Soap)
    $endpoints = @(
        'https://fe3cr.delivery.mp.microsoft.com/ClientWebService/client.asmx/secured',
        'https://fe3.delivery.mp.microsoft.com/ClientWebService/client.asmx/secured'
    )
    $curl = Join-Path $env:SystemRoot 'System32\curl.exe'
    if (Test-Path -LiteralPath $curl) {
        $tmpReq = Join-Path $env:TEMP ("fe3_req_" + [guid]::NewGuid().ToString('N') + ".xml")
        $tmpOut = Join-Path $env:TEMP ("fe3_out_" + [guid]::NewGuid().ToString('N') + ".xml")
        try {
            [System.IO.File]::WriteAllText($tmpReq, $Soap, (New-Object System.Text.UTF8Encoding($false)))
            # Try with certificate validation first (Windows curl.exe trusts the Microsoft roots via Schannel);
            # fall back to the unvalidated (-k) call only if that fails.
            # Downloaded files are still verified against the SHA-1 from the UUP metadata.
            foreach ($insecure in @($false, $true)) {
                foreach ($ep in $endpoints) {
                    Assert-UiNotCancelled
                    Remove-Item -LiteralPath $tmpOut -Force -ErrorAction SilentlyContinue
                    $curlArgs = @('-sS', '--compressed', '--connect-timeout', '15', '--max-time', '30', '-X', 'POST', $ep,
                                  '-H', 'Content-Type: application/soap+xml; charset=utf-8',
                                  '-A', 'Windows-Update-Agent/10.0.10011.16384 Client-Protocol/2.50',
                                  '--data-binary', "@$tmpReq", '-o', $tmpOut)
                    if ($insecure) { $curlArgs = @('-k') + $curlArgs }
                    $null = & $curl @curlArgs
                    if (Test-Path -LiteralPath $tmpOut) {
                        $xmlContent = [System.IO.File]::ReadAllText($tmpOut, [System.Text.Encoding]::UTF8)
                        if ($xmlContent -match '<FileLocation>') {
                            if ($insecure) { Write-UiLog 'warn' "FE3: sertifika doğrulanamadı, doğrulamasız bağlantı kullanıldı ($ep)" }
                            return $xmlContent
                        }
                    }
                }
            }
        } finally {
            Remove-Item -LiteralPath $tmpReq, $tmpOut -Force -ErrorAction SilentlyContinue
        }
    } else {
        foreach ($ep in $endpoints) {
            Assert-UiNotCancelled
            try {
                $resp = Invoke-WebRequest -Uri $ep -Method Post -UseBasicParsing -TimeoutSec 30 `
                    -Body ([System.Text.Encoding]::UTF8.GetBytes($Soap)) `
                    -ContentType 'application/soap+xml; charset=utf-8' `
                    -UserAgent 'Windows-Update-Agent/10.0.10011.16384 Client-Protocol/2.50' -ErrorAction Stop
                $content = if ($resp.Content -is [byte[]]) { [System.Text.Encoding]::UTF8.GetString($resp.Content) } else { [string]$resp.Content }
                if ($content -match '<FileLocation>') { return $content }
            } catch {
                Write-UiLog 'warn' "FE3: $($_.Exception.Message)"
            }
        }
    }
    return $null
}

function Get-DirectMsFe3XmlForUpdate {
    param(
        [string]$UpdateID,
        [string]$Build = '10.0.26100.1',
        [string]$Arch = 'amd64',
        [int]$Sku = 48
    )

    $cleanId = ($UpdateID -replace '_rev\.\d+$', '').ToLowerInvariant()
    $nowUnix = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()

    # 1. Memory cache (valid for 8 minutes)
    if ($script:Fe3XmlMemoryCache.ContainsKey($cleanId)) {
        $entry = $script:Fe3XmlMemoryCache[$cleanId]
        if ($entry -and ($nowUnix - $entry.FetchedUnix) -lt 480 -and $entry.Xml) {
            return [string]$entry.Xml
        }
    }

    # 2. Disk cache (valid for 8 minutes)
    if (-not (Test-Path $script:UupCacheDir)) {
        New-Item -Path $script:UupCacheDir -ItemType Directory -Force | Out-Null
    }
    $fe3CacheFile = Join-Path $script:UupCacheDir "fe3_${cleanId}.xml"
    if (Test-Path -LiteralPath $fe3CacheFile) {
        try {
            $fi = Get-Item -LiteralPath $fe3CacheFile -ErrorAction Stop
            if (((Get-Date).ToUniversalTime() - $fi.LastWriteTimeUtc).TotalSeconds -lt 480 -and $fi.Length -gt 2048) {
                $cachedXml = [System.IO.File]::ReadAllText($fe3CacheFile, [System.Text.Encoding]::UTF8)
                if ($cachedXml -match '<FileLocation>') {
                    $script:Fe3XmlMemoryCache[$cleanId] = [PSCustomObject]@{ FetchedUnix = $nowUnix; Xml = $cachedXml }
                    return $cachedXml
                }
            }
        } catch { }
    }

    Set-UiStatus (L 'Job_Fe3')

    $rev = 1
    if ($UpdateID -match '_rev\.(\d+)$') {
        $rev = [int]$Matches[1]
    }

    $device  = New-UupDeviceTicket
    $msgId   = [guid]::NewGuid().ToString()
    $nowUtc  = [DateTime]::UtcNow
    $created = $nowUtc.ToString("yyyy-MM-dd'T'HH:mm:ss'+00:00'")
    $expires = $nowUtc.AddMinutes(2).ToString("yyyy-MM-dd'T'HH:mm:ss'+00:00'")
    $da      = New-UupDeviceAttributes -Build $Build -Arch $Arch -Sku $Sku -Ring 'RETAIL'

    $soap = @"
<s:Envelope xmlns:a="http://www.w3.org/2005/08/addressing" xmlns:s="http://www.w3.org/2003/05/soap-envelope">
    <s:Header>
        <a:Action s:mustUnderstand="1">http://www.microsoft.com/SoftwareDistribution/Server/ClientWebService/GetExtendedUpdateInfo2</a:Action>
        <a:MessageID>urn:uuid:$msgId</a:MessageID>
        <a:To s:mustUnderstand="1">https://fe3.delivery.mp.microsoft.com/ClientWebService/client.asmx/secured</a:To>
        <o:Security s:mustUnderstand="1" xmlns:o="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd">
            <Timestamp xmlns="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd">
                <Created>$created</Created>
                <Expires>$expires</Expires>
            </Timestamp>
            <wuws:WindowsUpdateTicketsToken wsu:id="ClientMSA" xmlns:wsu="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd" xmlns:wuws="http://schemas.microsoft.com/msus/2014/10/WindowsUpdateAuthorization">
                <TicketType Name="MSA" Version="1.0" Policy="MBI_SSL">
                    <Device>$device</Device>
                </TicketType>
            </wuws:WindowsUpdateTicketsToken>
        </o:Security>
    </s:Header>
    <s:Body>
        <GetExtendedUpdateInfo2 xmlns="http://www.microsoft.com/SoftwareDistribution/Server/ClientWebService">
            <updateIDs>
                <UpdateIdentity>
                    <UpdateID>$cleanId</UpdateID>
                    <RevisionNumber>$rev</RevisionNumber>
                </UpdateIdentity>
            </updateIDs>
            <infoTypes>
                <XmlUpdateFragmentType>FileUrl</XmlUpdateFragmentType>
                <XmlUpdateFragmentType>FileDecryption</XmlUpdateFragmentType>
                <XmlUpdateFragmentType>EsrpDecryptionInformation</XmlUpdateFragmentType>
                <XmlUpdateFragmentType>PiecesHashUrl</XmlUpdateFragmentType>
                <XmlUpdateFragmentType>BlockMapUrl</XmlUpdateFragmentType>
            </infoTypes>
            <deviceAttributes>$da</deviceAttributes>
        </GetExtendedUpdateInfo2>
    </s:Body>
</s:Envelope>
"@

    $xmlContent = Invoke-Fe3SoapRequest -Soap $soap
    if ($xmlContent -and $xmlContent -match '<FileLocation>') {
        $script:Fe3XmlMemoryCache[$cleanId] = [PSCustomObject]@{ FetchedUnix = $nowUnix; Xml = $xmlContent }
        try { [System.IO.File]::WriteAllText($fe3CacheFile, $xmlContent, (New-Object System.Text.UTF8Encoding($false))) } catch { }
        return $xmlContent
    }
    return $null
}

function Clear-Fe3Cache {
    param([string]$UpdateID)
    $cleanId = ($UpdateID -replace '_rev\.\d+$', '').ToLowerInvariant()
    if ($script:Fe3XmlMemoryCache.ContainsKey($cleanId)) { $script:Fe3XmlMemoryCache.Remove($cleanId) }
    $fe3CacheFile = Join-Path $script:UupCacheDir "fe3_${cleanId}.xml"
    Remove-Item -LiteralPath $fe3CacheFile -Force -ErrorAction SilentlyContinue
}

function Find-UrlBySha1InFe3Xml {
    param(
        [string]$XmlContent,
        [string]$Sha1Hex
    )
    if ([string]::IsNullOrWhiteSpace($XmlContent) -or [string]::IsNullOrWhiteSpace($Sha1Hex) -or $Sha1Hex.Length -ne 40) {
        return $null
    }
    $bytes = New-Object byte[] 20
    for ($i = 0; $i -lt 20; $i++) {
        $bytes[$i] = [Convert]::ToByte($Sha1Hex.Substring($i * 2, 2), 16)
    }
    $digestB64 = [Convert]::ToBase64String($bytes)
    $needle = "<FileDigest>$digestB64</FileDigest><Url>"
    $idx = $XmlContent.IndexOf($needle, [System.StringComparison]::Ordinal)
    if ($idx -lt 0) {
        $escapedDigest = [regex]::Escape($digestB64)
        $m = [regex]::Match($XmlContent, "<FileDigest>\s*$escapedDigest\s*</FileDigest>\s*<Url>([^<]+)</Url>", [System.Text.RegularExpressions.RegexOptions]'IgnoreCase, CultureInvariant')
        if (-not $m.Success) { return $null }
        $rawUrl = [System.Net.WebUtility]::HtmlDecode($m.Groups[1].Value.Trim())
    } else {
        $urlStart = $idx + $needle.Length
        $urlEnd   = $XmlContent.IndexOf("</Url>", $urlStart, [System.StringComparison]::Ordinal)
        if ($urlEnd -lt 0) { return $null }
        $rawUrl = [System.Net.WebUtility]::HtmlDecode($XmlContent.Substring($urlStart, $urlEnd - $urlStart).Trim())
    }
    $expire = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds() + 600
    if ($rawUrl -match 'P1=(\d+)') {
        $expire = [long]$Matches[1]
    }
    return [PSCustomObject]@{
        Url    = $rawUrl
        Expire = $expire
    }
}
function Resolve-DirectMsUrlForFile {
    param(
        [string]$UpdateID,
        [string]$Sha1Hex,
        [string]$Build = '10.0.26100.1',
        [string]$Arch = 'amd64',
        [int]$Sku = 48
    )
    if ([string]::IsNullOrWhiteSpace($Sha1Hex)) { return $null }

    # 1. Direct Microsoft FE3 SOAP query for the primary UpdateID
    $xml = Get-DirectMsFe3XmlForUpdate -UpdateID $UpdateID -Build $Build -Arch $Arch -Sku $Sku
    if ($xml) {
        $found = Find-UrlBySha1InFe3Xml -XmlContent $xml -Sha1Hex $Sha1Hex
        if ($found) { return $found }
    }

    # 2. Fallback base OS FE3 pool: 25H2/26H2 -> 24H2 (26100), Server 22H2 -> Server 21H2 (20348)
    $fallbackUpdateId = $null
    $fallbackBuild    = $null
    $fallbackSku      = $Sku
    if ($Build -match '26200|26300|26100') {
        $fallbackUpdateId = if ($Arch -match 'arm64') { 'b6049aaf-4f56-4183-8e58-32954906de64' } else { 'ad27e52b-9e18-408a-9df2-8688e5273fbf' }
        $fallbackBuild    = '10.0.26100.2605'
        $fallbackSku      = 48
    } elseif ($Build -match '20349|20348') {
        $fallbackUpdateId = '2ba1d737-a36b-415b-a630-85bd5146d77d'
        $fallbackBuild    = '10.0.20348.1'
        $fallbackSku      = 7
    }
    if ($fallbackUpdateId -and $fallbackUpdateId -ne $UpdateID) {
        $xmlFb = Get-DirectMsFe3XmlForUpdate -UpdateID $fallbackUpdateId -Build $fallbackBuild -Arch $Arch -Sku $fallbackSku
        if ($xmlFb) {
            $foundFb = Find-UrlBySha1InFe3Xml -XmlContent $xmlFb -Sha1Hex $Sha1Hex
            if ($foundFb) { return $foundFb }
        }
    }
    return $null
}

# UUP dump metadata (noLinks=1: no rate limit) and live URL resolution
function Get-UUPFiles {
    param (
        [Parameter(Mandatory=$true)]
        [string]$UpdateID,
        [Parameter(Mandatory=$false)]
        [string]$Language = $null,
        [switch]$NoLinks,
        [switch]$ForceRefresh
    )

    $record = $script:UUP_Table | Where-Object { $_.UpdateID -eq $UpdateID } | Select-Object -First 1
    if ($null -eq $record) {
        throw "UpdateID '$UpdateID' UUP_Table içinde bulunamadı."
    }
    if ([string]::IsNullOrWhiteSpace($Language)) {
        throw "Dil parametresi boş olamaz."
    }

    $cacheKey        = "${UpdateID}_${Language}".ToLowerInvariant()
    $noLinksCacheKey = "${UpdateID}_all".ToLowerInvariant()
    if (-not (Test-Path $script:UupCacheDir)) {
        New-Item -Path $script:UupCacheDir -ItemType Directory -Force | Out-Null
    }
    $cacheFile        = Join-Path $script:UupCacheDir ($cacheKey + ".json")
    $stampFile        = Join-Path $script:UupCacheDir "_last_req.txt"

    # 1. Memory cache
    if (-not $ForceRefresh -and $script:UupMemoryCache.ContainsKey($cacheKey)) {
        $memObj = $script:UupMemoryCache[$cacheKey]
        if (Test-UupCacheValid -ResponseObj $memObj -MinRemainingSeconds 90) {
            return $memObj
        }
    }
    if ($NoLinks -and -not $ForceRefresh -and $script:UupNoLinksCache.ContainsKey($cacheKey)) {
        $nlMem = $script:UupNoLinksCache[$cacheKey]
        if (Test-UupCacheValid -ResponseObj $nlMem -AllowNoLinks) {
            $script:LastManifestSource = 'LocalCatalog'
            return $nlMem
        }
    }

    # 2. Persistent local catalog (Manifests folders)
    $staleDiskObj = $null
    $candidateFiles = @()
    foreach ($mDir in $script:ManifestDirs) {
        if (Test-Path -LiteralPath $mDir) {
            if ($NoLinks) {
                $candidateFiles += (Join-Path $mDir ($noLinksCacheKey + "_nolinks.json"))
            } else {
                $candidateFiles += (Join-Path $mDir ($cacheKey + ".json"))
            }
        }
    }
    foreach ($candidateFile in $candidateFiles) {
        if (Test-Path -LiteralPath $candidateFile) {
            try {
                $diskRaw = Get-Content -LiteralPath $candidateFile -Raw -Encoding UTF8 -ErrorAction Stop
                $diskObj = ConvertFrom-UupJson -JsonText $diskRaw -Language $Language
                if ($diskObj -and $diskObj.response -and $diskObj.response.files) {
                    if ($null -eq $staleDiskObj) { $staleDiskObj = $diskObj }
                    if (-not $ForceRefresh -and (Test-UupCacheValid -ResponseObj $diskObj -MinRemainingSeconds 90 -AllowNoLinks:$NoLinks)) {
                        if ($NoLinks) { $script:UupNoLinksCache[$cacheKey] = $diskObj }
                        else { $script:UupMemoryCache[$cacheKey] = $diskObj }
                        $script:LastManifestSource = 'LocalCatalog'
                        return $diskObj
                    }
                }
            } catch { }
        }
    }

    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor 3072 -bor 12288
    } catch {
        try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }
    }

    $curl = Join-Path $env:SystemRoot 'System32\curl.exe'

    # 3. noLinks=1 is not rate limited (no HTTP 429); without &lang= it returns every language pack
    #    and FOD for client and server in one response.
    if ($NoLinks) {
        Set-UiStatus (LF 'Job_UupMeta' $Language)
        $noLinksUrl = "https://api.uupdump.net/get.php?id=$UpdateID&noLinks=1"
        $contentStr = $null
        if (Test-Path -LiteralPath $curl) {
            $tmpJson = Join-Path $env:TEMP ("uup_nl_" + [guid]::NewGuid().ToString('N') + ".json")
            try {
                $null = & $curl -sS -L --compressed --connect-timeout 10 --max-time 25 $noLinksUrl -o $tmpJson
                if (Test-Path -LiteralPath $tmpJson) {
                    $contentStr = [System.IO.File]::ReadAllText($tmpJson, [System.Text.Encoding]::UTF8)
                }
            } finally {
                Remove-Item -LiteralPath $tmpJson -Force -ErrorAction SilentlyContinue
            }
        }
        Assert-UiNotCancelled
        if ([string]::IsNullOrWhiteSpace($contentStr)) {
            $webResp = Invoke-WebRequest -Uri $noLinksUrl -Method Get -UseBasicParsing -TimeoutSec 25 -Headers @{ 'Accept' = 'application/json' } -ErrorAction Stop
            $contentStr = if ($webResp.Content -is [byte[]]) { [System.Text.Encoding]::UTF8.GetString($webResp.Content) } else { [string]$webResp.Content }
        }
        $parsed = ConvertFrom-UupJson -JsonText $contentStr -Language $Language
        if ($parsed -and $parsed.response -and $parsed.response.files) {
            $script:UupNoLinksCache[$cacheKey] = $parsed
            try {
                if (-not (Test-Path $script:LocalManifestDir)) { New-Item -Path $script:LocalManifestDir -ItemType Directory -Force | Out-Null }
                Set-Content -LiteralPath (Join-Path $script:LocalManifestDir ($noLinksCacheKey + "_nolinks.json")) -Value $contentStr -Encoding UTF8 -Force -ErrorAction SilentlyContinue
            } catch { }
            $script:LastManifestSource = 'Online'
            return $parsed
        }
        if ($null -ne $staleDiskObj) {
            $script:LastManifestSource = 'LocalCatalog'
            return $staleDiskObj
        }
        if ($parsed -and $parsed.error) { throw "API Hatası: $($parsed.error)" }
    }

    # 4. Live UUP URL resolution (5.5 s spacing between requests, automatic retry on HTTP 429)
    $minGapMs = 5500
    $lastTicks = $script:LastUupCallUtc.Ticks
    if (Test-Path -LiteralPath $stampFile) {
        try {
            $parsedTicks = [long](Get-Content -LiteralPath $stampFile -Raw -ErrorAction Stop).Trim()
            if ($parsedTicks -gt $lastTicks) { $lastTicks = $parsedTicks }
        } catch { }
    }
    if ($lastTicks -gt 0) {
        $elapsedMs = ([DateTime]::UtcNow.Ticks - $lastTicks) / 10000
        if ($elapsedMs -ge 0 -and $elapsedMs -lt $minGapMs) {
            $waitMs = [int]($minGapMs - $elapsedMs)
            Wait-UiDelay -Milliseconds $waitMs -MessageKey 'Job_RateWait'
        }
    }

    $apiUrl = "https://api.uupdump.net/get.php?id=$UpdateID&lang=$Language"
    $retryDelaysSec = @(5, 8, 12, 16, 22, 30)
    $maxAttempts = $retryDelaysSec.Count + 1

    for ($attempt = 1; $attempt -le $maxAttempts; $attempt++) {
        try {
            Assert-UiNotCancelled
            if ($attempt -eq 1) {
                Set-UiStatus (LF 'Job_UupLinks' $Language)
            } else {
                Set-UiStatus (LF 'Job_UupReconnect' $attempt $maxAttempts)
            }

            $nowUtc = [DateTime]::UtcNow
            $script:LastUupCallUtc = $nowUtc
            try { Set-Content -LiteralPath $stampFile -Value $nowUtc.Ticks.ToString() -Encoding ASCII -Force -ErrorAction SilentlyContinue } catch { }

            $webResp = Invoke-WebRequest -Uri $apiUrl -Method Get -UseBasicParsing -TimeoutSec 25 -Headers @{ 'Accept' = 'application/json' } -ErrorAction Stop
            $nowUtc = [DateTime]::UtcNow
            $script:LastUupCallUtc = $nowUtc
            try { Set-Content -LiteralPath $stampFile -Value $nowUtc.Ticks.ToString() -Encoding ASCII -Force -ErrorAction SilentlyContinue } catch { }

            $contentStr = if ($webResp.Content -is [byte[]]) { [System.Text.Encoding]::UTF8.GetString($webResp.Content) } else { [string]$webResp.Content }
            $parsed = ConvertFrom-UupJson -JsonText $contentStr -Language $Language

            if ($parsed -and $parsed.response -and $parsed.response.files) {
                $script:UupMemoryCache[$cacheKey] = $parsed
                try { Set-Content -LiteralPath $cacheFile -Value $contentStr -Encoding UTF8 -Force -ErrorAction SilentlyContinue } catch { }
                $script:LastManifestSource = 'Online'
                return $parsed
            }

            if ($parsed -and $parsed.error) {
                throw "API Hatası: $($parsed.error)"
            }
            throw "Sunucudan geçersiz yanıt alındı."
        }
        catch [System.OperationCanceledException] {
            throw
        }
        catch {
            $nowUtc = [DateTime]::UtcNow
            $script:LastUupCallUtc = $nowUtc
            try { Set-Content -LiteralPath $stampFile -Value $nowUtc.Ticks.ToString() -Encoding ASCII -Force -ErrorAction SilentlyContinue } catch { }

            $errMsg = [string]$_.Exception.Message
            $statusCode = 0
            $retryAfterSec = 0
            if ($_.Exception.Response) {
                try { $statusCode = [int]$_.Exception.Response.StatusCode } catch { }
                try {
                    $ra = $_.Exception.Response.Headers['Retry-After']
                    if ($ra -and [int]::TryParse([string]$ra, [ref]$retryAfterSec)) { }
                } catch { }
            }

            $isRateLimitOrTransient = ($statusCode -eq 429) -or ($statusCode -ge 500) -or ($errMsg -match '429|Too Many Requests|502|503|504|timed out|zaman a')
            if ($isRateLimitOrTransient -and $attempt -lt $maxAttempts) {
                $waitSec = $retryDelaysSec[$attempt - 1]
                if ($retryAfterSec -gt $waitSec -and $retryAfterSec -le 60) {
                    $waitSec = $retryAfterSec
                }
                Wait-UiDelay -Milliseconds ($waitSec * 1000) -MessageKey 'Job_Retry' -MessageArgs @(($attempt + 1), $maxAttempts)
                continue
            }

            if (-not $ForceRefresh -and $null -ne $staleDiskObj) {
                return $staleDiskObj
            }

            throw
        }
    }
}

function Resolve-LangPackFileDownloadUrl {
    param(
        [Parameter(Mandatory=$true)]
        [string]$FileName,
        [Parameter(Mandatory=$true)]
        $TagObj
    )

    $updateId = [string]$TagObj.UpdateID
    $langCode = [string]$TagObj.Language
    $sha1Hex  = ([string]$TagObj.Sha1).ToLowerInvariant()
    $buildStr = if ($TagObj.Build) { [string]$TagObj.Build } else { '10.0.26100.1' }
    $archStr  = if ($TagObj.Arch)  { [string]$TagObj.Arch }  else { 'amd64' }
    $skuInt   = if ($TagObj.Sku)   { [int]$TagObj.Sku }      else { 48 }

    # Query the Microsoft Windows Update FE3 SOAP service directly
    if (-not [string]::IsNullOrWhiteSpace($sha1Hex)) {
        $msResult = $null
        try {
            $msResult = Resolve-DirectMsUrlForFile -UpdateID $updateId -Sha1Hex $sha1Hex -Build $buildStr -Arch $archStr -Sku $skuInt
        } catch [System.OperationCanceledException] {
            throw
        } catch {
            throw "Doğrudan Microsoft FE3 SOAP bağlantı çözümlemesi başarısız oldu: $($_.Exception.Message)"
        }
        if ($msResult -and -not [string]::IsNullOrWhiteSpace([string]$msResult.Url)) {
            return [PSCustomObject]@{
                Url    = [string]$msResult.Url
                Expire = [long]$msResult.Expire
                Size   = [long]$TagObj.Size
                Source = 'DirectMS_FE3'
            }
        }
        throw "Doğrudan Microsoft FE3 sunucusunda bu dosya için bağlantı bulunamadı ($FileName / SHA1: $sha1Hex)."
    }

    # Alternative: live UUP resolution
    $refreshed = Get-UUPFiles -UpdateID $updateId -Language $langCode -ForceRefresh
    if ($refreshed -and $refreshed.response -and $refreshed.response.files) {
        $prop = $refreshed.response.files.PSObject.Properties[$FileName]
        if ($prop -and -not [string]::IsNullOrWhiteSpace([string]$prop.Value.url)) {
            return [PSCustomObject]@{
                Url    = [string]$prop.Value.url
                Expire = [long]$prop.Value.expire
                Size   = [long]$prop.Value.size
                Source = 'DirectMS'
            }
        }
    }
    return $null
}

# --- List item (PackageItem) builders ---
function ConvertTo-LangItems {
    param(
        $Response,
        [string]$Language,
        [bool]$IsServer,
        [string]$UpdateId
    )
    $respBuild = [string]$Response.response.build
    $respArch  = [string]$Response.response.arch
    $respSku   = if ($Response.response.sku) { [int]$Response.response.sku } else { 48 }

    # Filter and order: 0 main language pack, 1 language features, 2 client FOD, 3 server FOD
    $decorated = foreach ($file in @($Response.response.files.PSObject.Properties)) {
        if (-not (Filter-WindowsFiles -File $file -Language $Language -IsServer $IsServer)) { continue }
        $isLxp = $file.Name -match 'LanguageExperiencePack[._].*\.appx$'
        $isLp  = $isLxp -or $file.Name -match 'LanguagePack|_lp\.esd$'
        $isFtr = $file.Name -match 'LanguageFeatures-'
        $isSrv = Test-IsServerFOD -FileName $file.Name -Language $Language
        # Local Experience Pack (.appx) right after the main language pack
        $prio  = if ($isLxp) { 0.5 } elseif ($isLp) { 0 } elseif ($isFtr) { 1 } elseif ($isSrv) { 3 } else { 2 }
        $cat   = if ($isLp) { 'lp' } elseif ($isFtr) { 'feature' } elseif ($isSrv) { 'server' } else { 'fod' }
        [PSCustomObject]@{ File = $file; Prio = $prio; Cat = $cat; Name = [string]$file.Name }
    }
    $sorted = @($decorated | Sort-Object -Property @{ Expression = 'Prio'; Ascending = $true }, @{ Expression = 'Name'; Ascending = $true })

    $list = New-Object 'System.Collections.Generic.List[WinPEOCs.PackageItem]'
    $idx = 0
    foreach ($d in $sorted) {
        $f = $d.File
        $it = New-Object WinPEOCs.PackageItem
        $it.Key       = $d.Name
        $it.Name      = $d.Name
        $it.Category  = $d.Cat
        $it.SortIndex = $idx
        $it.Size      = [long]$f.Value.size
        $it.Url       = [string]$f.Value.url
        $it.Expire    = if ($f.Value.expire) { [long]$f.Value.expire } else { [long]0 }
        $it.Sha1      = [string]$f.Value.sha1
        $it.Sha256    = [string]$f.Value.sha256
        $it.UpdateId  = $UpdateId
        $it.Language  = $Language
        $it.Build     = $respBuild
        $it.Arch      = $respArch
        $it.Sku       = $respSku
        $list.Add($it)
        $idx++
    }
    return ,$list.ToArray()
}

function Get-PeCategory {
    param([string]$Name)
    if ($Name -match '^(lp|WinPE-LanguagePack)') { return 'lp' }
    if ($Name -match '^(WinPE-WMI|WinPE-NetFx|WinPE-Scripting|WinPE-PowerShell|WinPE-StorageWMI|WinPE-DismCmdlets|WinPE-EnhancedStorage)') { return 'core' }
    if ($Name -match '^(WinPE-Setup-Server|WinPE-Setup-ASZ)') { return 'server' }
    return 'other'
}

function ConvertTo-PeItems {
    param(
        [object[]]$Files,
        [string]$BuildId,
        [string]$Arch,
        [string]$Language,
        [bool]$IsServer
    )
    # One row per component; Setup-Client is listed for client builds, Setup-Server / ASZ for server builds
    $byComponent = @{}
    foreach ($f in $Files) {
        $compName = [string]$f.ComponentName
        if (-not $IsServer -and ($compName -eq 'WinPE-Setup-Server' -or $compName -eq 'WinPE-Setup-ASZ')) { continue }
        if ($IsServer -and ($compName -eq 'WinPE-Setup-Client')) { continue }
        if (-not $byComponent.ContainsKey($compName)) { $byComponent[$compName] = New-Object System.Collections.Generic.List[object] }
        $byComponent[$compName].Add($f)
    }

    $prio = @{ 'lp' = 0; 'core' = 1; 'other' = 2; 'server' = 3 }
    $sortedNames = @($byComponent.Keys | Sort-Object -Property @{ Expression = { $prio[(Get-PeCategory $_)] }; Ascending = $true }, @{ Expression = { $_ }; Ascending = $true })

    $list = New-Object 'System.Collections.Generic.List[WinPEOCs.PackageItem]'
    $idx = 0
    foreach ($compName in $sortedNames) {
        $group = $byComponent[$compName]
        $total = [long]0
        foreach ($g in $group) { $total += [long]$g.FileSize }
        $it = New-Object WinPEOCs.PackageItem
        $it.Key        = $compName
        $it.Name       = $compName
        $it.DescTr     = [string]$script:OcDescriptions[$compName]
        $it.DescEn     = [string]$script:OcDescriptionsEn[$compName]
        $it.Category   = Get-PeCategory $compName
        $it.SortIndex  = $idx
        $it.Size       = $total
        $it.FileCount  = $group.Count
        $it.BuildId    = $BuildId
        $it.Arch       = $Arch
        $it.Language   = $Language
        $it.Languages  = [string[]]@('neutral', $Language)
        $it.Containers = [string[]]@($group | ForEach-Object { [string]$_.ContainerCabName } | Select-Object -Unique)
        if ($script:OcDependencies.ContainsKey($compName)) { $it.Dependencies = [string[]]@($script:OcDependencies[$compName]) }
        $list.Add($it)
        $idx++
    }
    return ,$list.ToArray()
}



