# --- 2. Public API: catalog, languages and CDN resolution ---

function Get-WinPESupportedLanguages {
    <#
    .SYNOPSIS
        Returns the 38 language culture codes supported by WinPE_OCs.
    .EXAMPLE
        Get-WinPESupportedLanguages
    #>
    [CmdletBinding()]
    param()
    return $Script:SupportedWinPELanguages
}

function Get-WinPEOCBuildCatalog {
    <#
    .SYNOPSIS
        Returns the CDN, MSI and container details of every supported Windows 10 and Windows 11 build.
    .EXAMPLE
        Get-WinPEOCBuildCatalog -BuildId Win11_*
    #>
    [CmdletBinding()]
    param(
        [Parameter(Position = 0)]
        [string]$BuildId = '*'
    )

    $Script:WinPEBuildCatalog | Where-Object { $_.BuildId -like $BuildId }
}

function Get-WinPEOCFileMap {
    <#
    .SYNOPSIS
        Returns the quick table that maps the deterministic fil<MD5> ids inside the static container CABs
        to WinPE_OCs package names. (Use Get-WinPEMsiDatabaseIndex for the full 38-language index.)
    .EXAMPLE
        Get-WinPEOCFileMap -Architecture amd64 -ComponentName *WMI*,*PowerShell*
    #>
    [CmdletBinding()]
    param(
        [ValidateSet('amd64', 'x86')]
        [string]$Architecture = 'amd64',

        [string[]]$ComponentName = @('*')
    )

    $results = foreach ($entry in $Script:WinPEOCFileTable) {
        if ($entry.Arch -ne $Architecture) { continue }
        $matched = $false
        foreach ($pattern in $ComponentName) {
            if ($entry.Name -like $pattern) {
                $matched = $true
                break
            }
        }
        if ($matched) {
            [PSCustomObject]@{
                Architecture = $entry.Arch
                Component    = $entry.Name
                BaseFilHash  = $entry.BaseFil
                BaseRelPath  = $entry.RelPath
                LangFilHash  = $entry.LangFil
                LangRelPath  = $entry.LangRelPath
            }
        }
    }
    return $results
}

function Expand-WinPEBurnManifestFromExe {
    <#
    .SYNOPSIS
        Carves the MSCF cabinet (UX container) embedded in adkwinpesetup.exe / adksetup.exe without 7-Zip
        and returns the CDN DownloadRoot and the .msi / .cab package list from UserExperienceManifest.xml.
    .EXAMPLE
        Expand-WinPEBurnManifestFromExe -SetupExePath "C:\Temp\adkwinpesetup.exe"
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$SetupExePath
    )

    if (-not (Test-Path $SetupExePath)) {
        throw "Setup exe bulunamadi: $SetupExePath"
    }

    $bytes = [System.IO.File]::ReadAllBytes($SetupExePath)
    $cabOffset = -1
    $cabSize   = 0

    # Find the CFHEADER signature: 'M','S','C','F',0,0,0,0 with offset+24 == 3 and offset+25 == 1 (CAB v1.3)
    for ($i = 0; $i -lt ($bytes.Length - 36); $i++) {
        if ($bytes[$i] -eq 0x4D -and $bytes[$i+1] -eq 0x53 -and $bytes[$i+2] -eq 0x43 -and $bytes[$i+3] -eq 0x46 -and
            $bytes[$i+4] -eq 0x00 -and $bytes[$i+5] -eq 0x00 -and $bytes[$i+6] -eq 0x00 -and $bytes[$i+7] -eq 0x00 -and
            $bytes[$i+24] -eq 3 -and $bytes[$i+25] -eq 1) {
            $candidateSize = [System.BitConverter]::ToUInt32($bytes, $i + 8)
            if ($candidateSize -gt 1024 -and ($i + $candidateSize) -le $bytes.Length) {
                $cabOffset = $i
                $cabSize   = [int]$candidateSize
                break
            }
        }
    }

    if ($cabOffset -lt 0) {
        throw "Setup exe icinde gomulu MSCF UX Cabinet bulunamadi: $SetupExePath"
    }

    $tempDir = Join-Path $env:TEMP ("WinPE_UX_" + [guid]::NewGuid().ToString('N'))
    New-Item -Path $tempDir -ItemType Directory -Force | Out-Null
    $uxCabPath = Join-Path $tempDir 'ux.cab'

    try {
        $cabBytes = New-Object byte[] $cabSize
        [System.Array]::Copy($bytes, $cabOffset, $cabBytes, 0, $cabSize)
        [System.IO.File]::WriteAllBytes($uxCabPath, $cabBytes)

        & expand.exe $uxCabPath -F:* $tempDir | Out-Null

        $uxManifestPath = Join-Path $tempDir 'UserExperienceManifest.xml'
        $burnManifestPath = Join-Path $tempDir '0'

        $fwLinkUrl = $null
        $msiPayloads = [System.Collections.Generic.List[string]]::new()
        $cabPayloads = [System.Collections.Generic.List[string]]::new()

        foreach ($xmlFile in @($uxManifestPath, $burnManifestPath)) {
            if (Test-Path $xmlFile) {
                $rawXml = Get-Content -Path $xmlFile -Raw -Encoding UTF8
                if (-not $fwLinkUrl) {
                    $fwMatch = [regex]::Match($rawXml, 'https?://go\.microsoft\.com/fwlink/\?linkid=\d+', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
                    if ($fwMatch.Success) { $fwLinkUrl = $fwMatch.Value }
                }
                foreach ($m in [regex]::Matches($rawXml, 'Installers\\([^"<>]+\.msi)', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)) {
                    $val = $m.Groups[1].Value
                    if (-not $msiPayloads.Contains($val)) { $msiPayloads.Add($val) }
                }
                foreach ($m in [regex]::Matches($rawXml, 'Installers\\([0-9a-f]{32}\.cab)', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)) {
                    $val = $m.Groups[1].Value
                    if (-not $cabPayloads.Contains($val)) { $cabPayloads.Add($val) }
                }
            }
        }

        return [PSCustomObject]@{
            SetupExePath     = $SetupExePath
            CabOffset        = $cabOffset
            CabSize          = $cabSize
            DownloadRootFw   = $fwLinkUrl
            MsiPackages      = $msiPayloads
            CabContainers    = $cabPayloads
        }
    } finally {
        Remove-Item -Path $tempDir -Recurse -Force -ErrorAction SilentlyContinue
    }
}

# --- 2b. Source discovery: CDN mirrors, fwlink validation, MSI version check, local layout ---

function Get-WinPECurlPath {
    <#
    .SYNOPSIS
        Returns the path of curl.exe (included with Windows 10 1803+).
    #>
    [CmdletBinding()]
    param()

    if ($env:SystemRoot) {
        $sysCurl = Join-Path $env:SystemRoot 'System32\curl.exe'
        if (Test-Path -LiteralPath $sysCurl) { return $sysCurl }
    }
    $cmd = Get-Command -Name 'curl.exe', 'curl' -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($cmd) { return $cmd.Source }
    throw 'curl.exe bulunamadi (Windows 10 1803 veya ustu gerekir).'
}

function Invoke-WinPEHttpDownload {
    <#
    .SYNOPSIS
        Downloads a single file with curl.exe. Does not throw on failure; returns the HTTP status code and
        the curl exit code. An interrupted download never corrupts the target file (a .part file is used).
    .EXAMPLE
        Invoke-WinPEHttpDownload -Url 'https://download.microsoft.com/.../x.msi' -OutFile C:\Temp\x.msi
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Url,

        [Parameter(Mandatory = $true)]
        [string]$OutFile,

        [int]$TimeoutSeconds = 300
    )

    $ErrorActionPreference = 'Continue'
    $curl    = Get-WinPECurlPath
    $part    = "$OutFile.part"
    $errFile = "$OutFile.err"
    Remove-Item -LiteralPath $part, $errFile -Force -ErrorAction SilentlyContinue

    $encoded = $Url -replace ' ', '%20'
    $curlArgs = @('-sS', '-L', '-g', '--fail', '--retry', '2', '--connect-timeout', '30',
                  '--max-time', [string]$TimeoutSeconds, '--stderr', $errFile,
                  '-o', $part, '-w', '%{http_code}', $encoded)
    $code = ((& $curl @curlArgs) | Out-String).Trim()
    $exitCode = $LASTEXITCODE

    $errText = ''
    if (Test-Path -LiteralPath $errFile) {
        $errText = [string](Get-Content -LiteralPath $errFile -Raw -ErrorAction SilentlyContinue)
        Remove-Item -LiteralPath $errFile -Force -ErrorAction SilentlyContinue
    }

    $ok = ($exitCode -eq 0) -and (Test-Path -LiteralPath $part)
    if ($ok) {
        Move-Item -LiteralPath $part -Destination $OutFile -Force
    } else {
        Remove-Item -LiteralPath $part -Force -ErrorAction SilentlyContinue
    }

    $message = if ($code -match '^\d{3}$' -and $code -ne '000') {
        "HTTP $code"
    } else {
        ("curl hata kodu $exitCode " + $errText.Trim()).Trim()
    }

    return [PSCustomObject]@{
        Url        = $Url
        Success    = $ok
        StatusCode = $code
        ExitCode   = $exitCode
        Message    = $message
    }
}

function Get-WinPERemoteFileSize {
    <#
    .SYNOPSIS
        Returns the size (Content-Length) of a remote file using a HEAD request, or $null.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Url
    )

    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    } catch { }
    $resp = $null
    try {
        $req = [System.Net.HttpWebRequest]::Create(($Url -replace ' ', '%20'))
        $req.Method = 'HEAD'
        $req.AllowAutoRedirect = $true
        $req.Timeout = 30000
        $resp = $req.GetResponse()
        if ($resp.ContentLength -gt 0) { return [long]$resp.ContentLength }
        return $null
    } catch {
        Write-Verbose "Boyut alinamadi ($Url): $($_.Exception.Message)"
        return $null
    } finally {
        if ($null -ne $resp) { $resp.Close() }
    }
}

function ConvertTo-WinPEAdkBaseUrl {
    <#
    .SYNOPSIS
        Validates that an fwlink redirect target really is an ADK / WinPE add-on location and returns the
        root above its Installers folder; returns $null for an invalid target.
        (Some old fwlinks now point to a PDF, bing.com or MediaCreationTool.)
    .EXAMPLE
        ConvertTo-WinPEAdkBaseUrl -Location 'https://download.microsoft.com/download/<guid>/adkwinpeaddons/adkwinpesetup.exe'
    #>
    [CmdletBinding()]
    param(
        [string]$Location
    )

    if ([string]::IsNullOrWhiteSpace($Location)) { return $null }
    $pattern = '^(https?://download\.microsoft\.com/download/[^?#]*?/(?:adk|adkwinpeaddons)/)(?:adk(?:winpe)?setup\.exe)?(?:[?#].*)?$'
    $m = [regex]::Match($Location.Trim(), $pattern, [System.Text.RegularExpressions.RegexOptions]'IgnoreCase, CultureInvariant')
    if (-not $m.Success) { return $null }
    return ($m.Groups[1].Value -replace '^http://', 'https://')
}

function Resolve-WinPEFwLinkBase {
    <#
    .SYNOPSIS
        Resolves a go.microsoft.com fwlink (without following the redirect), validates that the target is an
        ADK / WinPE add-on location and returns the CDN root.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$FwLinkUrl
    )

    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    } catch { }

    $location = $null
    $resp = $null
    try {
        $req = [System.Net.HttpWebRequest]::Create($FwLinkUrl)
        $req.Method = 'HEAD'
        $req.AllowAutoRedirect = $false
        $req.Timeout = 30000
        $resp = $req.GetResponse()
        $location = $resp.Headers['Location']
    } catch [System.Net.WebException] {
        $errResp = $_.Exception.Response
        if ($null -ne $errResp) {
            $location = $errResp.Headers['Location']
            $errResp.Close()
        }
        if (-not $location) {
            throw "FwLink yonlendirmesi cozumlenemedi ($FwLinkUrl): $($_.Exception.Message)"
        }
    } finally {
        if ($null -ne $resp) { $resp.Close() }
    }

    if (-not $location) {
        throw "FwLink bir yonlendirme adresi dondurmedi: $FwLinkUrl"
    }
    $base = ConvertTo-WinPEAdkBaseUrl -Location $location
    if (-not $base) {
        throw "FwLink artik bir ADK / WinPE eklentisi konumuna yonlenmiyor: $FwLinkUrl -> $location"
    }
    return $base
}

function Get-WinPESourceTag {
    <#
    .SYNOPSIS
        Builds a short, stable tag for a CDN root (the first 8 characters of the GUID in the URL).
        Keeps cache file names from different sources apart.
    #>
    [CmdletBinding()]
    param(
        [string]$BaseUrl
    )

    $m = [regex]::Match([string]$BaseUrl, '([0-9a-f]{8})-[0-9a-f]{4}-[0-9a-f]{4}-', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if ($m.Success) { return $m.Groups[1].Value.ToLowerInvariant() }
    $clean = ([string]$BaseUrl -replace '[^A-Za-z0-9]', '').ToLowerInvariant()
    if ($clean.Length -gt 12) { $clean = $clean.Substring($clean.Length - 12) }
    return $clean
}

function Get-WinPEMsiProductVersion {
    <#
    .SYNOPSIS
        Reads ProductVersion from the Property table of an .msi file ($null if it cannot be read).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$MsiPath
    )

    $installer = $null; $db = $null; $view = $null; $rec = $null
    try {
        $installer = New-Object -ComObject WindowsInstaller.Installer
        $db   = $installer.GetType().InvokeMember('OpenDatabase', 'InvokeMethod', $null, $installer, @($MsiPath, 0))
        $view = $db.GetType().InvokeMember('OpenView', 'InvokeMethod', $null, $db, @('SELECT `Value` FROM `Property` WHERE `Property` = ''ProductVersion'''))
        $null = $view.GetType().InvokeMember('Execute', 'InvokeMethod', $null, $view, $null)
        $rec  = $view.GetType().InvokeMember('Fetch', 'InvokeMethod', $null, $view, $null)
        if ($null -eq $rec) { return $null }
        return [string]$rec.GetType().InvokeMember('StringData', 'GetProperty', $null, $rec, @(1))
    } catch {
        Write-Verbose "MSI surumu okunamadi ($MsiPath): $($_.Exception.Message)"
        return $null
    } finally {
        if ($null -ne $view) {
            try { $null = $view.GetType().InvokeMember('Close', 'InvokeMethod', $null, $view, $null) } catch { }
        }
        foreach ($comObj in @($rec, $view, $db, $installer)) {
            if ($null -ne $comObj) {
                try { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($comObj) } catch { }
            }
        }
    }
}

function Test-WinPEMsiBuildMatch {
    <#
    .SYNOPSIS
        Returns whether the build field of an MSI ProductVersion (e.g. 10.1.17763.x -> 17763) matches the
        catalog build. Returns $true when the version cannot be read (does not block).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        $BuildInfo,

        [string]$ProductVersion
    )

    $pv = $null
    if (-not [version]::TryParse([string]$ProductVersion, [ref]$pv)) { return $true }

    $bn = $null
    if (-not [version]::TryParse([string]$BuildInfo.BuildNumber, [ref]$bn)) { return $true }
    return ($pv.Build -eq $bn.Build)
}

function Get-WinPELocalInstallersMsi {
    <#
    .SYNOPSIS
        Finds the Installers folder and the WinPE .msi files of a local ADK layout
        (adksetup.exe / adkwinpesetup.exe /layout). The root of the layout can be given as well.
    .EXAMPLE
        Get-WinPELocalInstallersMsi -Path D:\ADK_1809_Layout -BuildInfo (Get-WinPEOCBuildCatalog Win10_1809)
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        $BuildInfo
    )

    if (-not (Test-Path -LiteralPath $Path -PathType Container)) {
        throw "Yerel klasor bulunamadi: $Path"
    }
    $dir = (Resolve-Path -LiteralPath $Path).ProviderPath
    $hasMsi = Get-ChildItem -LiteralPath $dir -Filter '*.msi' -File -ErrorAction SilentlyContinue | Select-Object -First 1
    $sub = Join-Path $dir 'Installers'
    if (-not $hasMsi -and (Test-Path -LiteralPath $sub -PathType Container)) {
        $dir = $sub
    }

    $found = [System.Collections.Generic.List[string]]::new()
    if ($BuildInfo -and $BuildInfo.MsiPackages) {
        foreach ($msiName in @($BuildInfo.MsiPackages)) {
            $candidate = Join-Path $dir $msiName
            if (Test-Path -LiteralPath $candidate -PathType Leaf) { $found.Add($candidate) }
        }
    }
    if ($found.Count -eq 0) {
        foreach ($f in @(Get-ChildItem -LiteralPath $dir -Filter 'Windows PE*.msi' -File -ErrorAction SilentlyContinue)) {
            $found.Add($f.FullName)
        }
    }
    if ($found.Count -eq 0) {
        throw "Klasorde WinPE .msi dosyasi bulunamadi: $dir (adksetup.exe /layout ile olusturulan Installers klasorunu secin)"
    }

    return [PSCustomObject]@{
        InstallersPath = $dir
        MsiFiles       = @($found)
    }
}

function Find-WinPEAddonSource {
    <#
    .SYNOPSIS
        Finds a working Microsoft CDN source for a build and downloads its MSI index files to the cache.
    .DESCRIPTION
        Tries the primary root of the catalog (CdnBaseUrl), then the mirrors (CdnMirrors), then the validated
        fwlink target. The ProductVersion of every downloaded MSI is compared with the selected build; sources
        that point to another ADK release are rejected. If no source works, a detailed error listing the tried
        URLs and HTTP status codes is thrown.
    .EXAMPLE
        Find-WinPEAddonSource -BuildId Win10_1809
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [string]$BuildId = 'Win11_22H2',

        [string]$CacheDirectory = (Join-Path $env:TEMP 'WinPE_MSI_Cache')
    )

    $build = Get-WinPEOCBuildCatalog -BuildId $BuildId | Select-Object -First 1
    if (-not $build) {
        throw "Belirtilen BuildId bulunamadi: $BuildId"
    }
    New-Item -Path $CacheDirectory -ItemType Directory -Force | Out-Null

    $bases = [System.Collections.Generic.List[string]]::new()
    foreach ($b in @(@($build.CdnBaseUrl) + @($build.CdnMirrors))) {
        if ([string]::IsNullOrWhiteSpace($b)) { continue }
        $norm = $b.Trim().TrimEnd('/') + '/'
        if (-not $bases.Contains($norm)) { $bases.Add($norm) }
    }

    $attempts = [System.Collections.Generic.List[string]]::new()
    $fwLinkTried = $false
    $i = 0
    while ($true) {
        if ($i -ge $bases.Count) {
            if ($fwLinkTried -or [string]::IsNullOrWhiteSpace($build.FwLinkUrl)) { break }
            $fwLinkTried = $true
            try {
                $fwBase = Resolve-WinPEFwLinkBase -FwLinkUrl $build.FwLinkUrl
            } catch {
                $attempts.Add("FwLink: $($_.Exception.Message)")
                break
            }
            if ($bases.Contains($fwBase)) { break }
            $bases.Add($fwBase)
        }

        $base = $bases[$i]
        $i++
        $tag = Get-WinPESourceTag -BaseUrl $base
        $msiFiles = [System.Collections.Generic.List[string]]::new()
        $productVersion = $null

        foreach ($msiName in @($build.MsiPackages)) {
            $msiUrl   = "${base}Installers/$msiName"
            $localMsi = Join-Path $CacheDirectory "$($build.BuildId)_${tag}_$msiName"
            $cached   = (Test-Path -LiteralPath $localMsi) -and ((Get-Item -LiteralPath $localMsi).Length -gt 10240)
            if (-not $cached) {
                Write-Verbose "MSI indeks veritabani indiriliyor: $msiUrl"
                $dl = Invoke-WinPEHttpDownload -Url $msiUrl -OutFile $localMsi
                if (-not $dl.Success) {
                    $attempts.Add("$($dl.Message)  $msiUrl")
                    continue
                }
                if ((Get-Item -LiteralPath $localMsi).Length -le 10240) {
                    $attempts.Add("Gecersiz (cok kucuk) dosya  $msiUrl")
                    Remove-Item -LiteralPath $localMsi -Force -ErrorAction SilentlyContinue
                    continue
                }
            }

            $pv = Get-WinPEMsiProductVersion -MsiPath $localMsi
            if (-not (Test-WinPEMsiBuildMatch -BuildInfo $build -ProductVersion $pv)) {
                $attempts.Add("Surum uyusmuyor ($pv, beklenen $($build.BuildNumber))  $msiUrl")
                continue
            }
            if (-not $productVersion) { $productVersion = $pv }
            $msiFiles.Add($localMsi)
        }

        if ($msiFiles.Count -gt 0) {
            return [PSCustomObject]@{
                BuildId        = $build.BuildId
                BaseUrl        = $base
                InstallersUrl  = "${base}Installers/"
                MsiFiles       = @($msiFiles)
                ProductVersion = $productVersion
                Attempts       = @($attempts)
            }
        }
    }

    $detail = if ($attempts.Count -gt 0) {
        ($attempts | ForEach-Object { "  - $_" }) -join "`r`n"
    } else {
        '  - (katalogda bu derleme icin adres tanimli degil)'
    }
    throw "Gecerli bir WinPE .msi indeks dosyasi indirilemedi ($($build.BuildId)).`r`nDenenen adresler:`r`n$detail"
}

function Resolve-WinPEAddonCdnUrl {
    <#
    .SYNOPSIS
        Resolves the Microsoft CDN Installers root URL (and the MSI / CAB links) for a Windows build id or a
        Microsoft fwlink URL.
    .EXAMPLE
        Resolve-WinPEAddonCdnUrl -BuildId Win11_24H2 -ForceLiveRedirect
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false, Position = 0)]
        [string]$BuildId = 'Win11_22H2',

        [Parameter(Mandatory = $false)]
        [string]$FwLinkUrl,

        [Parameter(Mandatory = $false)]
        [string]$LocalSetupExePath,

        [switch]$ForceLiveRedirect
    )

    $buildObj = $null
    if (-not $FwLinkUrl -and -not $LocalSetupExePath) {
        $buildObj = Get-WinPEOCBuildCatalog -BuildId $BuildId | Select-Object -First 1
        if (-not $buildObj) {
            throw "Belirtilen BuildId bulunamadi: $BuildId"
        }
        if ($buildObj.CdnBaseUrl -and -not $ForceLiveRedirect) {
            $base = $buildObj.CdnBaseUrl.TrimEnd('/') + '/'
            return [PSCustomObject]@{
                BuildId             = $buildObj.BuildId
                OSName              = $buildObj.OSName
                BuildNumber         = $buildObj.BuildNumber
                CdnBaseUrl          = $base
                MirrorBaseUrls      = @($buildObj.CdnMirrors | Where-Object { $_ } | ForEach-Object { $_.TrimEnd('/') + '/' })
                InstallersUrl       = "${base}Installers/"
                MsiPackageUrls      = @($buildObj.MsiPackages | ForEach-Object { "${base}Installers/$_" })
                Amd64BaseCabUrl     = "${base}Installers/$($buildObj.Amd64BaseCab)"
                Amd64EnUsCabUrl     = "${base}Installers/$($buildObj.Amd64EnUsCab)"
                X86BaseCabUrl       = if ($buildObj.X86BaseCab) { "${base}Installers/$($buildObj.X86BaseCab)" } else { $null }
                ResolutionSource    = 'CatalogCache'
            }
        }
        $FwLinkUrl = $buildObj.FwLinkUrl
    }

    if ($LocalSetupExePath) {
        $burnInfo = Expand-WinPEBurnManifestFromExe -SetupExePath $LocalSetupExePath
        if ($burnInfo.DownloadRootFw) {
            $FwLinkUrl = $burnInfo.DownloadRootFw
        } else {
            throw "adkwinpesetup.exe icinde fwlink DownloadRoot bulunamadi."
        }
    }

    if (-not $FwLinkUrl) {
        throw "Bu derleme icin gecerli bir fwlink tanimli degil: $BuildId"
    }
    # Validate the target: redirects that are not ADK / WinPE add-on locations (PDF, bing.com, ...) are rejected.
    $resolvedBase = Resolve-WinPEFwLinkBase -FwLinkUrl $FwLinkUrl

    $msiList   = if ($buildObj -and $buildObj.MsiPackages) { $buildObj.MsiPackages } else { $Script:WinPEOptionalPackagesMsiNames }
    $amd64Base = if ($buildObj) { $buildObj.Amd64BaseCab } else { '9722214af0ab8aa9dffb6cfdafd937b7.cab' }
    $amd64Lang = if ($buildObj) { $buildObj.Amd64EnUsCab } else { '3ffff92a2c7e8b2f1a6e85afeaa027ca.cab' }
    $x86Base   = if ($buildObj) { $buildObj.X86BaseCab }   else { 'aa25d18a5fcce134b0b89fb003ec99ff.cab' }

    return [PSCustomObject]@{
        BuildId             = if ($buildObj) { $buildObj.BuildId } else { 'Custom' }
        OSName              = if ($buildObj) { $buildObj.OSName } else { 'Custom FwLink Build' }
        BuildNumber         = if ($buildObj) { $buildObj.BuildNumber } else { 'Unknown' }
        CdnBaseUrl          = $resolvedBase
        InstallersUrl       = "${resolvedBase}Installers/"
        MsiPackageUrls      = @($msiList | ForEach-Object { "${resolvedBase}Installers/$_" })
        Amd64BaseCabUrl     = "${resolvedBase}Installers/$amd64Base"
        Amd64EnUsCabUrl     = "${resolvedBase}Installers/$amd64Lang"
        X86BaseCabUrl       = if ($x86Base) { "${resolvedBase}Installers/$x86Base" } else { $null }
        ResolutionSource    = 'LiveHttp302'
    }
}

# --- 3. MSI database indexer for all languages (Directory / Component / File / Media) ---

function ConvertFrom-WinPEMsiTables {
    <#
    .SYNOPSIS
        Joins the MSI Directory, Component, Media and File table rows and resolves the container .cab name,
        fil<MD5> id and target path of every WinPE_OCs package in all 38 languages (tr-tr, de-de, en-us, ...).
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$DirectoryRows,

        [Parameter(Mandatory = $true)]
        [hashtable]$ComponentDirMap,

        [Parameter(Mandatory = $true)]
        [array]$MediaRows,

        [Parameter(Mandatory = $true)]
        [array]$FileRows,

        [string]$InstallersBaseUrl = '',

        # Folder holding the container .cab files when working from a local ADK layout
        [string]$LocalCabDirectory = '',

        [string]$MsiProductVersion = ''
    )

    # 1. Build the complete folder tree from the Directory table
    $resolvedPaths = @{}
    function Resolve-DirPath ([string]$dirKey) {
        if (-not $dirKey -or -not $DirectoryRows.ContainsKey($dirKey)) { return '' }
        if ($resolvedPaths.ContainsKey($dirKey)) { return $resolvedPaths[$dirKey] }

        $row = $DirectoryRows[$dirKey]
        $parentKey = $row.Parent
        $defaultDir = $row.DefaultDir

        # MSI DefaultDir format: [targetshort|]targetlong[:[sourceshort|]sourcelong]
        $targetSegment = ($defaultDir -split ':')[0]
        if ($targetSegment -match '\|') {
            $targetSegment = ($targetSegment -split '\|')[-1]
        }

        $parentPath = if ($parentKey -and $parentKey -ne $dirKey) { Resolve-DirPath $parentKey } else { '' }
        $fullPath = if ($targetSegment -eq '.' -or $targetSegment -eq 'SourceDir' -or $targetSegment -eq 'TARGETDIR' -or [string]::IsNullOrWhiteSpace($targetSegment)) {
            $parentPath
        } elseif ($parentPath) {
            "$parentPath\$targetSegment"
        } else {
            $targetSegment
        }

        $resolvedPaths[$dirKey] = $fullPath
        return $fullPath
    }

    foreach ($k in $DirectoryRows.Keys) {
        $null = Resolve-DirPath $k
    }

    # 2. Sort the Media table by LastSequence
    $sortedMedia = @($MediaRows | Sort-Object { [int]$_.LastSequence })

    # 3. Map every WinPE_OCs file of the File table
    $results = [System.Collections.Generic.List[PSCustomObject]]::new()
    $baseUrlClean = if ($InstallersBaseUrl) { $InstallersBaseUrl.TrimEnd('/') + '/' } else { '' }

    foreach ($f in $FileRows) {
        $compId = $f.Component
        if (-not $ComponentDirMap.ContainsKey($compId)) { continue }

        $dirId = $ComponentDirMap[$compId]
        $dirPath = $resolvedPaths[$dirId]
        if ($dirPath -notmatch 'WinPE_OCs') { continue }

        $longFileName = ($f.FileName -split '\|')[-1]
        if ($longFileName -notmatch '\.cab$') { continue }

        # Find the external container .cab that covers the sequence number
        $seq = [int]$f.Sequence
        $cabName = $null
        foreach ($m in $sortedMedia) {
            if ($seq -le [int]$m.LastSequence) {
                $cabName = ($m.Cabinet -replace '^#', '')
                break
            }
        }

        # Detect the architecture (amd64, x86, arm64, arm) and the language (neutral or xx-xx)
        $arch = if ($dirPath -match '\\(amd64|x86|arm64|arm)\\WinPE_OCs') {
            $Matches[1].ToLowerInvariant()
        } else {
            'amd64'
        }

        $lang = 'neutral'
        $relWinPEPath = "WinPE_OCs\$longFileName"
        if ($dirPath -match 'WinPE_OCs\\([a-z]{2}-[a-z]{2,4}(?:-[a-z]{2})?)$') {
            $lang = $Matches[1].ToLowerInvariant()
            $relWinPEPath = "WinPE_OCs\$lang\$longFileName"
        }

        $compBaseName = [System.IO.Path]::GetFileNameWithoutExtension($longFileName)
        if ($lang -ne 'neutral') {
            $compBaseName = $compBaseName -replace ('_' + [regex]::Escape($lang) + '$'), ''
        }

        $results.Add([PSCustomObject]@{
            Architecture     = $arch
            Language         = $lang
            IsLanguagePack   = ($lang -ne 'neutral')
            ComponentName    = $compBaseName
            FileName         = $longFileName
            RelativePath     = $relWinPEPath
            FilHashId        = $f.File
            Sequence         = $seq
            FileSize         = [long]$f.FileSize
            ContainerCabName = $cabName
            ContainerCabUrl  = if ($baseUrlClean -and $cabName) { "${baseUrlClean}${cabName}" } else { $null }
            ContainerCabPath = if ($LocalCabDirectory -and $cabName) { Join-Path $LocalCabDirectory $cabName } else { $null }
            ContainerCabSize = $null
            MsiProductVersion = if ($MsiProductVersion) { $MsiProductVersion } else { $null }
        })
    }

    return $results
}

function Get-WinPEMsiDatabaseIndex {
    <#
    .SYNOPSIS
        Downloads the Windows PE Optional Packages .msi database (~1 MB) from the Microsoft CDN (or opens a
        local .msi), runs SQL queries through the WindowsInstaller.Installer COM object and builds the
        container .cab and fil<MD5> map for all 38 languages (tr-tr, de-de, fr-fr, en-us, ...).
    .PARAMETER LocalInstallersPath
        Installers folder (or root) of a local ADK layout (adksetup.exe /layout) to use instead of the CDN.
        The MSIs are read from this folder and ContainerCabPath of every record points to the local container
        .cab, which allows working offline.
    .PARAMETER Online
        Ignore the embedded index: download the MSI from the CDN and resolve it again with WindowsInstaller COM.
        (By default the embedded index is used when available; no MSI is downloaded and results are instant.)
    .EXAMPLE
        Get-WinPEMsiDatabaseIndex -BuildId Win11_22H2 -Language tr-tr,de-de,en-us
        Get-WinPEMsiDatabaseIndex -BuildId Win11_24H2 -Language * -Architecture amd64
        Get-WinPEMsiDatabaseIndex -BuildId Win10_1809 -LocalInstallersPath D:\ADK1809\Installers
        Get-WinPEMsiDatabaseIndex -BuildId Win11_26H2 -Online
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [string]$BuildId = 'Win11_22H2',

        [Parameter(Mandatory = $false)]
        [string[]]$MsiPath,

        [Parameter(Mandatory = $false)]
        [string]$LocalInstallersPath,

        [ValidateSet('All', 'amd64', 'x86', 'arm64', 'arm')]
        [string]$Architecture = 'All',

        [string[]]$Language = @('*'),

        [string[]]$ComponentName = @('*'),

        [string]$CacheDirectory = (Join-Path $env:TEMP 'WinPE_MSI_Cache'),

        [switch]$Online
    )

    # Architecture, language and component filter (shared by the embedded and MSI paths)
    $applyFilter = {
        param($items)
        foreach ($item in $items) {
            if ($Architecture -ne 'All' -and $item.Architecture -ne $Architecture) { continue }

            $langMatch = $false
            foreach ($langPattern in $Language) {
                if ($langPattern -eq '*' -or $item.Language -like $langPattern) {
                    $langMatch = $true
                    break
                }
            }
            if (-not $langMatch) { continue }

            $compMatch = $false
            foreach ($compPattern in $ComponentName) {
                if ($compPattern -eq '*' -or $item.ComponentName -like $compPattern -or $item.FileName -like $compPattern) {
                    $compMatch = $true
                    break
                }
            }
            if ($compMatch) { $item }
        }
    }

    # Embedded index: no MSI download, no COM (unless a local folder, -MsiPath or -Online is given)
    if (-not $MsiPath -and -not $LocalInstallersPath -and -not $Online -and (Test-WinPEEmbeddedIndex -BuildId $BuildId)) {
        return (& $applyFilter (Get-WinPEEmbeddedIndex -BuildId $BuildId))
    }

    $installersBaseUrl = ''
    $localCabDirectory = ''
    $localMsiFiles = [System.Collections.Generic.List[string]]::new()

    if ($LocalInstallersPath) {
        $buildInfo = Get-WinPEOCBuildCatalog -BuildId $BuildId | Select-Object -First 1
        $localSource = Get-WinPELocalInstallersMsi -Path $LocalInstallersPath -BuildInfo $buildInfo
        $localCabDirectory = $localSource.InstallersPath
        if (-not $MsiPath) {
            foreach ($m in $localSource.MsiFiles) { $localMsiFiles.Add($m) }
        }
    }

    if ($MsiPath) {
        foreach ($p in $MsiPath) {
            if (Test-Path -LiteralPath $p) { $localMsiFiles.Add((Resolve-Path -LiteralPath $p).ProviderPath) }
        }
    } elseif (-not $LocalInstallersPath) {
        # Primary root -> mirrors -> validated fwlink; throws a detailed error on failure
        $source = Find-WinPEAddonSource -BuildId $BuildId -CacheDirectory $CacheDirectory
        $installersBaseUrl = $source.InstallersUrl
        foreach ($m in $source.MsiFiles) { $localMsiFiles.Add($m) }
    }

    if ($localMsiFiles.Count -eq 0) {
        throw "Incelenecek gecerli bir WinPE .msi indeks dosyasi bulunamadi."
    }

    $installer = New-Object -ComObject WindowsInstaller.Installer
    $allIndexedItems = [System.Collections.Generic.List[PSCustomObject]]::new()

    foreach ($msiFile in $localMsiFiles) {
        $db = $installer.GetType().InvokeMember('OpenDatabase', 'InvokeMethod', $null, $installer, @($msiFile, 0))

        function Invoke-MsiQuery ($database, [string]$sql, [string[]]$columns) {
            $view = $database.GetType().InvokeMember('OpenView', 'InvokeMethod', $null, $database, @($sql))
            $null = $view.GetType().InvokeMember('Execute', 'InvokeMethod', $null, $view, $null)
            $rows = [System.Collections.Generic.List[hashtable]]::new()
            while ($true) {
                $rec = $view.GetType().InvokeMember('Fetch', 'InvokeMethod', $null, $view, $null)
                if ($null -eq $rec) { break }
                $rowHash = @{}
                for ($c = 0; $c -lt $columns.Count; $c++) {
                    $colIdx = $c + 1
                    $val = $rec.GetType().InvokeMember('StringData', 'GetProperty', $null, $rec, @($colIdx))
                    $rowHash[$columns[$c]] = $val
                }
                $rows.Add($rowHash)
            }
            $null = $view.GetType().InvokeMember('Close', 'InvokeMethod', $null, $view, $null)
            return $rows
        }

        $dirTable  = Invoke-MsiQuery -database $db -sql 'SELECT `Directory`, `Directory_Parent`, `DefaultDir` FROM `Directory`' -columns @('Directory', 'Parent', 'DefaultDir')
        $compTable = Invoke-MsiQuery -database $db -sql 'SELECT `Component`, `Directory_` FROM `Component`' -columns @('Component', 'Directory')
        $medTable  = Invoke-MsiQuery -database $db -sql 'SELECT `DiskId`, `LastSequence`, `Cabinet` FROM `Media`' -columns @('DiskId', 'LastSequence', 'Cabinet')
        $fileTable = Invoke-MsiQuery -database $db -sql 'SELECT `File`, `Component_`, `FileName`, `FileSize`, `Sequence` FROM `File`' -columns @('File', 'Component', 'FileName', 'FileSize', 'Sequence')
        $propTable = @(Invoke-MsiQuery -database $db -sql 'SELECT `Value` FROM `Property` WHERE `Property` = ''ProductVersion''' -columns @('Value'))
        $msiVersion = if ($propTable.Count -gt 0) { [string]$propTable[0].Value } else { '' }

        $dirHash = @{}
        foreach ($r in $dirTable) { $dirHash[$r.Directory] = $r }

        $compHash = @{}
        foreach ($r in $compTable) { $compHash[$r.Component] = $r.Directory }

        $mapped = ConvertFrom-WinPEMsiTables `
            -DirectoryRows $dirHash `
            -ComponentDirMap $compHash `
            -MediaRows $medTable `
            -FileRows $fileTable `
            -InstallersBaseUrl $installersBaseUrl `
            -LocalCabDirectory $localCabDirectory `
            -MsiProductVersion $msiVersion

        foreach ($item in $mapped) {
            $allIndexedItems.Add($item)
        }
    }

    return (& $applyFilter $allIndexedItems)
}

# --- 3b. Embedded index: instant package list without downloading the MSI ---
# The package list of every build (container .cab URL, fil<MD5> id, size) is stored as plain text in
# $Script:WinPEEmbeddedFilTable / $Script:WinPEEmbeddedBuildData at the end of the script.
# fil ids are derived from the file path and are identical in every ADK release, so they live in one
# shared table; the build blocks only carry sizes and container numbers.

function ConvertTo-WinPEEmbeddedIndexData {
    <#
    .SYNOPSIS
        Converts per-build WinPE_OCs index records into the plain-text format embedded in the script.
    .DESCRIPTION
        Format (v2):
          FilTable : one line per arch|language block: "arch|lang|Component:fil32hex,Component:fil32hex,..."
          BuildData: a "@BuildId|MsiVersion|InstallersUrl|container0.cab:size,container1.cab:size,..." header followed
                     by one "arch|lang|containerNo|size,size,-,..." line per block. Sizes follow the component
                     order of FilTable; '-' marks a package that does not exist in that build.
        File name and relative path are derived from the component name (neutral: Name.cab, language:
        Name_lang.cab, lp: lp.cab); a record that breaks this rule makes the conversion fail, so data is
        never corrupted silently.
    .OUTPUTS
        FilTable, BuildData and the complete assignment text to paste into the script (Text).
    #>
    [CmdletBinding()]
    param(
        # Ordered dictionary: BuildId -> @{ ProductVersion; InstallersUrl; Items (Get-WinPEMsiDatabaseIndex output);
        #                ContainerSizes (optional: container .cab name -> bytes) }
        [Parameter(Mandatory = $true)]
        [System.Collections.IDictionary]$Builds
    )

    $namePattern = '^[A-Za-z0-9._-]+$'
    $blocks = @{}
    foreach ($bid in $Builds.Keys) {
        foreach ($it in $Builds[$bid].Items) {
            $key = "$($it.Architecture)|$($it.Language)"
            if ($key -notmatch '^[a-z0-9]+\|[a-z0-9-]+$') { throw "Beklenmeyen mimari/dil: $key" }
            if ([string]$it.ComponentName -cnotmatch $namePattern) { throw "Gecersiz bilesen adi: $($it.ComponentName)" }
            $fil = ([string]$it.FilHashId) -replace '^fil', ''
            if ($fil -notmatch '^[0-9a-f]{32}$') { throw "Beklenmeyen fil kimligi: $($it.FilHashId)" }
            $isLang = $it.Language -ne 'neutral'
            $expectedName = if (-not $isLang) { "$($it.ComponentName).cab" } elseif ($it.ComponentName -ceq 'lp') { 'lp.cab' } else { "$($it.ComponentName)_$($it.Language).cab" }
            if ($expectedName -cne $it.FileName) { throw "Dosya adi kurala uymuyor: $($it.FileName) ($bid)" }
            if (-not $blocks.ContainsKey($key)) { $blocks[$key] = @{} }
            $prev = $blocks[$key][$it.ComponentName]
            if ($prev -and $prev -ne $fil) { throw "Ayni paket icin farkli fil kimligi: $key $($it.ComponentName)" }
            $blocks[$key][$it.ComponentName] = $fil
        }
    }

    $blockKeys = [string[]]@($blocks.Keys)
    [Array]::Sort($blockKeys, [StringComparer]::Ordinal)
    $order = @{}
    $filLines = [System.Collections.Generic.List[string]]::new()
    foreach ($key in $blockKeys) {
        $names = [string[]]@($blocks[$key].Keys)
        [Array]::Sort($names, [StringComparer]::Ordinal)
        $order[$key] = $names
        $filLines.Add($key + '|' + (($names | ForEach-Object { $_ + ':' + $blocks[$key][$_] }) -join ','))
    }

    $buildLines = [System.Collections.Generic.List[string]]::new()
    foreach ($bid in $Builds.Keys) {
        $b = $Builds[$bid]
        if ("$bid$($b.ProductVersion)$($b.InstallersUrl)" -match "[|,'\s]") { throw "Derleme basligi ayirici karakter iceriyor: $bid" }
        $cabs = [string[]]@($b.Items | ForEach-Object { [string]$_.ContainerCabName } | Select-Object -Unique)
        [Array]::Sort($cabs, [StringComparer]::Ordinal)
        $cabIndex = @{}
        for ($i = 0; $i -lt $cabs.Count; $i++) { $cabIndex[$cabs[$i]] = $i }
        $cabTokens = foreach ($c in $cabs) {
            $sz = if ($b.ContainerSizes) { $b.ContainerSizes[$c] } else { $null }
            if ($sz) { "${c}:$([long]$sz)" } else { $c }
        }
        $buildLines.Add("@$bid|$($b.ProductVersion)|$($b.InstallersUrl)|$(@($cabTokens) -join ',')")

        $byBlock = @{}
        foreach ($it in $b.Items) {
            $key = "$($it.Architecture)|$($it.Language)"
            if (-not $byBlock.ContainsKey($key)) {
                $byBlock[$key] = @{ Cab = [string]$it.ContainerCabName; Sizes = @{} }
            } elseif ($byBlock[$key].Cab -ne $it.ContainerCabName) {
                throw "Ayni blokta birden fazla konteyner: $bid $key"
            }
            if ($byBlock[$key].Sizes.ContainsKey($it.ComponentName)) { throw "Yinelenen paket: $bid $key $($it.ComponentName)" }
            $byBlock[$key].Sizes[$it.ComponentName] = [long]$it.FileSize
        }
        $keys = [string[]]@($byBlock.Keys)
        [Array]::Sort($keys, [StringComparer]::Ordinal)
        foreach ($key in $keys) {
            $vals = @(foreach ($n in $order[$key]) {
                    if ($byBlock[$key].Sizes.ContainsKey($n)) { [string]$byBlock[$key].Sizes[$n] } else { '-' }
                })
            $last = $vals.Count - 1
            while ($last -gt 0 -and $vals[$last] -eq '-') { $last-- }
            $buildLines.Add("$key|$($cabIndex[$byBlock[$key].Cab])|$($vals[0..$last] -join ',')")
        }
    }

    $filText   = $filLines -join "`r`n"
    $buildText = $buildLines -join "`r`n"
    $stamp = Get-Date -Format 'yyyy-MM-dd'
    $text = "# Embedded index data (format v2) - generated by Export-WinPEEmbeddedIndexData: $stamp`r`n" +
            "# Builds: $(@($Builds.Keys) -join ', ')`r`n" +
            "`$Script:WinPEEmbeddedFilTable = '`r`n$filText`r`n'`r`n" +
            "`$Script:WinPEEmbeddedBuildData = '`r`n$buildText`r`n'"

    return [PSCustomObject]@{
        FilTable  = $filText
        BuildData = $buildText
        Text      = $text
    }
}

function Get-WinPEEmbeddedIndexData {
    <#
    .SYNOPSIS
        Parses the embedded index text once and caches it for the session (internal).
    #>
    [CmdletBinding()]
    param()

    if ($null -ne $Script:WinPEEmbeddedIndexCache) { return $Script:WinPEEmbeddedIndexCache }

    $blocks = @{}
    foreach ($raw in ([string]$Script:WinPEEmbeddedFilTable -split "`r?`n")) {
        $line = $raw.Trim()
        if (-not $line -or $line.StartsWith('#')) { continue }
        $parts = $line.Split([char[]]@('|'), 3)
        if ($parts.Count -lt 3) { continue }
        $names = [System.Collections.Generic.List[string]]::new()
        $fils  = [System.Collections.Generic.List[string]]::new()
        foreach ($pair in $parts[2].Split(',')) {
            $kv = $pair.Split(':')
            $names.Add($kv[0])
            $fils.Add('fil' + $kv[1])
        }
        $blocks["$($parts[0])|$($parts[1])"] = [PSCustomObject]@{ Names = $names.ToArray(); Fils = $fils.ToArray() }
    }

    $builds = @{}
    $current = $null
    foreach ($raw in ([string]$Script:WinPEEmbeddedBuildData -split "`r?`n")) {
        $line = $raw.Trim()
        if (-not $line -or $line.StartsWith('#')) { continue }
        if ($line.StartsWith('@')) {
            $h = $line.Substring(1).Split('|')
            if ($h.Count -lt 4) { $current = $null; continue }
            $current = [PSCustomObject]@{
                BuildId        = $h[0]
                ProductVersion = $h[1]
                InstallersUrl  = $h[2]
                Cabs           = @($h[3].Split(',') | ForEach-Object { ($_ -split ':', 2)[0] })
                CabSizes       = @($h[3].Split(',') | ForEach-Object { $t = $_ -split ':', 2; if ($t.Count -gt 1 -and $t[1]) { [long]$t[1] } else { $null } })
                Lines          = [System.Collections.Generic.List[string]]::new()
            }
            $builds[$h[0]] = $current
        } elseif ($null -ne $current) {
            $current.Lines.Add($line)
        }
    }

    $Script:WinPEEmbeddedIndexCache = [PSCustomObject]@{ Blocks = $blocks; Builds = $builds }
    return $Script:WinPEEmbeddedIndexCache
}

function Test-WinPEEmbeddedIndex {
    <#
    .SYNOPSIS
        Returns whether the script contains an embedded index for the given build.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BuildId
    )
    return [bool](Get-WinPEEmbeddedIndexData).Builds.ContainsKey($BuildId)
}

function Get-WinPEEmbeddedIndex {
    <#
    .SYNOPSIS
        Returns every WinPE_OCs package of a build from the embedded index (without downloading the MSI).
        The output has the same fields as Get-WinPEMsiDatabaseIndex.
    .EXAMPLE
        Get-WinPEEmbeddedIndex -BuildId Win11_22H2 | Where-Object Language -eq 'tr-tr'
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BuildId
    )

    $data  = Get-WinPEEmbeddedIndexData
    $build = $data.Builds[$BuildId]
    if (-not $build) { return }

    $results = [System.Collections.Generic.List[PSCustomObject]]::new()
    foreach ($line in $build.Lines) {
        $p = $line.Split('|')
        if ($p.Count -lt 4) { continue }
        $arch   = $p[0]
        $lang   = $p[1]
        $cab    = $build.Cabs[[int]$p[2]]
        $cabSize = $build.CabSizes[[int]$p[2]]
        $block  = $data.Blocks["$arch|$lang"]
        if (-not $block) { throw "Gomulu indeks tutarsiz: '$arch|$lang' blogu fil tablosunda yok ($BuildId)." }
        $isLang = $lang -ne 'neutral'
        $cabUrl = "$($build.InstallersUrl)$cab"
        $sizes  = $p[3].Split(',')
        for ($i = 0; $i -lt $sizes.Count; $i++) {
            if ($sizes[$i] -eq '-' -or $sizes[$i] -eq '') { continue }
            $comp = $block.Names[$i]
            $fileName = if (-not $isLang) { "$comp.cab" } elseif ($comp -ceq 'lp') { 'lp.cab' } else { "${comp}_$lang.cab" }
            $results.Add([PSCustomObject]@{
                Architecture      = $arch
                Language          = $lang
                IsLanguagePack    = $isLang
                ComponentName     = $comp
                FileName          = $fileName
                RelativePath      = if ($isLang) { "WinPE_OCs\$lang\$fileName" } else { "WinPE_OCs\$fileName" }
                FilHashId         = $block.Fils[$i]
                Sequence          = $null
                FileSize          = [long]$sizes[$i]
                ContainerCabName  = $cab
                ContainerCabUrl   = $cabUrl
                ContainerCabPath  = $null
                ContainerCabSize  = $cabSize
                MsiProductVersion = $build.ProductVersion
            })
        }
    }
    return $results
}

function Export-WinPEEmbeddedIndexData {
    <#
    .SYNOPSIS
        Regenerates the embedded index data from the MSI files on the Microsoft CDN (Windows; requires COM).
    .DESCRIPTION
        Downloads and resolves the MSI of every catalog build and produces the text that replaces the
        $Script:WinPEEmbeddedFilTable / $Script:WinPEEmbeddedBuildData assignments in the script.
        Use it after adding a new ADK release to the catalog.
    .EXAMPLE
        Export-WinPEEmbeddedIndexData -Path C:\Temp\WinPEEmbeddedIndex.txt
    #>
    [CmdletBinding()]
    param(
        [string[]]$BuildId,

        [string]$Path
    )

    if (-not $BuildId) {
        $BuildId = @(Get-WinPEOCBuildCatalog | ForEach-Object { $_.BuildId })
    }
    $builds = [ordered]@{}
    foreach ($id in $BuildId) {
        Write-Verbose "$id indeksleniyor (MSI indiriliyor)..."
        $items = @(Get-WinPEMsiDatabaseIndex -BuildId $id -Online -Architecture All -Language '*')
        if ($items.Count -eq 0) {
            Write-Warning "$id icin kayit bulunamadi, atlandi."
            continue
        }
        $sizes = @{}
        foreach ($u in @($items | ForEach-Object { $_.ContainerCabUrl } | Select-Object -Unique)) {
            $len = Get-WinPERemoteFileSize -Url $u
            if ($len) { $sizes[($u -split '/')[-1]] = $len }
        }
        $builds[$id] = @{
            ProductVersion = [string]$items[0].MsiProductVersion
            InstallersUrl  = ([string]$items[0].ContainerCabUrl -replace '[^/]+$', '')
            ContainerSizes = $sizes
            Items          = $items
        }
    }

    $data = ConvertTo-WinPEEmbeddedIndexData -Builds $builds
    if ($Path) {
        Set-Content -LiteralPath $Path -Value $data.Text -Encoding ASCII
        return (Get-Item -LiteralPath $Path)
    }
    return $data.Text
}

function Get-MacriumWinPEManifest {
    <#
    .SYNOPSIS
        Parses the Macrium Reflect getfeaturelist.asp manifest (live URL or local file) as XML and returns the
        WinPE_OCs containers, the fil<Hash> mappings and the matching WinPE version.
    .DESCRIPTION
        Manifest layout: <feature releaseVer=.. winBuild=..> -> <component> -> <file id=..> records.
        Every <file> holds a container .cab URL (url), the byte range Macrium downloads (range) and a list of
        <extract_item> entries (source_filename = fil<MD5>, extract_path = target path).
        Note: the 1507 and 1511 URLs in the manifest point to old locations Microsoft has removed (HTTP 404).
        Macrium hosts only the PE 3/4/5 (Windows 7 / 8 / 8.1) components on its own servers.
    .EXAMPLE
        Get-MacriumWinPEManifest -MicrosoftCdnOnly | Where-Object WinBuild -eq '14393'
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [string]$ManifestUrl = 'https://updates.macrium.com/reflect/v8/getfeaturelist.asp',

        [Parameter(Mandatory = $false)]
        [string]$ManifestPath,

        [ValidateSet('All', 'amd64', 'x86')]
        [string]$Architecture = 'All',

        [switch]$MicrosoftCdnOnly
    )

    if ($ManifestPath) {
        if (-not (Test-Path -LiteralPath $ManifestPath)) {
            throw "Belirtilen manifest dosyasi bulunamadi: $ManifestPath"
        }
        $content = Get-Content -LiteralPath $ManifestPath -Raw -Encoding UTF8
    } else {
        try {
            [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
        } catch { }
        $resp = Invoke-WebRequest -Uri $ManifestUrl -UseBasicParsing
        $content = $resp.Content
        if ($content -is [byte[]]) { $content = [System.Text.Encoding]::UTF8.GetString($content) }
    }

    # Read as XML: source_filename and extract_path are separate elements in the manifest.
    $xml = New-Object System.Xml.XmlDocument
    $xml.XmlResolver = $null
    try {
        $xml.LoadXml(([string]$content).TrimStart([char]0xFEFF).Trim())
    } catch {
        throw "Macrium manifesti XML olarak okunamadi: $($_.Exception.Message)"
    }
    $rootNode = $xml.DocumentElement

    # WinPE version info: <feature id="pe10_1607" releaseVer="1607" winBuild="14393" ...>
    $featureInfo = @{}
    foreach ($fe in $rootNode.SelectNodes('feature[@releaseVer]')) {
        $featureInfo[$fe.GetAttribute('id')] = [PSCustomObject]@{
            Release  = $fe.GetAttribute('releaseVer')
            WinBuild = $fe.GetAttribute('winBuild')
        }
    }

    $parsedEntries = [System.Collections.Generic.List[PSCustomObject]]::new()

    foreach ($fileNode in $rootNode.SelectNodes('file')) {
        $urlNode = $fileNode.SelectSingleNode('url')
        $cabUrl  = if ($urlNode) { $urlNode.InnerText.Trim() } else { '' }
        if ($cabUrl -notmatch '^https?://') { continue }
        if ($MicrosoftCdnOnly -and $cabUrl -notmatch '^https?://download\.microsoft\.com/') { continue }

        $items = @($fileNode.SelectNodes('.//extract_item') | Where-Object {
                $p = $_.SelectSingleNode('extract_path')
                $p -and $p.InnerText.Trim() -match '^WinPE_OCs\\'
            })
        if ($items.Count -eq 0) { continue }

        $fileId   = $fileNode.GetAttribute('id')
        $saveNode = $fileNode.SelectSingleNode('savepath')
        $kitPath  = if ($saveNode) { $saveNode.InnerText.Trim().TrimEnd('\') } else { '' }
        if (-not $kitPath) { $kitPath = 'Unknown' }

        $detectedArch = if ($kitPath -match '\\(amd64|x86|arm64)$') {
            $Matches[1].ToLowerInvariant()
        } elseif ($fileId -match 'x64') {
            'amd64'
        } elseif ($fileId -match 'x86') {
            'x86'
        } else {
            'unknown'
        }
        if ($Architecture -ne 'All' -and $detectedArch -ne $Architecture) { continue }

        # The file id carries the feature name: pe10_1607x64files -> pe10_1607
        $feature = if ($fileId -match '^(pe[0-9A-Za-z_]*?)(x86|x64)') { $Matches[1] } else { $fileId }
        $info = $featureInfo[$feature]

        $rangeEndNode = $fileNode.SelectSingleNode('range/end')
        $rangeEnd = $null
        if ($rangeEndNode) {
            $tmpLong = 0L
            if ([long]::TryParse($rangeEndNode.InnerText.Trim(), [ref]$tmpLong)) { $rangeEnd = $tmpLong }
        }
        $hashNode = $fileNode.SelectSingleNode('hash')
        $rangeMd5 = if ($hashNode -and $hashNode.InnerText.Trim()) { $hashNode.InnerText.Trim() } else { $null }

        $containerFileName = ($cabUrl -split '/')[-1]
        foreach ($it in $items) {
            $relPath = $it.SelectSingleNode('extract_path').InnerText.Trim()
            $srcNode = $it.SelectSingleNode('source_filename')
            $filId   = if ($srcNode) { $srcNode.InnerText.Trim() } else { $null }

            $lang = 'neutral'
            if ($relPath -match '^WinPE_OCs\\([a-z]{2}-[a-z]{2,4}(?:-[a-z]{2})?)\\') { $lang = $Matches[1].ToLowerInvariant() }
            $compName = ($relPath -split '\\')[-1] -replace '\.cab$', ''
            if ($lang -ne 'neutral') { $compName = $compName -replace ('_' + [regex]::Escape($lang) + '$'), '' }

            $parsedEntries.Add([PSCustomObject]@{
                ContainerCabUrl  = $cabUrl
                ContainerCabName = $containerFileName
                KitPath          = $kitPath
                Architecture     = $detectedArch
                ComponentName    = $compName
                FilHashId        = $filId
                RelativePath     = $relPath
                IsLanguagePack   = ($lang -ne 'neutral')
                Language         = $lang
                Feature          = $feature
                PeRelease        = if ($info) { $info.Release } else { $null }
                WinBuild         = if ($info) { $info.WinBuild } else { $null }
                RangeEnd         = $rangeEnd
                RangeMd5         = $rangeMd5
            })
        }
    }

    return $parsedEntries
}

# --- 4. Multi-language WinPE_OCs download and extraction ---

function Save-WinPEOCPackage {
    <#
    .SYNOPSIS
        Downloads and extracts WinPE_OCs packages directly from the Microsoft CDN for the given Windows 10/11
        release, architecture and LANGUAGES (* = all 38 languages, or tr-tr, de-de, en-us, ...).
    .DESCRIPTION
        Three modes are supported (-Method):
          1. MsiIndexDirectCab (default):
             Downloads the ~1 MB .msi index database from the Microsoft CDN, uses WindowsInstaller COM to find
             the container .cab and fil<MD5> id of every package in all 38 languages, downloads only the
             required container .cab files and extracts them with expand.exe into WinPE_OCs\<language>\<package>.cab.
          2. MsiAdminExtract:
             Downloads the MSI database and every container .cab of its Media table and unpacks all 38 languages
             at once with msiexec.exe /a, without installing anything on the system.
          3. AdkSetupLayout:
             Runs the official adkwinpesetup.exe /layout <target> /quiet to download all languages.
    .PARAMETER LocalInstallersPath
        Uses the Installers folder of a local ADK layout instead of the CDN (MsiIndexDirectCab and
        MsiAdminExtract). Container .cab files are read from this folder instead of being downloaded.
    .EXAMPLE
        # Offline, from an existing ADK layout:
        Save-WinPEOCPackage -BuildId Win10_1809 -Language tr-tr -ComponentName * -DestinationPath C:\WinPE_OCs -LocalInstallersPath D:\ADK1809\Installers

    .EXAMPLE
        # All 38 languages (ar-sa .. tr-tr .. zh-tw) and every package:
        Save-WinPEOCPackage -BuildId Win11_24H2 -Architecture amd64 -Language * -ComponentName * -DestinationPath C:\WinPE_OCs_AllLangs

    .EXAMPLE
        # Turkish (tr-tr), German (de-de) and English (en-us) plus the main packages only:
        Save-WinPEOCPackage -BuildId Win11_22H2 -Architecture amd64 -Language neutral,tr-tr,de-de,en-us -ComponentName WinPE-WMI,WinPE-NetFx,WinPE-PowerShell,lp -DestinationPath C:\WinPE_OCs_Selected
    #>
    [CmdletBinding(SupportsShouldProcess = $true)]
    param(
        [Parameter(Mandatory = $false)]
        [string]$BuildId = 'Win11_22H2',

        [ValidateSet('amd64', 'x86', 'arm64', 'All')]
        [string]$Architecture = 'amd64',

        [Parameter(Mandatory = $false)]
        [string[]]$Language = @('*'),

        [Parameter(Mandatory = $false)]
        [string[]]$ComponentName = @('*'),

        [Parameter(Mandatory = $true)]
        [string]$DestinationPath,

        [ValidateSet('MsiIndexDirectCab', 'MsiAdminExtract', 'AdkSetupLayout')]
        [string]$Method = 'MsiIndexDirectCab',

        [Parameter(Mandatory = $false)]
        [string]$LocalInstallersPath,

        [switch]$KeepContainerCache
    )

    $buildInfo = Get-WinPEOCBuildCatalog -BuildId $BuildId | Select-Object -First 1
    if (-not $buildInfo) {
        throw "Gecersiz BuildId: $BuildId"
    }

    $targetRoot = Join-Path $DestinationPath $buildInfo.BuildId
    $cacheDir   = Join-Path $DestinationPath '_ContainerCache'

    # Method 3: adkwinpesetup.exe /layout (all languages and architectures)
    if ($Method -eq 'AdkSetupLayout') {
        # The setup file comes from the validated (working) CDN source; broken fwlink targets
        # (PDF, MediaCreationTool, ...) are never downloaded or run.
        $source    = Find-WinPEAddonSource -BuildId $BuildId
        $setupName = if ($source.BaseUrl -match '(?i)/adkw[iI]npeaddons/$') { 'adkwinpesetup.exe' } else { 'adksetup.exe' }
        $setupUrl  = "$($source.BaseUrl)$setupName"
        $installerPath = Join-Path $env:TEMP "$($buildInfo.BuildId)_$setupName"
        if ($PSCmdlet.ShouldProcess($setupUrl, "$setupName indir ve /layout ile tum dilleri cikar -> $targetRoot")) {
            New-Item -Path $targetRoot -ItemType Directory -Force | Out-Null
            $dl = Invoke-WinPEHttpDownload -Url $setupUrl -OutFile $installerPath
            if (-not $dl.Success) {
                throw "Kurulum dosyasi indirilemedi ($($dl.Message)): $setupUrl"
            }
            Start-Process -FilePath $installerPath -ArgumentList "/layout `"$targetRoot`" /quiet" -Wait -NoNewWindow
            if (-not $KeepContainerCache) {
                Remove-Item $installerPath -Force -ErrorAction SilentlyContinue
            }
        }
        return [PSCustomObject]@{
            BuildId         = $buildInfo.BuildId
            Method          = 'AdkSetupLayout'
            Languages       = 'All (38 Languages)'
            DestinationPath = $targetRoot
        }
    }

    # Method 2: msiexec.exe /a administrative extraction (unpacks all 38 languages at once without installing)
    if ($Method -eq 'MsiAdminExtract') {
        New-Item -Path $cacheDir -ItemType Directory -Force | Out-Null
        if ($LocalInstallersPath) {
            # Local layout: the MSI and the container .cab files are already in the same folder
            $localSource   = Get-WinPELocalInstallersMsi -Path $LocalInstallersPath -BuildInfo $buildInfo
            $msiFiles      = @($localSource.MsiFiles)
            $installersUrl = $null
            $sourceText    = $localSource.InstallersPath
        } else {
            $source        = Find-WinPEAddonSource -BuildId $BuildId -CacheDirectory $cacheDir
            $msiFiles      = @($source.MsiFiles)
            $installersUrl = $source.InstallersUrl
            $sourceText    = $installersUrl
        }
        if ($PSCmdlet.ShouldProcess($sourceText, "MSI ve Media CAB konteynerlerini indirip msiexec /a ile 38 dili cikar -> $targetRoot")) {
            New-Item -Path $targetRoot -ItemType Directory -Force | Out-Null

            $installerCom = New-Object -ComObject WindowsInstaller.Installer
            foreach ($localMsi in $msiFiles) {
                if (-not (Test-Path -LiteralPath $localMsi)) { continue }

                # Download every CAB of the MSI Media table next to the MSI (not needed for a local layout)
                $db = $installerCom.GetType().InvokeMember('OpenView', 'InvokeMethod', $null,
                    $installerCom.GetType().InvokeMember('OpenDatabase', 'InvokeMethod', $null, $installerCom, @($localMsi, 0)),
                    @('SELECT `Cabinet` FROM `Media`'))
                $null = $db.GetType().InvokeMember('Execute', 'InvokeMethod', $null, $db, $null)
                while ($installersUrl) {
                    $rec = $db.GetType().InvokeMember('Fetch', 'InvokeMethod', $null, $db, $null)
                    if ($null -eq $rec) { break }
                    $cabFile = ($rec.GetType().InvokeMember('StringData', 'GetProperty', $null, $rec, @(1)) -replace '^#', '')
                    if ($cabFile -match '\.cab$') {
                        $localCab = Join-Path $cacheDir $cabFile
                        if (-not (Test-Path -LiteralPath $localCab)) {
                            $cabUrl = "$installersUrl$cabFile"
                            Write-Verbose "Konteyner indiriliyor: $cabUrl"
                            $dl = Invoke-WinPEHttpDownload -Url $cabUrl -OutFile $localCab -TimeoutSeconds 7200
                            if (-not $dl.Success) { Write-Warning "Konteyner indirilemedi ($($dl.Message)): $cabUrl" }
                        }
                    }
                }
                $null = $db.GetType().InvokeMember('Close', 'InvokeMethod', $null, $db, $null)

                # Unpack all languages into the target folder with msiexec /a
                Start-Process -FilePath 'msiexec.exe' -ArgumentList "/a `"$localMsi`" /qn TARGETDIR=`"$targetRoot`"" -Wait -NoNewWindow
            }

            if (-not $KeepContainerCache) {
                Remove-Item -Path $cacheDir -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
        return [PSCustomObject]@{
            BuildId         = $buildInfo.BuildId
            Method          = 'MsiAdminExtract'
            Languages       = 'All (38 Languages)'
            DestinationPath = $targetRoot
        }
    }

    # Method 1 (default): MsiIndexDirectCab
    # When specific languages are given (e.g. tr-tr, de-de), add 'neutral' so the main packages are included
    $effectiveLanguages = if ($Language -contains '*') {
        @('*')
    } else {
        @(@('neutral') + $Language | Select-Object -Unique)
    }

    Write-Verbose "MSI veritabani uzerinden $($effectiveLanguages -join ', ') dilleri indeksleniyor..."
    $indexArgs = @{
        BuildId        = $BuildId
        Architecture   = $Architecture
        Language       = $effectiveLanguages
        ComponentName  = $ComponentName
        CacheDirectory = $cacheDir
    }
    if ($LocalInstallersPath) { $indexArgs['LocalInstallersPath'] = $LocalInstallersPath }
    $indexedPackages = @(Get-WinPEMsiDatabaseIndex @indexArgs)

    if ($indexedPackages.Count -eq 0) {
        throw "Belirtilen kriterlere (Dil: $($Language -join ','), Mimari: $Architecture) uygun paket bulunamadi."
    }

    $extractedFiles = [System.Collections.Generic.List[PSCustomObject]]::new()

    # Group by container .cab (each container is downloaded only once)
    $cabGroups = $indexedPackages | Group-Object -Property ContainerCabName

    if ($PSCmdlet.ShouldProcess("$($cabGroups.Count) adet konteyner CAB ($($indexedPackages.Count) WinPE_OCs paketi)", "Indir ve ayikla -> $targetRoot")) {
        New-Item -Path $cacheDir -ItemType Directory -Force | Out-Null

        foreach ($group in $cabGroups) {
            $cabName = $group.Name
            $first   = $group.Group[0]

            if ($first.ContainerCabPath) {
                # Local ADK layout: the container is used in place, not downloaded
                $localCab = $first.ContainerCabPath
                if (-not (Test-Path -LiteralPath $localCab)) {
                    Write-Warning "Yerel konteyner bulunamadi, $($group.Count) paket atlandi: $localCab"
                    continue
                }
            } else {
                $cabUrl = $first.ContainerCabUrl
                if (-not $cabUrl) {
                    Write-Warning "Konteyner URL'si cozumlenemedi, $($group.Count) paket atlandi: $cabName"
                    continue
                }
                # The cache name contains the source tag, so files of different ADK releases never mix
                $tag = Get-WinPESourceTag -BaseUrl ($cabUrl -replace '/[^/]*$', '/')
                $localCab = Join-Path $cacheDir "${BuildId}_${tag}_${cabName}"
                if (-not (Test-Path -LiteralPath $localCab)) {
                    Write-Verbose "Konteyner indiriliyor ($($group.Count) paket iceriyor): $cabUrl"
                    $dl = Invoke-WinPEHttpDownload -Url $cabUrl -OutFile $localCab -TimeoutSeconds 7200
                    if (-not $dl.Success) {
                        Write-Warning "Konteyner indirilemedi ($($dl.Message)), $($group.Count) paket atlandi: $cabUrl"
                        continue
                    }
                }
            }

            foreach ($pkg in $group.Group) {
                $archRoot = Join-Path $targetRoot $pkg.Architecture
                $destFile = Join-Path $archRoot $pkg.RelativePath
                $destDir  = [System.IO.Path]::GetDirectoryName($destFile)

                if (-not (Test-Path $destDir)) {
                    New-Item -Path $destDir -ItemType Directory -Force | Out-Null
                }

                $tempExtract = Join-Path $destDir $pkg.FilHashId
                & expand.exe $localCab -F:$($pkg.FilHashId) $destDir | Out-Null
                if (Test-Path $tempExtract) {
                    Move-Item -Path $tempExtract -Destination $destFile -Force
                    $extractedFiles.Add([PSCustomObject]@{
                        BuildId          = $buildInfo.BuildId
                        Architecture     = $pkg.Architecture
                        Language         = $pkg.Language
                        Component        = $pkg.ComponentName
                        SourceContainer  = $cabName
                        SourceFilHash    = $pkg.FilHashId
                        FilePath         = $destFile
                    })
                }
            }
        }

        if (-not $KeepContainerCache) {
            Remove-Item -Path $cacheDir -Recurse -Force -ErrorAction SilentlyContinue
        }
    }

    return $extractedFiles
}

# --- 5. Local HTTP REST API server (HttpListener) ---

function Start-WinPEOCRestApi {
    <#
    .SYNOPSIS
        Starts a local HTTP REST API server that serves the WinPE_OCs catalog, the 38-language list,
        MSI index queries and downloads as JSON.
    .DESCRIPTION
        Endpoints:
          - GET /api/builds                                  -> All Windows 10/11 builds
          - GET /api/languages                               -> The 38 supported language codes
          - GET /api/components?arch=amd64                   -> Quick fil<Hash> -> WinPE_OCs table
          - GET /api/msi-index?build=Win11_22H2&lang=tr-tr   -> MSI database query (38 languages)
          - GET /api/resolve?build=Win11_24H2                -> Resolves the CDN URL, MSI and CAB links
    .EXAMPLE
        Start-WinPEOCRestApi -Port 8080
    #>
    [CmdletBinding()]
    param(
        [int]$Port = 8080,
        [int]$MaxRequests = 0
    )

    $prefix = "http://localhost:$Port/"
    $listener = [System.Net.HttpListener]::new()
    $listener.Prefixes.Add($prefix)
    $listener.Start()
    Write-Host "WinPE_OCs Multi-Language REST API dinleniyor: $prefix" -ForegroundColor Cyan

    $requestCount = 0
    try {
        while ($listener.IsListening) {
            $context  = $listener.GetContext()
            $request  = $context.Request
            $response = $context.Response
            $path     = $request.Url.AbsolutePath.ToLowerInvariant()
            $statusCode = 200

            try {
                switch ($path) {
                    '/api/builds' {
                        $buildFilter = if ($request.QueryString['build']) { $request.QueryString['build'] } else { '*' }
                        $payload = Get-WinPEOCBuildCatalog -BuildId $buildFilter
                    }
                    '/api/languages' {
                        $payload = [PSCustomObject]@{
                            Count     = $Script:SupportedWinPELanguages.Count
                            Languages = $Script:SupportedWinPELanguages
                        }
                    }
                    '/api/components' {
                        $arch = if ($request.QueryString['arch']) { $request.QueryString['arch'] } else { 'amd64' }
                        $name = if ($request.QueryString['name']) { $request.QueryString['name'] -split ',' } else { @('*') }
                        $payload = Get-WinPEOCFileMap -Architecture $arch -ComponentName $name
                    }
                    '/api/msi-index' {
                        $build = if ($request.QueryString['build']) { $request.QueryString['build'] } else { 'Win11_22H2' }
                        $arch  = if ($request.QueryString['arch'])  { $request.QueryString['arch'] }  else { 'All' }
                        $lang  = if ($request.QueryString['lang'])  { $request.QueryString['lang'] -split ',' } else { @('*') }
                        $comp  = if ($request.QueryString['name'])  { $request.QueryString['name'] -split ',' } else { @('*') }
                        $payload = Get-WinPEMsiDatabaseIndex -BuildId $build -Architecture $arch -Language $lang -ComponentName $comp
                    }
                    '/api/resolve' {
                        $build = if ($request.QueryString['build']) { $request.QueryString['build'] } else { 'Win11_22H2' }
                        $payload = Resolve-WinPEAddonCdnUrl -BuildId $build
                    }
                    default {
                        $statusCode = 404
                        $payload = @{
                            error     = 'Endpoint Not Found'
                            endpoints = @(
                                '/api/builds',
                                '/api/languages',
                                '/api/components?arch=amd64',
                                '/api/msi-index?build=Win11_22H2&lang=tr-tr,de-de,en-us',
                                '/api/resolve?build=Win11_24H2'
                            )
                        }
                    }
                }
            } catch {
                $statusCode = 500
                $payload = @{ error = $_.Exception.Message }
            }

            $jsonBytes = [System.Text.Encoding]::UTF8.GetBytes(($payload | ConvertTo-Json -Depth 5))
            $response.StatusCode      = $statusCode
            $response.ContentType     = 'application/json; charset=utf-8'
            $response.ContentLength64 = $jsonBytes.Length
            $response.OutputStream.Write($jsonBytes, 0, $jsonBytes.Length)
            $response.OutputStream.Close()

            $requestCount++
            if ($MaxRequests -gt 0 -and $requestCount -ge $MaxRequests) {
                break
            }
        }
    } finally {
        $listener.Stop()
        $listener.Close()
    }
}

# --- 6. Built-in self-test (includes a multi-language MSI table simulation) ---

function Invoke-WinPEOCApiSelfTest {
    <#
    .SYNOPSIS
        Verifies the 38-language support, the MSI table resolver (ConvertFrom-WinPEMsiTables),
        CDN URL resolution and the manifest parser.
    #>
    [CmdletBinding()]
    param(
        [string]$SampleManifestPath
    )

    $tests = [System.Collections.Generic.List[PSCustomObject]]::new()

    # Test 1: 38-language support and build catalog
    $langs  = @(Get-WinPESupportedLanguages)
    $builds = @(Get-WinPEOCBuildCatalog)
    $tests.Add([PSCustomObject]@{
        TestName = 'CatalogAnd38Languages'
        Passed   = ($builds.Count -ge 10 -and $langs.Count -eq 39 -and ($langs -contains 'tr-tr'))
        Details  = "$($builds.Count) derleme ve $($langs.Count) dil kulturu (tr-tr dahil) dogrulandi."
    })

    # Test 2: multi-language MSI table resolver (ConvertFrom-WinPEMsiTables) simulation
    $mockDirs = @{
        'TARGETDIR'    = @{ Directory = 'TARGETDIR';    Parent = '';           DefaultDir = 'SourceDir' }
        'dirWinPE'     = @{ Directory = 'dirWinPE';     Parent = 'TARGETDIR';  DefaultDir = 'WINPE~1|Windows Preinstallation Environment' }
        'dirAmd64'     = @{ Directory = 'dirAmd64';     Parent = 'dirWinPE';   DefaultDir = 'amd64' }
        'dirOCs'       = @{ Directory = 'dirOCs';       Parent = 'dirAmd64';   DefaultDir = 'WINPE_~1|WinPE_OCs' }
        'dirTrTr'      = @{ Directory = 'dirTrTr';      Parent = 'dirOCs';     DefaultDir = 'tr-tr:tr-tr' }
        'dirDeDe'      = @{ Directory = 'dirDeDe';      Parent = 'dirOCs';     DefaultDir = 'de-de:de-de' }
    }
    $mockComps = @{
        'compBaseWmi'  = 'dirOCs'
        'compTrLp'     = 'dirTrTr'
        'compTrWmi'    = 'dirTrTr'
        'compDeWmi'    = 'dirDeDe'
    }
    $mockMedia = @(
        @{ DiskId = '1'; LastSequence = '10'; Cabinet = '#9722214af0ab8aa9dffb6cfdafd937b7.cab' },
        @{ DiskId = '2'; LastSequence = '50'; Cabinet = '#0b63b7c537782729483bff2d64a620fa.cab' }
    )
    $mockFiles = @(
        @{ File = 'filb8eaee8243f0d40642def467974eb651'; Component = 'compBaseWmi'; FileName = 'WINPE-~1.CAB|WinPE-WMI.cab';       FileSize = '11245000'; Sequence = '5'  },
        @{ File = 'fil11111111111111111111111111111111'; Component = 'compTrLp';    FileName = 'LP.CAB|lp.cab';                    FileSize = '42500000'; Sequence = '15' },
        @{ File = 'fil22222222222222222222222222222222'; Component = 'compTrWmi';   FileName = 'WINPE-~2.CAB|WinPE-WMI_tr-tr.cab'; FileSize = '312000';   Sequence = '16' },
        @{ File = 'fil33333333333333333333333333333333'; Component = 'compDeWmi';   FileName = 'WINPE-~3.CAB|WinPE-WMI_de-de.cab'; FileSize = '318000';   Sequence = '25' }
    )

    $mappedMsi = @(ConvertFrom-WinPEMsiTables `
        -DirectoryRows $mockDirs `
        -ComponentDirMap $mockComps `
        -MediaRows $mockMedia `
        -FileRows $mockFiles `
        -InstallersBaseUrl 'https://download.microsoft.com/download/5/2/5/525dcde0-c7b8-487a-894d-0952775a78c7/adkwinpeaddons/Installers/')

    $trWmi = $mappedMsi | Where-Object { $_.Language -eq 'tr-tr' -and $_.ComponentName -eq 'WinPE-WMI' }
    $tests.Add([PSCustomObject]@{
        TestName = 'MultiLanguageMsiTableResolver'
        Passed   = ($mappedMsi.Count -eq 4 -and $trWmi.RelativePath -eq 'WinPE_OCs\tr-tr\WinPE-WMI_tr-tr.cab' -and $trWmi.ContainerCabName -eq '0b63b7c537782729483bff2d64a620fa.cab')
        Details  = "MSI tablosundan tr-tr ve de-de paket yollari ve konteyner CAB eslesmeleri dogrulandi."
    })

    # Test 3: CDN URL and MSI package resolution
    $resolved22H2 = Resolve-WinPEAddonCdnUrl -BuildId 'Win11_22H2'
    $tests.Add([PSCustomObject]@{
        TestName = 'CdnMsiAndCabUrlResolution'
        Passed   = ($resolved22H2.MsiPackageUrls.Count -ge 2 -and $resolved22H2.Amd64BaseCabUrl -match '9722214af0ab8aa9dffb6cfdafd937b7\.cab$')
        Details  = "MSI URL sayisi: $($resolved22H2.MsiPackageUrls.Count), BaseCAB: $($resolved22H2.Amd64BaseCabUrl)"
    })

    # Test 4: local manifest parsing
    if ($SampleManifestPath -and (Test-Path $SampleManifestPath)) {
        $manifestItems = @(Get-MacriumWinPEManifest -ManifestPath $SampleManifestPath -MicrosoftCdnOnly)
        $tests.Add([PSCustomObject]@{
            TestName = 'MacriumManifestParser'
            Passed   = ($manifestItems.Count -gt 400)
            Details  = "Manifest icinden $($manifestItems.Count) adet Microsoft CDN WinPE_OCs kaydi ayristirildi."
        })
    }

    # Test 5: fwlink target validation (offline) - broken redirects must be rejected
    $goodTargets = @(
        'https://download.microsoft.com/download/b53d3b97-9f7f-49df-b373-10138ee34d00/adk/adksetup.exe',
        'https://download.microsoft.com/download/4/7/6/47653b91-4dc7-46f3-ad00-e665f6ac8105/ADKWINPEADDONS/adkwinpesetup.exe',
        'https://download.microsoft.com/download/a4a79e7a-f085-41c4-aebf-2538fd000790/adkwinpeaddons/'
    )
    $badTargets = @(
        'https://download.microsoft.com/download/9/e/a/9eac306f-d134-4609-9c58-35d1638c2363/MediaCreationTool_22H2.exe',
        'https://download.microsoft.com/download/8/9/D/89D34449-2AC8-4E0F-9527-9780A0562DB1/Time-and-expense-approval-in-project-service-app-v3.pdf',
        'https://www.bing.com?ref=go&linkid=2165884'
    )
    $goodOk = @($goodTargets | Where-Object { ConvertTo-WinPEAdkBaseUrl -Location $_ }).Count
    $badOk  = @($badTargets  | Where-Object { ConvertTo-WinPEAdkBaseUrl -Location $_ }).Count
    $tests.Add([PSCustomObject]@{
        TestName = 'FwLinkTargetValidation'
        Passed   = ($goodOk -eq $goodTargets.Count -and $badOk -eq 0)
        Details  = "$goodOk/$($goodTargets.Count) gecerli hedef kabul edildi, $badOk/$($badTargets.Count) gecersiz hedef kabul edildi (0 olmali)."
    })

    # Test 6: catalog source consistency - every build needs at least one source
    $noSource = @($builds | Where-Object { -not $_.CdnBaseUrl -and @($_.CdnMirrors | Where-Object { $_ }).Count -eq 0 -and -not $_.FwLinkUrl })
    $tests.Add([PSCustomObject]@{
        TestName = 'CatalogSources'
        Passed   = ($noSource.Count -eq 0)
        Details  = if ($noSource.Count) { "Kaynagi olmayan derlemeler: $($noSource.BuildId -join ', ')" } else { 'Tum derlemelerin en az bir CDN kaynagi var.' }
    })

    # Test 7: embedded index - data exists for every build and URLs match the catalog
    $embeddedProblems = [System.Collections.Generic.List[string]]::new()
    $embeddedTotal = 0
    foreach ($b in $builds) {
        if (-not (Test-WinPEEmbeddedIndex -BuildId $b.BuildId)) {
            $embeddedProblems.Add("$($b.BuildId): veri yok")
            continue
        }
        $items = @(Get-WinPEEmbeddedIndex -BuildId $b.BuildId)
        $embeddedTotal += $items.Count
        $prefix = $b.CdnBaseUrl.TrimEnd('/') + '/Installers/'
        $bad = @($items | Where-Object {
                -not $_.ContainerCabUrl.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase) -or
                $_.FilHashId -notmatch '^fil[0-9a-f]{32}$' -or $_.FileSize -le 0
            })
        if ($items.Count -eq 0 -or $bad.Count -gt 0) { $embeddedProblems.Add("$($b.BuildId): $($bad.Count) hatali kayit") }
    }
    $tests.Add([PSCustomObject]@{
        TestName = 'EmbeddedIndex'
        Passed   = ($embeddedProblems.Count -eq 0)
        Details  = if ($embeddedProblems.Count) { $embeddedProblems -join '; ' } else { "Gomulu indeks: $embeddedTotal paket, tum adresler katalogla uyumlu." }
    })

    return $tests
}

