function Get-EmbeddedCatalogText {
    if ([string]::IsNullOrWhiteSpace($script:EmbeddedCatalogB64)) { return '' }
    try {
        # FromBase64String skips the line breaks of the here-string
        $gzBytes = [Convert]::FromBase64String($script:EmbeddedCatalogB64)
        $msIn = New-Object System.IO.MemoryStream(,$gzBytes)
        $gz = New-Object System.IO.Compression.GZipStream($msIn, [System.IO.Compression.CompressionMode]::Decompress)
        $msOut = New-Object System.IO.MemoryStream
        $gz.CopyTo($msOut)
        $gz.Dispose()
        return [System.Text.Encoding]::UTF8.GetString($msOut.ToArray()).TrimStart([char]0xFEFF)
    } catch {
        return ''
    }
}

# Catalog, format 2 (UTF-8, '|' separated; the embedded one covers every language of the UUP rows):
#   R|2|*|date                                                header
#   L|code|name                                               language (selector order)
#   U|no|updateId|version|arch|isWin11|isServer|build|sku     UUP row
#   O|<sha1><size>|<sha1><size>|...                           object table, referenced by position
#   G|no|language|<c><object>:<file name>;...                 files of a row in one language, display order
#                                                             (c: L language pack, E feature, F FOD, S server FOD)
#   V|label|buildId|isServer                                  Windows PE version (selector order)
#   B|buildId|ADK product version
#   A|buildId|arch|language,language,...                      Windows PE languages of a build / architecture
#   W|buildId|arch|<relative path>:<object>;...               Windows PE files of a build / architecture
#   P|lang|productId|wuCategoryId|<minBuild>:<size>:<sha256>:<package full name>;...
#                                                             Microsoft Store Local Experience Packs of a language
# Format 1 (Repo\index.txt of the earlier zip distribution, one language): R|1|lang|date, U lines with their
# F|category|sha1|name lines, O|sha1|size|part|dir|ext, V, B and X|buildId|arch|language|component|sha1|path.
# G and W lines are kept as text and parsed when a row / build is listed, so loading stays fast.
$script:RepoIndex = $null

function Import-OfflineRepo {
    param([string]$RepoDir)
    # Absolute path: .NET file APIs resolve relative paths against the process folder, not the PowerShell location
    $RepoDir = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($RepoDir)
    $indexPath = Join-Path $RepoDir 'index.txt'
    $text = $null
    $sourceDesc = 'disk'
    if ([System.IO.File]::Exists($indexPath)) {
        try { $text = [System.IO.File]::ReadAllText($indexPath, [System.Text.Encoding]::UTF8).TrimStart([char]0xFEFF) } catch { $text = $null }
    }
    if ([string]::IsNullOrEmpty($text)) {
        $text = Get-EmbeddedCatalogText
        $sourceDesc = 'embedded'
        $indexPath = $null
    }
    $where = if ($indexPath) { $indexPath } else { 'embedded' }
    if ([string]::IsNullOrEmpty($text)) { throw (LF 'Off_BadIndex' $where) }

    $repo = [PSCustomObject]@{
        Dir         = $RepoDir
        SourceDesc  = $sourceDesc
        IndexPath   = $indexPath
        Format      = 0
        Language    = ''
        Date        = ''
        Languages   = New-Object System.Collections.Generic.List[object]
        Rows        = New-Object System.Collections.Generic.List[object]
        LangRaw     = @{}
        LangFiles   = @{}
        ObjRaw      = [string[]]@()
        Objects     = @{}
        Versions    = New-Object System.Collections.Generic.List[object]
        Builds      = @{}
        PeRaw       = @{}
        PeFiles     = @{}
        PeLanguages = @{}
        StoreLxp    = @{}
        Roots       = [string[]]@($RepoDir)
    }
    $row = $null
    $f1Files = @{}
    foreach ($line in $text.Split([char]10)) {
        if ($line.Length -lt 3 -or $line[0] -eq '#') { continue }
        if ($line[$line.Length - 1] -eq [char]13) { $line = $line.Substring(0, $line.Length - 1) }
        $t = $line.Substring(0, 2)
        if ($t -eq 'G|' -or $t -eq 'W|') {
            # Only the key fields are split now; the file list stays text
            $i1 = $line.IndexOf('|', 2)
            $i2 = $line.IndexOf('|', $i1 + 1)
            if ($i1 -lt 0 -or $i2 -lt 0) { continue }
            $key = $line.Substring(2, $i1 - 2) + '|' + $line.Substring($i1 + 1, $i2 - $i1 - 1)
            if ($t -eq 'G|') { $repo.LangRaw[$key] = $line.Substring($i2 + 1) } else { $repo.PeRaw[$key] = $line.Substring($i2 + 1) }
            continue
        }
        $p = $line.Split('|')
        switch ($p[0]) {
            'R' { $repo.Format = [int]$p[1]; $repo.Language = $p[2]; $repo.Date = $p[3] }
            'L' { $repo.Languages.Add([PSCustomObject]@{ Code = $p[1]; Name = $p[2] }) }
            'O' {
                if ($repo.Format -ge 2) { $repo.ObjRaw = $p }      # entry n is at position n + 1
                else { $repo.Objects[$p[1]] = [PSCustomObject]@{ Sha1 = $p[1]; Size = [long]$p[2]; Ext = $p[5] } }
            }
            'U' {
                if ($repo.Format -ge 2) {
                    $row = [PSCustomObject]@{ No = $p[1]; UpdateId = $p[2]; Version = $p[3]; Arch = $p[4]; IsWin11 = $p[5]; IsServer = $p[6]
                                              Build = $p[7]; Sku = $(if ($p[8]) { [int]$p[8] } else { 0 }) }
                } else {
                    $row = [PSCustomObject]@{ No = [string]$repo.Rows.Count; UpdateId = $p[1]; Version = $p[2]; Arch = $p[3]; IsWin11 = $p[4]; IsServer = $p[5]
                                              Build = $(if ($p.Count -gt 6) { $p[6] } else { '' })
                                              Sku = $(if ($p.Count -gt 7 -and $p[7]) { [int]$p[7] } else { 0 }) }
                    $f1Files[$row.No] = New-Object System.Collections.Generic.List[object]
                }
                $repo.Rows.Add($row)
            }
            'F' { if ($row -and $f1Files.ContainsKey($row.No)) { $f1Files[$row.No].Add([PSCustomObject]@{ Category = $p[1]; Sha1 = $p[2]; Name = $p[3]; Size = [long]0 }) } }
            'V' { $repo.Versions.Add([PSCustomObject]@{ Label = $p[1]; BuildId = $p[2]; IsServer = $p[3] }) }
            'B' { $repo.Builds[$p[1]] = [PSCustomObject]@{ BuildId = $p[1]; ProductVersion = $p[2] } }
            'A' { $repo.PeLanguages["$($p[1])|$($p[2])"] = [string[]]$p[3].Split(',') }
            'P' { if ($p.Count -ge 5) { $repo.StoreLxp[$p[1]] = [PSCustomObject]@{ ProductId = $p[2]; CategoryId = $p[3]; Raw = $p[4] } } }
            'X' {
                $key = "$($p[1])|$($p[2])"
                if (-not $repo.PeFiles.ContainsKey($key)) { $repo.PeFiles[$key] = New-Object System.Collections.Generic.List[object] }
                $repo.PeFiles[$key].Add([PSCustomObject]@{ BuildId = $p[1]; Arch = $p[2]; Language = $p[3]; Component = $p[4]; Sha1 = $p[5]; RelativePath = $p[6]; Size = [long]0 })
            }
        }
    }
    if (($repo.Format -ne 1 -and $repo.Format -ne 2) -or $repo.Rows.Count -eq 0) { throw (LF 'Off_BadIndex' $where) }

    if ($repo.Format -eq 1) {
        # One language: sizes come from the object table
        $lang = $repo.Language
        foreach ($no in $f1Files.Keys) {
            foreach ($f in $f1Files[$no]) { $o = $repo.Objects[$f.Sha1]; if ($o) { $f.Size = $o.Size } }
            $repo.LangFiles["$no|$lang"] = $f1Files[$no]
        }
        foreach ($key in @($repo.PeFiles.Keys)) {
            $langs = @{}
            foreach ($x in $repo.PeFiles[$key]) {
                $o = $repo.Objects[$x.Sha1]; if ($o) { $x.Size = $o.Size }
                $langs[$x.Language] = $true
            }
            $repo.PeLanguages[$key] = [string[]]@($langs.Keys)
        }
        $name = $lang
        foreach ($r in @($script:RegionTable)) { if ($r.Region -eq $lang) { $name = $r.Language } }
        $repo.Languages.Add([PSCustomObject]@{ Code = $lang; Name = $name })
    }
    if (-not [System.IO.Directory]::Exists($RepoDir)) {
        try { New-Item -Path $RepoDir -ItemType Directory -Force -ErrorAction Stop | Out-Null } catch { }
    }
    $script:RepoIndex = $repo
    Update-OfflineSources
    return $repo
}

function Test-OfflineLanguage {
    param([string]$Language)
    foreach ($l in $script:RepoIndex.Languages) { if ($l.Code -eq $Language) { return $true } }
    return $false
}

# Files of a UUP row in one language: Category, Sha1, Size, Name (display order)
function Get-OfflineLangFiles {
    param($Row, [string]$Language)
    if (-not $Row) { return @() }
    $key = "$($Row.No)|$Language"
    $cached = $script:RepoIndex.LangFiles[$key]
    if ($cached) { return $cached.ToArray() }
    $raw = $script:RepoIndex.LangRaw[$key]
    if (-not $raw) { return @() }
    $objs = $script:RepoIndex.ObjRaw
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($e in $raw.Split(';')) {
        if ($e.Length -lt 4) { continue }
        $colon = $e.IndexOf(':')
        $o = $objs[[int]$e.Substring(1, $colon - 1) + 1]
        $cat = switch ([string]$e[0]) { 'L' { 'lp' } 'E' { 'feature' } 'S' { 'server' } default { 'fod' } }
        $list.Add([PSCustomObject]@{ Category = $cat; Sha1 = $o.Substring(0, 40); Size = [long]$o.Substring(40); Name = $e.Substring($colon + 1) })
    }
    $script:RepoIndex.LangFiles[$key] = $list
    return $list.ToArray()
}

# Windows PE files of a build / architecture in every language of the catalog
function Get-OfflinePeCatalog {
    param([string]$BuildId, [string]$Arch)
    $key = "$BuildId|$Arch"
    $cached = $script:RepoIndex.PeFiles[$key]
    if ($cached) { return $cached.ToArray() }
    $raw = $script:RepoIndex.PeRaw[$key]
    if (-not $raw) { return @() }
    $objs = $script:RepoIndex.ObjRaw
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($e in $raw.Split(';')) {
        $colon = $e.LastIndexOf(':')
        if ($colon -lt 1) { continue }
        $rel = $e.Substring(0, $colon)
        $o = $objs[[int]$e.Substring($colon + 1) + 1]
        # WinPE_OCs\<component>.cab (neutral), WinPE_OCs\<lang>\<component>_<lang>.cab or WinPE_OCs\<lang>\lp.cab
        $parts = $rel.Split('\')
        if ($parts.Count -lt 3) {
            $lang = 'neutral'
            $comp = $parts[$parts.Count - 1] -replace '\.cab$', ''
        } else {
            $lang = $parts[1]
            $fn = $parts[2] -replace '\.cab$', ''
            $suffix = "_$lang"
            $comp = if ($fn.EndsWith($suffix, [StringComparison]::OrdinalIgnoreCase)) { $fn.Substring(0, $fn.Length - $suffix.Length) } else { $fn }
        }
        $list.Add([PSCustomObject]@{ BuildId = $BuildId; Arch = $Arch; Language = $lang; Component = $comp
                                     Sha1 = $o.Substring(0, 40); RelativePath = $rel; Size = [long]$o.Substring(40) })
    }
    $script:RepoIndex.PeFiles[$key] = $list
    return $list.ToArray()
}

# Roots: the Repo folder, the script folder and the Repo folders of zip parts of the earlier
# distribution that were extracted into their own WinPEOCs* folders next to the script folder.
function Update-OfflineRepoRoots {
    if (-not $script:RepoIndex) { return }
    $roots = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    $add = {
        param([string]$Dir)
        if (-not $Dir -or -not [System.IO.Directory]::Exists($Dir)) { return }
        $k = [System.IO.Path]::GetFullPath($Dir).TrimEnd([char[]]@('\', '/')).ToLowerInvariant()
        if ($seen.ContainsKey($k)) { return }
        $seen[$k] = $true
        $roots.Add($Dir)
    }
    & $add $script:RepoIndex.Dir
    & $add $script:AppRoot
    try {
        $appDir = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($script:RepoIndex.Dir).TrimEnd([char[]]@('\', '/')))
        $d = $appDir
        for ($i = 0; $i -lt 2 -and $d; $i++) {
            $d = [System.IO.Path]::GetDirectoryName($d)
            if (-not $d -or -not [System.IO.Directory]::Exists($d)) { continue }
            foreach ($dir in [System.IO.Directory]::GetDirectories($d, 'WinPEOCs*')) {
                $cands = @((Join-Path $dir 'Repo'))
                foreach ($sub in [System.IO.Directory]::GetDirectories($dir, 'WinPEOCs*')) { $cands += (Join-Path $sub 'Repo') }
                foreach ($c in $cands) {
                    if (-not [System.IO.Directory]::Exists($c)) { continue }
                    if (@([System.IO.Directory]::GetFiles($c, 'part-*.txt')).Count -eq 0) { continue }
                    & $add $c
                }
            }
        }
    } catch { }
    $script:RepoIndex.Roots = $roots.ToArray()
}

function New-OfflineSource {
    param([string]$Type, $Entry = $null, [string]$Path = '', [bool]$ByName = $false)
    if ($Type -eq 'bin') {
        return [PSCustomObject]@{ Type = 'bin'; Path = $null; BinPath = $Entry.BinPath; EntryName = $Entry.Name; Entry = $Entry; ByName = $ByName }
    }
    return [PSCustomObject]@{ Type = 'file'; Path = $Path; BinPath = $null; EntryName = [System.IO.Path]::GetFileName($Path); Entry = $null; ByName = $ByName }
}

# Finds the content of a catalog file. Order: any .bin archive by SHA-1 -> the archive of this version /
# build by entry name (content must match the catalog SHA-1 when it is known) -> loose <sha1>.<ext> files
# -> loose files by their real name (size must match; ByName sources are always SHA-1 checked).
function Get-OfflineObjectSource {
    param(
        [string]$Sha1,
        [string]$FileName = '',
        [long]$Size = 0,
        [string]$BinPath = '',
        [string]$EntryName = ''
    )
    $sha = if ($Sha1) { $Sha1.ToLowerInvariant() } else { '' }
    if ($sha -and $script:BinBySha1.ContainsKey($sha)) { return (New-OfflineSource 'bin' $script:BinBySha1[$sha]) }

    $entryKey = if ($EntryName) { $EntryName } else { $FileName }
    if ($BinPath -and $entryKey) {
        $bk = [System.IO.Path]::GetFullPath($BinPath).ToLowerInvariant()
        $names = $script:BinByName[$bk]
        if ($names) {
            $e = $names[$entryKey.ToLowerInvariant()]
            if ($e -and (-not $sha -or $e.Sha1 -eq $sha)) { return (New-OfflineSource 'bin' $e -ByName (-not $sha)) }
        }
    }

    if ($sha) {
        $nameExt = if ($FileName) { [System.IO.Path]::GetExtension($FileName) } elseif ($EntryName) { [System.IO.Path]::GetExtension($EntryName) } else { '' }
        $exts = if ($nameExt) { @($nameExt) } else { @('.cab', '.esd') }
        foreach ($ext in $exts) {
            $cands = $script:LooseByName[("$sha$ext").ToLowerInvariant()]
            if ($cands) {
                foreach ($c in $cands) {
                    if ($Size -le 0 -or $c.Length -eq $Size) { return (New-OfflineSource 'file' -Path $c.Path) }
                }
            }
        }
    }

    if ($FileName) {
        $cands = $script:LooseByName[$FileName.ToLowerInvariant()]
        if ($cands) {
            foreach ($c in $cands) {
                if ($Size -le 0 -or $c.Length -eq $Size) { return (New-OfflineSource 'file' -Path $c.Path -ByName $true) }
            }
        }
    }
    return $null
}

# Windows paths in the catalog; converted for the local platform (tests run on Linux)
function ConvertTo-LocalRelativePath {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return '' }
    $p = $Path.TrimStart([char[]]@('\', '/'))
    if ([System.IO.Path]::DirectorySeparatorChar -eq '\') { return $p.Replace('/', '\') }
    return $p.Replace('\', [string][System.IO.Path]::DirectorySeparatorChar)
}

# Windows PE files (neutral + one language) of a build / architecture: the catalog (with SHA-1) or, for
# what the catalog does not list, the embedded ADK index of the engine (SHA-1 then comes from the archive).
function Get-OfflinePeFiles {
    param(
        [Parameter(Mandatory = $true)][string]$BuildId,
        [Parameter(Mandatory = $true)][string]$Arch,
        [Parameter(Mandatory = $true)][string]$Language
    )
    if (-not $script:RepoIndex) { return @() }
    $out = New-Object System.Collections.Generic.List[object]
    $haveNeutral = $false; $haveLang = $false
    foreach ($x in (Get-OfflinePeCatalog -BuildId $BuildId -Arch $Arch)) {
        if ($x.Language -eq 'neutral') { $haveNeutral = $true } elseif ($x.Language -eq $Language) { $haveLang = $true } else { continue }
        $out.Add($x)
    }
    if ($haveNeutral -and $haveLang) { return $out.ToArray() }
    if (Get-Command -Name Get-WinPEEmbeddedIndex -ErrorAction SilentlyContinue) {
        try {
            foreach ($r in @(Get-WinPEEmbeddedIndex -BuildId $BuildId)) {
                if ($r.Architecture -ne $Arch) { continue }
                if ($r.Language -eq 'neutral') { if ($haveNeutral) { continue } }
                elseif ($r.Language -ne $Language -or $haveLang) { continue }
                $out.Add([PSCustomObject]@{ BuildId = $BuildId; Arch = $Arch; Language = $r.Language; Component = $r.ComponentName
                                            Sha1 = ''; RelativePath = $r.RelativePath; Size = [long]$r.FileSize })
            }
        } catch { }
    }
    return $out.ToArray()
}

# build|arch|language triples for the Windows PE selectors: catalog languages, plus the engine index for
# languages of the catalog that a build / architecture of the catalog does not list
function Get-OfflinePeAvailability {
    $set = New-Object 'System.Collections.Generic.HashSet[string]'
    $known = @{}
    foreach ($l in $script:RepoIndex.Languages) { $known[$l.Code] = $true }
    foreach ($key in $script:RepoIndex.PeLanguages.Keys) {
        foreach ($l in $script:RepoIndex.PeLanguages[$key]) { [void]$set.Add("$key|$l") }
    }
    if (Get-Command -Name Get-WinPEEmbeddedIndexData -ErrorAction SilentlyContinue) {
        try {
            $data = Get-WinPEEmbeddedIndexData
            $builds = @{}
            foreach ($v in $script:RepoIndex.Versions) { $builds[$v.BuildId] = $true }
            foreach ($bid in @($data.Builds.Keys)) {
                if (-not $builds.ContainsKey($bid)) { continue }
                foreach ($line in $data.Builds[$bid].Lines) {
                    $p = $line.Split('|')
                    if ($p.Count -lt 2 -or ($p[1] -ne 'neutral' -and -not $known.ContainsKey($p[1]))) { continue }
                    [void]$set.Add("$bid|$($p[0])|$($p[1])")
                }
            }
        } catch { }
    }
    return ,([string[]]@($set))
}

function Get-OfflineRuntimeInfo {
    $fw = try { [System.Runtime.InteropServices.RuntimeInformation]::FrameworkDescription } catch { ".NET $([Environment]::Version)" }
    return "PowerShell $($PSVersionTable.PSVersion) · $fw"
}

function Update-OfflineRepoInfo {
    if (-not $script:RepoIndex) { return }
    Update-OfflineSources
    $langBins = 0; $peBins = 0; $binBytes = [long]0
    $langs = New-Object 'System.Collections.Generic.SortedSet[string]'
    foreach ($info in $script:BinArchives.Values) {
        if ($info.Kind -eq 'winpe' -or [System.IO.Path]::GetFileName($info.Path) -like 'winpe_*') { $peBins++ } else { $langBins++ }
        $binBytes += $info.FileLength
        if ($info.Language -and $info.Language -ne 'neutral') { [void]$langs.Add($info.Language) }
    }
    $loose = 0
    foreach ($n in $script:LooseByName.Keys) { $loose += $script:LooseByName[$n].Count }
    $contents = if ($script:BinArchives.Count -eq 0 -and $loose -eq 0) {
        L 'Off_ContentsEmpty'
    } else {
        $langText = if ($langs.Count -gt 0) { @($langs) -join ', ' } else { '—' }
        $c = LF 'Off_Contents' $langBins $peBins (Format-Size $binBytes) $langText
        if ($loose -gt 0) { $c += ' · ' + (LF 'Off_ContentsLoose' $loose) }
        $c
    }
    $src = if ($script:RepoIndex.SourceDesc -eq 'embedded') { LF 'Off_IndexEmbedded' $script:RepoIndex.Languages.Count } else { LF 'Off_IndexDisk' $script:RepoIndex.IndexPath }
    $index = LF 'Off_IndexInfo' $src $script:RepoIndex.Date $script:RepoIndex.Rows.Count $script:RepoIndex.Builds.Count
    if ($script:UI) { $script:UI.SetEngineInfo($contents, $index, (Get-OfflineRuntimeInfo)) }
    return [PSCustomObject]@{
        Contents  = $contents
        Index     = $index
        Archives  = $script:BinArchives.Count
        Languages = [string[]]@($langs)
        Loose     = $loose
    }
}

function Set-OfflineMissingState {
    param($Item)
    $Item.SetState('Skipped', (L 'Off_NotInRepo'))
}

function Write-OfflineMissingSummary {
    param([int]$Count, [long]$Bytes)
    if ($Count -le 0) { return }
    $msg = LF 'Off_ListMissing' $Count (Format-Size $Bytes)
    Write-UiLog 'warn' $msg
    Set-UiStatus $msg 'warn'
}

function Assert-OfflineRepo {
    if (-not $script:RepoIndex) { throw (L 'Off_NoRepo') }
}

function Get-OfflineRow {
    param([string]$UpdateId, [string]$Version, [string]$Arch)
    foreach ($r in $script:RepoIndex.Rows) {
        if ($r.UpdateId -eq $UpdateId -and $r.Version -eq $Version -and $r.Arch -eq $Arch) { return $r }
    }
    return $null
}

# Device attributes for the FE3 request: build and SKU of the UUP row (catalog) or the UUP API
function Get-OfflineUupTag {
    param($Row, [string]$Language = 'en-us')
    $build = [string]$Row.Build
    $sku = [int]$Row.Sku
    $arch = switch ($Row.Arch) { 'x64' { 'amd64' } default { [string]$Row.Arch } }
    if (-not $build) {
        try {
            $resp = Get-UUPFiles -UpdateID $Row.UpdateId -Language $Language -NoLinks
            if ($resp -and $resp.response) {
                if ($resp.response.build) { $build = [string]$resp.response.build }
                if ($resp.response.sku) { $sku = [int]$resp.response.sku }
                if ($resp.response.arch) { $arch = [string]$resp.response.arch }
            }
        } catch {
            Write-UiLog 'warn' "UUP: $($_.Exception.Message)"
        }
    }
    if (-not $build) { $build = '26100.1' }
    if ($sku -le 0) { $sku = $(if ($Row.IsServer -eq 'true') { 8 } else { 48 }) }
    return [PSCustomObject]@{ Build = $build; Arch = $arch; Sku = $sku }
}

function Get-OfflineTempDir {
    param([string]$BinPath)
    $dir = Join-Path (Join-Path $script:RepoIndex.Dir '_temp') ([System.IO.Path]::GetFileNameWithoutExtension($BinPath))
    if (-not [System.IO.Directory]::Exists($dir)) { New-Item -Path $dir -ItemType Directory -Force | Out-Null }
    return $dir
}

function Remove-OfflineTempDir {
    param([string]$Dir)
    try {
        if ([System.IO.Directory]::Exists($Dir) -and -not (Get-ChildItem -LiteralPath $Dir -Force -ErrorAction SilentlyContinue | Select-Object -First 1)) {
            Remove-Item -LiteralPath $Dir -Force -ErrorAction SilentlyContinue
        }
        $parent = [System.IO.Path]::GetDirectoryName($Dir)
        if ([System.IO.Directory]::Exists($parent) -and -not (Get-ChildItem -LiteralPath $parent -Force -ErrorAction SilentlyContinue | Select-Object -First 1)) {
            Remove-Item -LiteralPath $parent -Force -ErrorAction SilentlyContinue
        }
    } catch { }
}

# Adds files to an archive (existing entries are kept); returns the number of new entries.
# Files: objects with Name, Category, Arch and either Path (local file; Sha1 = expected hash, optional)
# or Entry (entry of another archive, copied as it is).
function Add-OfflineBinFiles {
    param([string]$BinPath, [object[]]$Files, [hashtable]$Meta)
    if ($Files.Count -eq 0) { return 0 }
    Ensure-BinArchiveCompiled
    Set-UiStatus (LF 'Off_Packing' $Files.Count ([System.IO.Path]::GetFileName($BinPath)))
    $w = New-Object WinPEOCs.Archive.BinArchiveWriter($BinPath)
    try {
        # An existing archive keeps its metadata (KeepFrom fills the empty fields from its manifest)
        if (-not [System.IO.File]::Exists($BinPath) -or -not (Get-BinArchiveInfo $BinPath)) {
            $w.Slug = $Meta.Slug; $w.Language = $Meta.Language; $w.Arch = $Meta.Arch
            $w.UpdateId = $Meta.UpdateId; $w.Kind = $Meta.Kind; $w.BuildId = $Meta.BuildId; $w.Label = $Meta.Label
        }
        if ([System.IO.File]::Exists($BinPath)) {
            try {
                $null = $w.KeepFrom($BinPath)
            } catch {
                # A damaged archive is rebuilt from the new files only (it is replaced on commit)
                $m = if ($_.Exception.InnerException) { $_.Exception.InnerException.Message } else { $_.Exception.Message }
                Write-UiLog 'warn' (LF 'Off_BinError' ([System.IO.Path]::GetFileName($BinPath)) $m)
            }
        }
        $i = 0
        $added = 0
        foreach ($f in $Files) {
            $i++
            $script:UI.Detail((LF 'Prog_Count' $i $Files.Count))
            if ($f.Entry) {
                $null = $w.CopyEntry($f.Entry, $f.Name, $f.Category, $f.Arch)
                $added++
                continue
            }
            $e = $w.Add($f.Path, $f.Name, $f.Category, $f.Arch)
            if ($f.Sha1 -and $e.Sha1 -ne ([string]$f.Sha1).ToLowerInvariant()) {
                # Changed after the download check (disk / temp folder): not archived, offered again next time
                $null = $w.Remove($f.Name)
                Write-UiLog 'error' "$(L 'Err_Hash'): $($f.Path)"
                if ($f.Item) { $f.Item.Fail((L 'Err_Hash')) }
                continue
            }
            $added++
        }
        $w.Commit()
    } finally {
        $w.Dispose()
        $script:UI.Detail('')
    }
    $size = (New-Object System.IO.FileInfo($BinPath)).Length
    Write-UiLog 'ok' (LF 'Off_Packed' $added ([System.IO.Path]::GetFileName($BinPath)) (Format-Size $size))
    return $added
}

# Is the file already an entry of this archive (same name and, when known, the same content)?
function Test-OfflineInBin {
    param([string]$BinPath, [string]$Sha1, [string]$Name)
    if (-not $BinPath -or -not $Name) { return $false }
    $names = $script:BinByName[[System.IO.Path]::GetFullPath($BinPath).ToLowerInvariant()]
    if (-not $names) { return $false }
    $e = $names[$Name.ToLowerInvariant()]
    return [bool]($e -and (-not $Sha1 -or $e.Sha1 -eq $Sha1.ToLowerInvariant()))
}

# Archive entry for a file that is found elsewhere (another archive or a loose file)
function ConvertTo-OfflinePackFile {
    param($Source, [string]$Name, [string]$Category, [string]$Arch, [string]$Sha1, [string]$Language = '')
    if ($Source.Type -eq 'bin') { return [PSCustomObject]@{ Entry = $Source.Entry; Path = $null; Name = $Name; Category = $Category; Arch = $Arch; Sha1 = $Sha1; Language = $Language } }
    return [PSCustomObject]@{ Entry = $null; Path = $Source.Path; Name = $Name; Category = $Category; Arch = $Arch; Sha1 = $Sha1; Language = $Language }
}

# --- Microsoft Store Local Experience Packs ---
# UUP lists them only for some releases; the Store has one app per language with a package for every
# Windows release. The catalog (P lines, from the Store catalog) gives each package with the lowest build it
# installs on, its size and SHA-256. The download address comes from Windows Update like the UUP files:
# GetCookie -> SyncUpdates for the app category -> GetExtendedUpdateInfo2 for the update holding the package.
$script:StoreFe3Cookie = $null
$script:StoreFe3Files = @{}

# Package for a UUP row (client, or Server with Desktop Experience): the highest minimum build that the
# build of the row satisfies
function Get-OfflineStoreLxp {
    param($Row, [string]$Language)
    if (-not $Row -or -not $script:RepoIndex -or -not $script:RepoIndex.StoreLxp) { return $null }
    # Server: only the LTSC releases with Desktop Experience (2019, 2022, 2025); the Annual / Semi-Annual
    # Channel releases (1709-20H2, 23H2) are Server Core only
    if (([string]$Row.IsServer -eq 'true' -or [string]$Row.Version -match 'Server') -and [string]$Row.Version -notmatch 'LTSC') { return $null }
    $s = $script:RepoIndex.StoreLxp[$Language]
    if (-not $s) { return $null }
    $build = 0
    if (-not [int]::TryParse(([string]$Row.Build).Split('.')[0], [ref]$build) -or $build -le 0) { return $null }
    $best = $null
    foreach ($e in ([string]$s.Raw).Split(';')) {
        $f = $e.Split(':')
        if ($f.Count -lt 4) { continue }
        $min = [int]$f[0]
        if ($min -le $build -and (-not $best -or $min -gt $best.MinBuild)) {
            $best = [PSCustomObject]@{ MinBuild = $min; Size = [long]$f[1]; Sha256 = $f[2]; FullName = $f[3]
                                       ProductId = $s.ProductId; CategoryId = $s.CategoryId; Language = $Language }
        }
    }
    return $best
}

function New-StoreFe3Envelope {
    param([string]$Action, [string]$Body)
    $now = [DateTime]::UtcNow
    $created = $now.ToString("yyyy-MM-dd'T'HH:mm:ss.fff'Z'", [System.Globalization.CultureInfo]::InvariantCulture)
    $expires = $now.AddMinutes(5).ToString("yyyy-MM-dd'T'HH:mm:ss.fff'Z'", [System.Globalization.CultureInfo]::InvariantCulture)
    return @"
<s:Envelope xmlns:a="http://www.w3.org/2005/08/addressing" xmlns:s="http://www.w3.org/2003/05/soap-envelope">
<s:Header>
<a:Action s:mustUnderstand="1">http://www.microsoft.com/SoftwareDistribution/Server/ClientWebService/$Action</a:Action>
<a:MessageID>urn:uuid:$([guid]::NewGuid().ToString())</a:MessageID>
<a:To s:mustUnderstand="1">https://fe3.delivery.mp.microsoft.com/ClientWebService/client.asmx</a:To>
<o:Security s:mustUnderstand="1" xmlns:o="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd">
<Timestamp xmlns="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd"><Created>$created</Created><Expires>$expires</Expires></Timestamp>
<wuws:WindowsUpdateTicketsToken wsu:id="ClientMSA" xmlns:wsu="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd" xmlns:wuws="http://schemas.microsoft.com/msus/2014/10/WindowsUpdateAuthorization"><TicketType Name="MSA" Version="1.0" Policy="MBI_SSL"><User/></TicketType></wuws:WindowsUpdateTicketsToken>
</o:Security>
</s:Header>
<s:Body>$Body</s:Body>
</s:Envelope>
"@
}

# POST to the Windows Update service (certificate checked); SOAP faults are reported with their text
function Invoke-StoreFe3Request {
    param([string]$Soap)
    try { [System.Net.ServicePointManager]::SecurityProtocol = [System.Net.ServicePointManager]::SecurityProtocol -bor [System.Net.SecurityProtocolType]::Tls12 } catch { }
    $body = [System.Text.Encoding]::UTF8.GetBytes($Soap)
    $last = ''
    foreach ($ep in 'https://fe3cr.delivery.mp.microsoft.com/ClientWebService/client.asmx', 'https://fe3.delivery.mp.microsoft.com/ClientWebService/client.asmx') {
        Assert-UiNotCancelled
        try {
            $req = [System.Net.HttpWebRequest]::Create($ep)
            $req.Method = 'POST'
            $req.ContentType = 'application/soap+xml; charset=utf-8'
            $req.UserAgent = 'Windows-Update-Agent/10.0.10011.16384 Client-Protocol/2.50'
            $req.Timeout = 60000
            $req.ContentLength = $body.Length
            $rs = $req.GetRequestStream()
            try { $rs.Write($body, 0, $body.Length) } finally { $rs.Dispose() }
            $resp = $req.GetResponse()
            try {
                $rd = New-Object System.IO.StreamReader($resp.GetResponseStream(), [System.Text.Encoding]::UTF8)
                return $rd.ReadToEnd()
            } finally { $resp.Dispose() }
        } catch {
            $ex = $_.Exception
            while ($ex.InnerException -and -not ($ex -is [System.Net.WebException])) { $ex = $ex.InnerException }
            $last = $ex.Message
            if ($ex -is [System.Net.WebException] -and $ex.Response) {
                try {
                    $t = (New-Object System.IO.StreamReader($ex.Response.GetResponseStream())).ReadToEnd() -replace '\s+', ' '
                    $m = [regex]::Match($t, '<(?:\w+:)?(?:Text|faultstring|ErrorCode)[^>]*>([^<]+)<')
                    $last += ' · ' + $(if ($m.Success) { $m.Groups[1].Value } elseif ($t.Length -gt 200) { $t.Substring(0, 200) } else { $t })
                } catch { }
            }
            Write-UiLog 'warn' "Microsoft Store ($ep): $last"
        }
    }
    throw "Microsoft Store: $last"
}

function Get-StoreFe3Cookie {
    $now = [DateTime]::UtcNow.ToString("yyyy-MM-dd'T'HH:mm:ss.fff'Z'", [System.Globalization.CultureInfo]::InvariantCulture)
    $body = "<GetCookie xmlns=""http://www.microsoft.com/SoftwareDistribution/Server/ClientWebService""><oldCookie></oldCookie><lastChange>2015-10-21T17:01:07.1472913Z</lastChange><currentTime>$now</currentTime><protocolVersion>1.40</protocolVersion></GetCookie>"
    $resp = Invoke-StoreFe3Request -Soap (New-StoreFe3Envelope -Action 'GetCookie' -Body $body)
    $m = [regex]::Match([string]$resp, '<EncryptedData>([^<]+)</EncryptedData>')
    if (-not $m.Success) { throw 'Microsoft Store: GetCookie' }
    return $m.Groups[1].Value
}

# SyncUpdates answer -> files with their update identity: the file list is in ExtendedUpdateInfo, the
# identity in NewUpdates, both keyed by the update's ID; the fragments are escaped XML
function ConvertFrom-StoreFe3Sync {
    param([string]$Xml)
    $doc = New-Object System.Xml.XmlDocument
    $doc.LoadXml($Xml)
    $ids = @{}
    foreach ($u in $doc.SelectNodes("//*[local-name()='NewUpdates']/*[local-name()='UpdateInfo']")) {
        $id = $u.SelectSingleNode("*[local-name()='ID']")
        $frag = $u.SelectSingleNode("*[local-name()='Xml']")
        if (-not $id -or -not $frag) { continue }
        $tag = [regex]::Match($frag.InnerText, '<UpdateIdentity\s[^>]*>')
        if (-not $tag.Success) { continue }
        $uid = [regex]::Match($tag.Value, 'UpdateID="([^"]+)"')
        $rev = [regex]::Match($tag.Value, 'RevisionNumber="(\d+)"')
        if ($uid.Success) { $ids[$id.InnerText] = @($uid.Groups[1].Value, $(if ($rev.Success) { [int]$rev.Groups[1].Value } else { 1 })) }
    }
    $files = New-Object System.Collections.Generic.List[object]
    foreach ($u in $doc.SelectNodes("//*[local-name()='ExtendedUpdateInfo']//*[local-name()='Update']")) {
        $id = $u.SelectSingleNode("*[local-name()='ID']")
        $frag = $u.SelectSingleNode("*[local-name()='Xml']")
        if (-not $id -or -not $frag -or -not $ids.ContainsKey($id.InnerText)) { continue }
        foreach ($fm in [regex]::Matches($frag.InnerText, '<File\s[^>]*>')) {
            $a = @{}
            foreach ($am in [regex]::Matches($fm.Value, '(\w+)="([^"]*)"')) { $a[$am.Groups[1].Value] = [System.Net.WebUtility]::HtmlDecode($am.Groups[2].Value) }
            if (-not $a['FileName']) { continue }
            $sha1 = ''
            if ($a['Digest'] -and (-not $a['DigestAlgorithm'] -or $a['DigestAlgorithm'] -eq 'SHA1')) {
                try { $sha1 = (([Convert]::FromBase64String($a['Digest']) | ForEach-Object { $_.ToString('x2') }) -join '') } catch { }
            }
            $size = [long]0
            [void][long]::TryParse([string]$a['Size'], [ref]$size)
            $files.Add([PSCustomObject]@{ FileName = $a['FileName']; Size = $size; Sha1 = $sha1; Identifier = [string]$a['InstallerSpecificIdentifier']
                                          UpdateId = $ids[$id.InnerText][0]; Revision = $ids[$id.InnerText][1] })
        }
    }
    return $files.ToArray()
}

function Get-StoreFe3Files {
    param([string]$CategoryId, [string]$Cookie, [int]$Build, [string]$Arch)
    $installed = (@(1, 2, 3, 11, 19, 544, 549, 2359974, 2359977, 5169044, 8788830, 23110993, 23110994, 54341900, 54343656,
                    59830006, 59830007, 59830008, 60484010, 62450018, 62450019, 62450020, 66027979, 66053150, 97657898,
                    98822896, 98959022, 98959023, 98959024, 98959025, 98959026, 104433538, 104900364, 105489019, 117765322,
                    129905029, 130040031, 132387090, 132393049, 133399034, 138537048, 140377312, 143747671, 158941041,
                    158941042, 158941043, 158941044, 159123858, 159130928, 164836897, 164847386, 164848327, 164852241,
                    164852246, 164852252, 164852253) | ForEach-Object { "<int>$_</int>" }) -join ''
    $ver = "10.0.$Build.1"
    $osArch = switch ($Arch) { 'arm64' { 'ARM64' } 'x86' { 'X86' } default { 'AMD64' } }
    $branch = Get-UupBranchFromBuild -Build $ver
    $attrs = "E:App=WU&AppVer=$ver&AttrDataVer=57&BranchReadinessLevel=CB&CurrentBranch=$branch&DefaultUserRegion=244" +
             "&DeviceFamily=Windows.Desktop&FlightRing=Retail&FlightingBranchName=&InstallLanguage=en-US&InstallationType=Client" +
             "&IsDeviceRetailDemo=0&IsFlightingEnabled=0&OSArchitecture=$osArch&OSSkuId=48&OSUILocale=en-US&OSVersion=$ver" +
             "&TelemetryLevel=1&UpdateManagementGroup=2&WuClientVer=$ver"
    $attrs = [System.Security.SecurityElement]::Escape($attrs)
    $body = "<SyncUpdates xmlns=""http://www.microsoft.com/SoftwareDistribution/Server/ClientWebService"">" +
            "<cookie><Expiration>2045-03-11T02:02:48Z</Expiration><EncryptedData>$Cookie</EncryptedData></cookie><parameters>" +
            "<ExpressQuery>false</ExpressQuery><InstalledNonLeafUpdateIDs>$installed</InstalledNonLeafUpdateIDs><OtherCachedUpdateIDs/>" +
            "<SkipSoftwareSync>false</SkipSoftwareSync><NeedTwoGroupOutOfScopeUpdates>true</NeedTwoGroupOutOfScopeUpdates>" +
            "<FilterAppCategoryIds><CategoryIdentifier><Id>$CategoryId</Id></CategoryIdentifier></FilterAppCategoryIds>" +
            "<TreatAppCategoryIdsAsInstalled>true</TreatAppCategoryIdsAsInstalled><AlsoPerformRegularSync>false</AlsoPerformRegularSync><ComputerSpec/>" +
            "<ExtendedUpdateInfoParameters><XmlUpdateFragmentTypes><XmlUpdateFragmentType>Extended</XmlUpdateFragmentType></XmlUpdateFragmentTypes>" +
            "<Locales><string>en-US</string><string>en</string></Locales></ExtendedUpdateInfoParameters>" +
            "<ClientPreferredLanguages><string>en-US</string></ClientPreferredLanguages>" +
            "<ProductsParameters><SyncCurrentVersionOnly>false</SyncCurrentVersionOnly><DeviceAttributes>$attrs</DeviceAttributes>" +
            "<CallerAttributes>Interactive=1;IsSeeker=0;</CallerAttributes><Products/></ProductsParameters></parameters></SyncUpdates>"
    $resp = Invoke-StoreFe3Request -Soap (New-StoreFe3Envelope -Action 'SyncUpdates' -Body $body)
    return ConvertFrom-StoreFe3Sync -Xml $resp
}

# Download address of a Store Local Experience Pack. When the Store has moved on to a newer package for the
# same Windows release, that one is taken (its SHA-1 then comes from Windows Update).
function Resolve-StoreLxpDownloadUrl {
    param($Item)
    $d = $Item.Data
    $build = 0
    [void][int]::TryParse(([string]$Item.Build).Split('.')[0], [ref]$build)
    $key = "$($d.CategoryId)|$build|$($Item.Arch)"
    $files = $script:StoreFe3Files[$key]
    if (-not $files) {
        Set-UiStatus (LF 'Off_StoreLxp' $Item.Name)
        if (-not $script:StoreFe3Cookie) { $script:StoreFe3Cookie = Get-StoreFe3Cookie }
        $files = @(Get-StoreFe3Files -CategoryId $d.CategoryId -Cookie $script:StoreFe3Cookie -Build $build -Arch $Item.Arch)
        $script:StoreFe3Files[$key] = $files
    }
    $appx = @($files | Where-Object { $_.FileName -match '\.appx$' -and $_.Sha1 })
    $pick = @($appx | Where-Object { $_.Identifier -eq $d.FullName -or $_.FileName -like "$($d.FullName).*" })[0]
    if (-not $pick) {
        $series = ([string]$d.FullName -split '_')[1].Split('.')[0]
        $newer = @($appx | Where-Object { (($_.FileName -split '_')[1] -split '\.')[0] -eq $series } |
                   Sort-Object -Descending -Property @{ Expression = { try { [version](($_.FileName -split '_')[1]) } catch { [version]'0.0' } } })
        if ($newer.Count -gt 0) {
            $pick = $newer[0]
            Write-UiLog 'info' (LF 'Off_StoreNewer' (($pick.FileName -split '_')[1]) (([string]$d.FullName -split '_')[1]))
            $Item.Size = [long]$pick.Size
            $Item.Sha1 = $pick.Sha1
            $Item.Sha256 = ''
        }
    }
    if (-not $pick) { throw (LF 'Off_StoreNoPkg' $d.FullName) }
    $xml = Get-DirectMsFe3XmlForUpdate -UpdateID ('{0}_rev.{1}' -f $pick.UpdateId, $pick.Revision) -Build "10.0.$build.1" -Arch $Item.Arch -Sku 48
    $u = Find-UrlBySha1InFe3Xml -XmlContent $xml -Sha1Hex $pick.Sha1
    if (-not $u) { return $null }
    return [PSCustomObject]@{ Url = $u.Url; Expire = $u.Expire; Size = [long]$pick.Size; Source = 'Store' }
}

# License.xml of a Local Experience Pack, saved next to it as <name>.License.xml (for DISM -LicensePath)
function Save-LxpLicense {
    param([string]$AppxPath)
    $out = [System.IO.Path]::Combine([System.IO.Path]::GetDirectoryName($AppxPath), [System.IO.Path]::GetFileNameWithoutExtension($AppxPath) + '.License.xml')
    if ([System.IO.File]::Exists($out)) { return $null }
    try {
        foreach ($n in 'System.IO.Compression.FileSystem', 'System.IO.Compression.ZipFile') { try { Add-Type -AssemblyName $n -ErrorAction Stop } catch { } }
        $zip = [System.IO.Compression.ZipFile]::OpenRead($AppxPath)
        try {
            $e = @($zip.Entries | Where-Object { $_.Name -eq 'License.xml' })[0]
            if (-not $e) { return $null }
            [System.IO.Compression.ZipFileExtensions]::ExtractToFile($e, $out, $true)
            return $out
        } finally { $zip.Dispose() }
    } catch {
        Write-UiLog 'warn' "License.xml: $($_.Exception.Message)"
        return $null
    }
}

# Downloads one UUP file into the temp folder: FE3 link by SHA-1, resumable download, SHA-1 check.
# Returns $true, $false (failed, item marked) or throws OperationCanceledException.
function Save-OfflineLangFile {
    param($Item, [string]$Dest, [int]$No, [int]$Count)
    $sha = ([string]$Item.Sha1).ToLowerInvariant()
    if ([System.IO.File]::Exists($Dest)) {
        # Completed earlier (cancelled run): reused without downloading again
        if ((New-Object System.IO.FileInfo($Dest)).Length -eq $Item.Size -and (Test-FileHashMatch -Item $Item -Path $Dest -Sha1 $sha)) {
            $script:UI.AddTransferred([long]$Item.Size)
            return $true
        }
        Remove-Item -LiteralPath $Dest -Force -ErrorAction SilentlyContinue
    }
    for ($attempt = 1; $attempt -le 2; $attempt++) {
        Assert-UiNotCancelled
        $Item.SetState('Resolving')
        Set-UiStatus (LF 'Job_Resolving' $No $Count $Item.Name)
        $isStore = $Item.Data -and [string]$Item.Data.Kind -eq 'store'
        if ($attempt -gt 1) {
            if ($isStore) { $script:StoreFe3Files = @{}; $script:StoreFe3Cookie = $null } else { Clear-Fe3Cache -UpdateID $Item.UpdateId }
        }
        $info = $null
        try {
            $info = if ($isStore) { Resolve-StoreLxpDownloadUrl -Item $Item } else { Resolve-LangPackFileDownloadUrl -FileName $Item.Name -TagObj $Item }
        } catch [System.OperationCanceledException] {
            throw
        } catch {
            if ($attempt -lt 2) { continue }
            $Item.Fail($_.Exception.Message)
            Write-UiLog 'error' "$($Item.Name): $($_.Exception.Message)"
            return $false
        }
        if (-not $info -or [string]::IsNullOrWhiteSpace([string]$info.Url)) {
            if ($attempt -lt 2) { continue }
            $Item.Fail((L 'Err_NoUrl'))
            Write-UiLog 'error' "$($Item.Name): $(L 'Err_NoUrl')"
            return $false
        }
        $Item.SetState('Downloading')
        Set-UiStatus (LF 'Off_Fetch' $No $Count $Item.Name)
        $r = [WinPEOCs.Net]::Download([string]$info.Url, $Dest, [long]$Item.Size, $script:UI.Observer($Item), $script:UI.Cancel)
        if ($r.Cancelled) { throw (New-Object System.OperationCanceledException) }
        if (-not $r.Success) {
            # Expired or rejected link: ask FE3 for a fresh one once
            if ($attempt -lt 2 -and @(401, 403, 404, 410) -contains $r.StatusCode) { continue }
            $Item.Fail((LF 'Off_DlFailed' $r.Message))
            Write-UiLog 'error' "$($Item.Name): $(LF 'Off_DlFailed' $r.Message)"
            return $false
        }
        if (-not (Test-FileHashMatch -Item $Item -Path $Dest -Sha1 $sha)) {
            Remove-Item -LiteralPath $Dest -Force -ErrorAction SilentlyContinue
            $Item.Fail((L 'Err_Hash'))
            Write-UiLog 'error' "$($Item.Name): $(L 'Err_Hash')"
            return $false
        }
        return $true
    }
    return $false
}

# --- Hybrid downloader: language packs / FOD of one UUP row -> <slug>_<arch>.bin ---
function Invoke-BuildOfflineBinForVersion {
    param(
        [Parameter(Mandatory = $true)]$Row,
        [Parameter(Mandatory = $true)][object[]]$Items,
        [Parameter(Mandatory = $true)][string]$BinPath,
        [object[]]$Extra = @()
    )
    $tempDir = Get-OfflineTempDir $BinPath
    $language = [string]$Items[0].Language
    $tag = Get-OfflineUupTag $Row $language
    foreach ($it in $Items) { $it.Build = $tag.Build; $it.Arch = $tag.Arch; $it.Sku = $tag.Sku; $it.SetState('Queued') }

    $total = [long]0
    foreach ($it in $Items) { $total += [long]$it.Size }
    $script:UI.BeginTransfer($total)
    Write-UiLog 'info' (LF 'Off_DlStart' $Items.Count (Format-Size $total) $Row.Version $Row.Arch ([System.IO.Path]::GetFileName($BinPath)))

    $ready = New-Object System.Collections.Generic.List[object]
    $failed = 0
    $cancelled = $false
    $n = $Items.Count; $i = 0
    try {
        foreach ($it in $Items) {
            $i++
            Assert-UiNotCancelled
            $dest = Join-Path $tempDir $it.Name
            if (Save-OfflineLangFile -Item $it -Dest $dest -No $i -Count $n) {
                $ready.Add([PSCustomObject]@{ Path = $dest; Name = $it.Name; Category = $it.Category; Arch = $Row.Arch; Sha1 = $it.Sha1; Item = $it })
                $it.SetState('Queued', (L 'Off_ToPack'))
            } else {
                $failed++
                $script:UI.AddTransferred([long]$it.Size)
            }
        }
    } catch [System.OperationCanceledException] {
        $cancelled = $true
    }

    if ($cancelled) {
        # Completed downloads stay in Repo\_temp and are reused by the next attempt
        foreach ($it in $Items) {
            if ($it.State -ne [WinPEOCs.ItemState]::Error) { Set-OfflineMissingState $it }
        }
        return [PSCustomObject]@{ Added = 0; Failed = $failed; Cancelled = $true; Ready = $ready.Count }
    }

    $added = 0
    if ($ready.Count -gt 0) {
        $meta = @{ Slug = (Get-VersionSlug -VersionText $Row.Version); Language = $language; Arch = $Row.Arch
                   UpdateId = $Row.UpdateId; Kind = 'lang'; BuildId = ''; Label = $Row.Version }
        # Files of this row that other archives already hold are copied in too, so the archive of the
        # row is complete on its own (it can be moved to another computer alone)
        $pack = @($ready.ToArray()) + @($Extra)
        $added = Add-OfflineBinFiles -BinPath $BinPath -Files $pack -Meta $meta
        foreach ($f in $ready) {
            Remove-Item -LiteralPath $f.Path -Force -ErrorAction SilentlyContinue
            if ($f.Item.State -ne [WinPEOCs.ItemState]::Error) { $f.Item.SetState('Idle') }
        }
    }
    Remove-OfflineTempDir $tempDir
    Update-OfflineSources
    return [PSCustomObject]@{ Added = $added; Failed = $failed; Cancelled = $false; Ready = $ready.Count }
}

# expand.exe -F:<fil id> extracts one file of an ADK container (kept as a function so tests can replace it)
function Invoke-OfflineCabExtract {
    param([string]$Cab, [string]$FilId, [string]$DestDir)
    $out = Join-Path $DestDir $FilId
    Remove-Item -LiteralPath $out -Force -ErrorAction SilentlyContinue
    & (Join-Path $env:SystemRoot 'System32\expand.exe') $Cab "-F:$FilId" $DestDir | Out-Null
    if ([System.IO.File]::Exists($out)) { return $out }
    return $null
}

# --- Hybrid downloader: Windows PE packages -> winpe_<buildId>_<arch>.bin ---
# Files: Get-OfflinePeFiles records that are missing; ItemsByName: component -> PackageItem
function Invoke-BuildOfflinePeBin {
    param(
        [Parameter(Mandatory = $true)][string]$BuildId,
        [Parameter(Mandatory = $true)][string]$Arch,
        [Parameter(Mandatory = $true)][string]$Language,
        [string]$Label = '',
        [Parameter(Mandatory = $true)][object[]]$Files,
        [Parameter(Mandatory = $true)][hashtable]$ItemsByName,
        [Parameter(Mandatory = $true)][string]$BinPath,
        [Parameter(Mandatory = $true)][object[]]$Plan,
        [object[]]$Extra = @()
    )
    $tempDir = Get-OfflineTempDir $BinPath
    $filesDir = Join-Path $tempDir 'files'
    $total = [long]0
    foreach ($c in $Plan) { if (-not [System.IO.File]::Exists($c.Local)) { $total += [long]$c.Size } }
    $script:UI.BeginTransfer($total)
    Write-UiLog 'info' (LF 'Off_PeDlStart' $Files.Count $BuildId $Arch $Plan.Count (Format-Size $total) ([System.IO.Path]::GetFileName($BinPath)))
    foreach ($it in $ItemsByName.Values) { if ($it.State -ne [WinPEOCs.ItemState]::Idle) { $it.SetState('Queued') } }

    $ready = New-Object System.Collections.Generic.List[object]
    $failed = 0
    $cancelled = $false
    $ci = 0
    $fileNo = 0
    try {
        foreach ($c in $Plan) {
            $ci++
            Assert-UiNotCancelled
            $comps = @($c.Records | ForEach-Object { $_.ComponentName } | Select-Object -Unique)
            foreach ($cn in $comps) { $it = $ItemsByName[$cn]; if ($it -and $it.State -ne [WinPEOCs.ItemState]::Error) { $it.SetState('Downloading') } }
            if (-not [System.IO.File]::Exists($c.Local)) {
                Set-UiStatus (LF 'Job_Container' $ci $Plan.Count $c.Name)
                Write-UiLog 'info' "$(LF 'Job_Container' $ci $Plan.Count $c.Name): $($c.Url)"
                $r = [WinPEOCs.Net]::Download($c.Url, $c.Local, [long]$c.Size, $script:UI.Observer($null), $script:UI.Cancel)
                if ($r.Cancelled) { throw (New-Object System.OperationCanceledException) }
                if (-not $r.Success) {
                    Write-UiLog 'error' "$($c.Name): $(LF 'Off_DlFailed' $r.Message)"
                    foreach ($cn in $comps) { $it = $ItemsByName[$cn]; if ($it) { $it.Fail((LF 'Off_DlFailed' $r.Message)) } }
                    $failed += $c.Records.Count
                    continue
                }
            }
            foreach ($rec in $c.Records) {
                $fileNo++
                Assert-UiNotCancelled
                $f = $rec.File
                $it = $ItemsByName[$f.Component]
                if ($it -and $it.State -ne [WinPEOCs.ItemState]::Error) { $it.SetState('Extracting') }
                Set-UiStatus (LF 'Job_Extract' $fileNo $Files.Count $f.RelativePath)
                $dest = Join-Path $filesDir (ConvertTo-LocalRelativePath $f.RelativePath)
                $destDir = [System.IO.Path]::GetDirectoryName($dest)
                if (-not [System.IO.Directory]::Exists($destDir)) { New-Item -Path $destDir -ItemType Directory -Force | Out-Null }
                $x = Invoke-OfflineCabExtract -Cab $c.Local -FilId $rec.FilHashId -DestDir $destDir
                $problem = $null
                if (-not $x) {
                    $problem = "$(L 'Err_Extract'): $($f.RelativePath)"
                } else {
                    if ([System.IO.File]::Exists($dest)) { Remove-Item -LiteralPath $dest -Force }
                    Move-Item -LiteralPath $x -Destination $dest -Force
                    $len = (New-Object System.IO.FileInfo($dest)).Length
                    if ($rec.FileSize -gt 0 -and $len -ne $rec.FileSize) {
                        $problem = (LF 'Err_Incomplete' $len $rec.FileSize)
                    } elseif ($f.Sha1) {
                        $h = [WinPEOCs.Net]::HashFile($dest, 'SHA1', $script:UI.Cancel, $null)
                        if ($null -eq $h) { throw (New-Object System.OperationCanceledException) }
                        if ($h -ne $f.Sha1) { $problem = "$(L 'Err_Hash'): $($f.RelativePath)" }
                    }
                }
                if ($problem) {
                    $failed++
                    if ($it) { $it.Fail($problem) }
                    Write-UiLog 'error' $problem
                    Remove-Item -LiteralPath $dest -Force -ErrorAction SilentlyContinue
                    continue
                }
                $ready.Add([PSCustomObject]@{ Path = $dest; Name = $f.RelativePath; Category = $f.Component; Arch = $Arch; Sha1 = $f.Sha1; Language = $f.Language })
            }
            # Containers are large; they are removed as soon as their files are extracted
            Remove-Item -LiteralPath $c.Local -Force -ErrorAction SilentlyContinue
        }
    } catch [System.OperationCanceledException] {
        $cancelled = $true
    }

    if ($cancelled) {
        foreach ($it in $ItemsByName.Values) {
            if ($it.State -ne [WinPEOCs.ItemState]::Error -and $it.State -ne [WinPEOCs.ItemState]::Idle) { Set-OfflineMissingState $it }
        }
        return [PSCustomObject]@{ Added = 0; Failed = $failed; Cancelled = $true; Ready = $ready.Count }
    }

    $added = 0
    if ($ready.Count -gt 0) {
        # Neutral packages go to winpe_<build>_<arch>.bin, language packages to the archive of their language
        $byTarget = [ordered]@{}
        foreach ($f in (@($ready.ToArray()) + @($Extra))) {
            $target = Get-PeBinPath -BuildId $BuildId -Arch $Arch -Language $f.Language
            if (-not $byTarget.Contains($target)) { $byTarget[$target] = New-Object System.Collections.Generic.List[object] }
            $byTarget[$target].Add($f)
        }
        foreach ($target in @($byTarget.Keys)) {
            $tl = if (@($byTarget[$target] | Where-Object { $_.Language -ne 'neutral' }).Count -gt 0) { $Language } else { 'neutral' }
            $meta = @{ Slug = [System.IO.Path]::GetFileNameWithoutExtension($target); Language = $tl; Arch = $Arch
                       UpdateId = ''; Kind = 'winpe'; BuildId = $BuildId; Label = $Label }
            $added += Add-OfflineBinFiles -BinPath $target -Files $byTarget[$target].ToArray() -Meta $meta
        }
    }
    try { if ([System.IO.Directory]::Exists($filesDir)) { Remove-Item -LiteralPath $filesDir -Recurse -Force -ErrorAction SilentlyContinue } } catch { }
    Remove-OfflineTempDir $tempDir
    Update-OfflineSources
    return [PSCustomObject]@{ Added = $added; Failed = $failed; Cancelled = $false; Ready = $ready.Count }
}

# Container download plan for missing Windows PE files (engine index: container URL, size, fil id)
function Get-OfflinePeDownloadPlan {
    param([string]$BuildId, [string]$Arch, [string]$Language, [object[]]$Files, [string]$BinPath)
    $pkgs = @(Get-WinPEMsiDatabaseIndex -BuildId $BuildId -Architecture $Arch -Language @('neutral', $Language))
    $byPath = @{}
    foreach ($p in $pkgs) { $byPath[([string]$p.RelativePath).ToLowerInvariant()] = $p }
    $tempDir = Get-OfflineTempDir $BinPath
    $groups = @{}
    $order = New-Object System.Collections.Generic.List[string]
    $unknown = New-Object System.Collections.Generic.List[object]
    foreach ($f in $Files) {
        $p = $byPath[([string]$f.RelativePath).ToLowerInvariant()]
        if (-not $p -or -not $p.ContainerCabUrl -or -not $p.FilHashId) { $unknown.Add($f); continue }
        $url = [string]$p.ContainerCabUrl
        if (-not $groups.ContainsKey($url)) {
            $groups[$url] = [PSCustomObject]@{ Name = [string]$p.ContainerCabName; Url = $url; Size = [long]$p.ContainerCabSize
                                               Local = (Join-Path $tempDir ([string]$p.ContainerCabName))
                                               Records = New-Object System.Collections.Generic.List[object] }
            $order.Add($url)
        }
        $groups[$url].Records.Add([PSCustomObject]@{ File = $f; FilHashId = [string]$p.FilHashId; FileSize = [long]$p.FileSize; ComponentName = $f.Component })
    }
    $plan = @($order | ForEach-Object { $groups[$_] })
    $bytes = [long]0
    foreach ($c in $plan) { if (-not [System.IO.File]::Exists($c.Local)) { $bytes += $c.Size } }
    return [PSCustomObject]@{ Containers = $plan; Unknown = $unknown.ToArray(); DownloadBytes = $bytes }
}

# --- Offline request handlers ---
function Invoke-OfflineLangFetch {
    param($Req)
    Assert-OfflineRepo
    $updateId = $Req.GetString('UpdateId')
    $version  = $Req.GetString('Version')
    $arch     = $Req.GetString('Arch')
    $lang     = $Req.GetString('Lang')
    Update-OfflineSources

    $row = Get-OfflineRow -UpdateId $updateId -Version $version -Arch $arch
    $binPath = if ($row) { Get-LangBinPath -Version $version -Arch $arch -Language $lang } else { '' }
    $list = New-Object 'System.Collections.Generic.List[WinPEOCs.PackageItem]'
    $missing = New-Object System.Collections.Generic.List[object]
    $elsewhere = New-Object System.Collections.Generic.List[object]
    $missingBytes = [long]0
    if ($row -and (Test-OfflineLanguage $lang)) {
        $tag = [PSCustomObject]@{ Build = $row.Build; Arch = $(if ($row.Arch -eq 'x64') { 'amd64' } else { $row.Arch }); Sku = $row.Sku }
        $idx = 0
        $files = New-Object System.Collections.Generic.List[object]
        foreach ($f in (Get-OfflineLangFiles -Row $row -Language $lang)) { $files.Add($f) }
        # Local Experience Pack from the Microsoft Store when UUP has none for this row (right after the language pack)
        if ($files.Count -gt 0 -and -not @($files | Where-Object { $_.Name -match '^LanguageExperiencePack[._]' }).Count) {
            $lxp = Get-OfflineStoreLxp -Row $row -Language $lang
            if ($lxp) {
                $pos = if ($files[0].Category -eq 'lp') { 1 } else { 0 }
                $files.Insert($pos, [PSCustomObject]@{ Category = 'lp'; Sha1 = ''; Size = $lxp.Size; Name = "LanguageExperiencePack.$lang.Neutral.appx"; Store = $lxp })
            }
        }
        foreach ($f in $files) {
            $it = New-Object WinPEOCs.PackageItem
            $it.Key       = $f.Name
            $it.Name      = $f.Name
            $it.Category  = $f.Category
            $it.SortIndex = $idx
            $it.Size      = [long]$f.Size
            $it.Sha1      = $f.Sha1
            $it.UpdateId  = $updateId
            $it.Language  = $lang
            $it.Build     = $tag.Build
            $it.Arch      = $tag.Arch
            $it.Sku       = $tag.Sku
            if ($f.Store) {
                $it.Sha256 = $f.Store.Sha256
                $it.Data = [PSCustomObject]@{ Kind = 'store'; ProductId = $f.Store.ProductId; CategoryId = $f.Store.CategoryId
                                              FullName = $f.Store.FullName; MinBuild = $f.Store.MinBuild }
            }
            $source = Get-OfflineObjectSource -Sha1 $f.Sha1 -FileName $f.Name -Size $it.Size -BinPath $binPath
            if (-not $source) {
                Set-OfflineMissingState $it
                $missing.Add($it)
                $missingBytes += [long]$it.Size
            } elseif (-not (Test-OfflineInBin -BinPath $binPath -Sha1 $f.Sha1 -Name $f.Name)) {
                $elsewhere.Add((ConvertTo-OfflinePackFile -Source $source -Name $f.Name -Category $f.Category -Arch $row.Arch -Sha1 $f.Sha1))
            }
            $list.Add($it)
            $idx++
        }
    }
    Write-UiLog 'info' "Liste: $version / $arch / $lang (UpdateID $updateId)"
    $script:UI.SetLangItems($list.ToArray(), "$version · $arch · $lang")
    if ($list.Count -eq 0) {
        $script:UI.ShowMessage('info', (L 'Msg_InfoTitle'), (LF 'Job_NoFiles' $version $arch $lang))
        $script:UI.Done($Req, $true, (LF 'Job_LangFetchDone' 0 (L 'Off_Src')), 'ok')
        return
    }
    if ($missing.Count -eq 0) {
        $script:UI.Done($Req, $true, (LF 'Job_LangFetchDone' $list.Count (L 'Off_Src')), 'ok')
        return
    }

    # Hybrid mode: offer to download the missing files once and add them to the archive of this row
    $binName = [System.IO.Path]::GetFileName($binPath)
    $details = @(
        (New-Object WinPEOCs.KeyValueRow((L 'Off_KVersion'), $version)),
        (New-Object WinPEOCs.KeyValueRow((L 'Dlg_Arch'), $arch)),
        (New-Object WinPEOCs.KeyValueRow((L 'Off_KLanguage'), $lang)),
        (New-Object WinPEOCs.KeyValueRow((L 'Off_KMissing'), (LF 'Off_KFiles' $missing.Count (Format-Size $missingBytes)), $true))
    )
    if ($elsewhere.Count -gt 0) { $details += (New-Object WinPEOCs.KeyValueRow((L 'Off_KElsewhere'), (LF 'Off_KElsewhereVal' $elsewhere.Count))) }
    $details += (New-Object WinPEOCs.KeyValueRow((L 'Off_KArchive'), (Join-Path $script:RepoIndex.Dir $binName)))
    $ok = $script:UI.Confirm('download', (L 'Off_DlTitle'), (LF 'Off_DlText' $missing.Count $binName), (L 'Off_DlOk'), (L 'Off_DlNote'), [WinPEOCs.KeyValueRow[]]$details)
    if (-not $ok) {
        $script:UI.Done($Req, $true, (LF 'Job_LangFetchDone' $list.Count (L 'Off_Src')), 'ok')
        Write-OfflineMissingSummary $missing.Count $missingBytes
        return
    }

    $res = Invoke-BuildOfflineBinForVersion -Row $row -Items $missing.ToArray() -BinPath $binPath -Extra $elsewhere.ToArray()
    $still = 0
    foreach ($it in $missing) {
        if (Get-OfflineObjectSource -Sha1 $it.Sha1 -FileName $it.Name -Size $it.Size -BinPath $binPath) {
            if ($it.State -ne [WinPEOCs.ItemState]::Error) { $it.SetState('Idle') }
        } else {
            $still++
            if ($it.State -ne [WinPEOCs.ItemState]::Error) { Set-OfflineMissingState $it }
        }
    }
    $null = Update-OfflineRepoInfo
    if ($res.Cancelled) {
        $script:UI.Done($Req, $false, (LF 'Off_DlCancelled' $res.Ready), 'warn')
    } elseif ($res.Failed -gt 0 -or $still -gt 0) {
        $msg = LF 'Off_DlPartial' $res.Added ([Math]::Max($res.Failed, $still))
        $script:UI.ShowMessage('warn', (L 'Msg_WarnTitle'), $msg)
        $script:UI.Done($Req, $false, $msg, 'warn')
    } else {
        $script:UI.Done($Req, $true, (LF 'Off_DlDone' $res.Added $binName), 'ok')
    }
}

function Invoke-OfflineLangCopy {
    param($Req)
    Assert-OfflineRepo
    $items  = @($Req.GetItems('Items'))
    $root   = $Req.GetString('Root')
    $arch   = $Req.GetString('Arch')
    $version = $Req.GetString('Version')
    $skip   = $Req.GetBool('SkipExisting')
    $verify = $Req.GetBool('Verify')
    if ([string]::IsNullOrWhiteSpace($root)) { throw (L 'Off_NoOutput') }
    if (-not $arch) { $arch = 'x64' }
    Update-OfflineSources
    $lang   = $Req.GetString('Lang')
    if (-not $lang -and $items.Count -gt 0) { $lang = [string]$items[0].Language }
    $binPath = if ($version) { Get-LangBinPath -Version $version -Arch $arch -Language $lang } else { '' }

    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $total = [long]0
    foreach ($it in $items) { $total += [long]$it.Size }
    $script:UI.BeginTransfer($total)
    $ok = 0; $fail = 0; $skipped = 0; $bytes = [long]0
    $n = $items.Count; $i = 0
    Write-UiLog 'info' "Kopyalama başladı: $n dosya ($(Format-Size $total)) -> $root"

    foreach ($it in $items) {
        $i++
        if (Test-UiCancel) { $it.SetState('Cancelled'); continue }
        $isLp = $it.Category -eq 'lp' -or $it.Name -match 'LanguagePack|_lp\.esd$'
        $targetDir = if ($isLp) { Join-Path $root 'Langs' } else { Join-Path (Join-Path $root 'OnDemand') $arch }
        $dest = Join-Path $targetDir $it.Name
        try {
            if ($skip -and (Test-Path -LiteralPath $dest -PathType Leaf)) {
                $len = (Get-Item -LiteralPath $dest).Length
                if ($it.Size -le 0 -or $len -eq $it.Size) {
                    $valid = $true
                    if ($verify -and $it.Sha1) { $valid = Test-FileHashMatch -Item $it -Path $dest }
                    if ($valid) {
                        if ($it.Name -match '^LanguageExperiencePack\..+\.appx$') { $lic = Save-LxpLicense -AppxPath $dest; if ($lic) { Write-UiLog 'info' (LF 'Off_LxpLicense' $lic) } }
                        $it.SetState('Exists')
                        $script:UI.AddTransferred([long]$it.Size)
                        $skipped++
                        continue
                    }
                }
            }
            $source = Get-OfflineObjectSource -Sha1 $it.Sha1 -FileName $it.Name -Size $it.Size -BinPath $binPath
            if (-not $source) {
                $script:UI.AddTransferred([long]$it.Size)
                throw (LF 'Off_NotInRepoTip' $(if ($binPath) { [System.IO.Path]::GetFileName($binPath) } else { '.bin' }))
            }
            $it.SetState('Downloading')
            Set-UiStatus (LF 'Job_Download' $i $n $it.Name)
            if ($source.Type -eq 'bin') {
                # Archive entries are always checked against the catalog SHA-1 (it is computed while copying)
                $sha = if ($it.Sha1) { [string]$it.Sha1 } else { [string]$source.Entry.Sha1 }
                $stream = [WinPEOCs.Archive.BinArchive]::OpenEntry($source.Entry)
                try {
                    $r = [WinPEOCs.Net]::CopyStream($stream, [long]$source.Entry.OriginalSize, $dest, [long]$it.Size, $sha, $script:UI.Observer($it), $script:UI.Cancel)
                } finally {
                    $stream.Dispose()
                }
            } else {
                $sha = if ($verify -or $source.ByName) { [string]$it.Sha1 } else { '' }
                $r = [WinPEOCs.Net]::CopyFile($source.Path, $dest, [long]$it.Size, $sha, $script:UI.Observer($it), $script:UI.Cancel)
            }
            if ($r.Cancelled) { $it.SetState('Cancelled'); continue }
            if (-not $r.Success) { throw $r.Message }
            $it.SetState('Done')
            $ok++
            $bytes += [long]$r.Bytes
            Write-UiLog 'ok' "$($it.Name) ($(Format-Size $r.Bytes)) -> $targetDir"
            if ($it.Name -match '^LanguageExperiencePack\..+\.appx$') { $lic = Save-LxpLicense -AppxPath $dest; if ($lic) { Write-UiLog 'info' (LF 'Off_LxpLicense' $lic) } }
        }
        catch [System.OperationCanceledException] {
            $it.SetState('Cancelled')
        }
        catch {
            $fail++
            $msg = $_.Exception.Message
            $it.Fail($msg)
            Write-UiLog 'error' "$($it.Name): $msg"
        }
    }

    if (Test-UiCancel) {
        $script:UI.Done($Req, $false, (L 'Job_Cancelled'), 'warn')
        return
    }
    if ($fail -gt 0 -or $skipped -gt 0) {
        $msg = LF 'Job_DlDoneErr' $ok $fail $skipped
        $level = if ($fail -gt 0) { 'warn' } else { 'ok' }
    } else {
        $msg = LF 'Job_DlDone' $ok (Format-Size $bytes)
        $level = 'ok'
    }
    if ($sw.Elapsed.TotalSeconds -gt 8 -or $fail -gt 0) {
        $kind = if ($fail -gt 0) { 'warn' } else { 'ok' }
        $script:UI.ShowMessage($kind, (L 'Msg_DoneTitle'), ($msg + "`n`n" + $root))
    }
    $script:UI.Done($Req, ($fail -eq 0), $msg, $level)
}

# Component rows of a Windows PE build: Setup-Client for client builds, Setup-Server / ASZ for server builds
function Get-OfflinePeComponents {
    param([object[]]$Files, [bool]$IsServer)
    $byComponent = @{}
    foreach ($f in $Files) {
        $c = $f.Component
        if (-not $IsServer -and ($c -eq 'WinPE-Setup-Server' -or $c -eq 'WinPE-Setup-ASZ')) { continue }
        if ($IsServer -and $c -eq 'WinPE-Setup-Client') { continue }
        if (-not $byComponent.ContainsKey($c)) { $byComponent[$c] = New-Object System.Collections.Generic.List[object] }
        $byComponent[$c].Add($f)
    }
    return $byComponent
}

function Get-OfflinePeFileSource {
    param($File)
    $bin = Get-PeBinPath -BuildId $File.BuildId -Arch $File.Arch -Language $File.Language
    return (Get-OfflineObjectSource -Sha1 $File.Sha1 -BinPath $bin -EntryName $File.RelativePath)
}

function Invoke-OfflinePeFetch {
    param($Req)
    Assert-OfflineRepo
    $buildId  = $Req.GetString('BuildId')
    $arch     = $Req.GetString('Arch')
    $lang     = $Req.GetString('Lang')
    $version  = $Req.GetString('Version')
    $isServer = $Req.GetBool('IsServer')
    Update-OfflineSources

    $files = @(Get-OfflinePeFiles -BuildId $buildId -Arch $arch -Language $lang)
    if ($files.Count -eq 0) {
        $script:UI.SetPeItems([WinPEOCs.PackageItem[]]@(), [string[]]@(), '', '')
        $script:UI.ShowMessage('info', (L 'Msg_InfoTitle'), (LF 'Job_PeNoFiles' "$buildId / $arch / $lang"))
        $script:UI.Done($Req, $true, (LF 'Job_PeNoFiles' "$buildId / $arch / $lang"), 'warn')
        return
    }
    $fromCatalog = @($files | Where-Object { $_.Sha1 }).Count -eq $files.Count
    $binPath = Get-PeBinPath -BuildId $buildId -Arch $arch -Language $lang
    $byComponent = Get-OfflinePeComponents -Files $files -IsServer $isServer
    $prio = @{ 'lp' = 0; 'core' = 1; 'other' = 2; 'server' = 3 }
    $sortedNames = @($byComponent.Keys | Sort-Object -Property @{ Expression = { $prio[(Get-PeCategory $_)] }; Ascending = $true }, @{ Expression = { $_ }; Ascending = $true })

    $list = New-Object 'System.Collections.Generic.List[WinPEOCs.PackageItem]'
    $itemsByName = @{}
    $missingFiles = New-Object System.Collections.Generic.List[object]
    $elsewhere = New-Object System.Collections.Generic.List[object]
    $missingBytes = [long]0
    $idx = 0
    foreach ($compName in $sortedNames) {
        $group = $byComponent[$compName]
        $total = [long]0
        $compMissing = $false
        foreach ($g in $group) {
            $total += [long]$g.Size
            $src = Get-OfflinePeFileSource -File $g
            if (-not $src) {
                $compMissing = $true
                $missingFiles.Add($g)
                $missingBytes += [long]$g.Size
            } elseif (-not (Test-OfflineInBin -BinPath (Get-PeBinPath -BuildId $buildId -Arch $arch -Language $g.Language) -Sha1 $g.Sha1 -Name $g.RelativePath)) {
                $elsewhere.Add((ConvertTo-OfflinePackFile -Source $src -Name $g.RelativePath -Category $g.Component -Arch $arch -Sha1 $g.Sha1 -Language $g.Language))
            }
        }
        $it = New-Object WinPEOCs.PackageItem
        $it.Key        = $compName
        $it.Name       = $compName
        $it.DescTr     = [string]$script:OcDescriptions[$compName]
        $it.DescEn     = [string]$script:OcDescriptionsEn[$compName]
        $it.Category   = Get-PeCategory $compName
        $it.SortIndex  = $idx
        $it.Size       = $total
        $it.FileCount  = $group.Count
        $it.BuildId    = $buildId
        $it.Arch       = $arch
        $it.Language   = $lang
        $it.Languages  = [string[]]@('neutral', $lang)
        $it.Containers = [string[]]@()
        if ($script:OcDependencies.ContainsKey($compName)) { $it.Dependencies = [string[]]@($script:OcDependencies[$compName]) }
        if ($compMissing) { Set-OfflineMissingState $it }
        $list.Add($it)
        $itemsByName[$compName] = $it
        $idx++
    }
    $b = $script:RepoIndex.Builds[$buildId]
    $buildInfo = if ($b -and $b.ProductVersion) { "ADK $($b.ProductVersion)" } else { '' }
    $script:UI.SetPeItems($list.ToArray(), [string[]]@(), "$version · $arch · $lang", $buildInfo)
    $srcText = if ($fromCatalog) { L 'Off_Src' } else { L 'Off_SrcEngine' }
    if ($missingFiles.Count -eq 0) {
        $script:UI.Done($Req, $true, (LF 'Job_PeFetchDone' $list.Count $srcText), 'ok')
        return
    }

    # Hybrid mode: download the ADK containers once, extract the missing packages, add them to the archive
    $plan = $null
    try {
        $plan = Get-OfflinePeDownloadPlan -BuildId $buildId -Arch $arch -Language $lang -Files $missingFiles.ToArray() -BinPath $binPath
    } catch {
        Write-UiLog 'warn' "WinPE: $($_.Exception.Message)"
    }
    if (-not $plan -or $plan.Containers.Count -eq 0) {
        $script:UI.Done($Req, $true, (LF 'Job_PeFetchDone' $list.Count $srcText), 'ok')
        Write-OfflineMissingSummary $missingFiles.Count $missingBytes
        return
    }
    # Archives that receive files: the language archive and, for missing neutral packages, the base archive
    $targets = New-Object System.Collections.Generic.List[string]
    foreach ($g in (@($missingFiles.ToArray()) + @($elsewhere.ToArray()))) {
        $n = [System.IO.Path]::GetFileName((Get-PeBinPath -BuildId $buildId -Arch $arch -Language $g.Language))
        if (-not $targets.Contains($n)) { $targets.Add($n) }
    }
    $baseName = [System.IO.Path]::GetFileName((Get-PeBinPath -BuildId $buildId -Arch $arch -Language 'neutral'))
    if ($targets.Remove($baseName)) { $targets.Insert(0, $baseName) }
    $binName = $targets -join ', '
    $missingComps = @($missingFiles | ForEach-Object { $_.Component } | Select-Object -Unique)
    $details = @(
        (New-Object WinPEOCs.KeyValueRow((L 'Dlg_Build'), $(if ($buildInfo) { "$buildId · $buildInfo" } else { $buildId }))),
        (New-Object WinPEOCs.KeyValueRow((L 'Dlg_Arch'), $arch)),
        (New-Object WinPEOCs.KeyValueRow((L 'Dlg_Langs'), "neutral, $lang")),
        (New-Object WinPEOCs.KeyValueRow((L 'Off_KMissing'), (LF 'Off_KComponents' $missingComps.Count $missingFiles.Count (Format-Size $missingBytes)))),
        (New-Object WinPEOCs.KeyValueRow((L 'Dlg_Download'), (LF 'Dlg_Containers' (Format-Size $plan.DownloadBytes) $plan.Containers.Count), $true))
    )
    $multi = $targets.Count -gt 1
    if ($elsewhere.Count -gt 0) { $details += (New-Object WinPEOCs.KeyValueRow((L 'Off_KElsewhere'), (LF $(if ($multi) { 'Off_KElsewhereValMulti' } else { 'Off_KElsewhereVal' }) $elsewhere.Count))) }
    $details += (New-Object WinPEOCs.KeyValueRow((L $(if ($multi) { 'Off_KArchives' } else { 'Off_KArchive' })), $binName))
    $ok = $script:UI.Confirm('download', (L 'Off_DlTitle'), (LF $(if ($multi) { 'Off_DlTextPeMulti' } else { 'Off_DlTextPe' }) $missingComps.Count $binName), (L 'Off_DlOk'), (L 'Off_DlNotePe'), [WinPEOCs.KeyValueRow[]]$details)
    if (-not $ok) {
        $script:UI.Done($Req, $true, (LF 'Job_PeFetchDone' $list.Count $srcText), 'ok')
        Write-OfflineMissingSummary $missingFiles.Count $missingBytes
        return
    }

    $missingSet = @{}
    foreach ($c in $missingComps) { $missingSet[$c] = $itemsByName[$c] }
    $res = Invoke-BuildOfflinePeBin -BuildId $buildId -Arch $arch -Language $lang -Label $version -Files $missingFiles.ToArray() -ItemsByName $missingSet -BinPath $binPath -Plan $plan.Containers -Extra $elsewhere.ToArray()
    $still = 0
    foreach ($c in $missingComps) {
        $it = $itemsByName[$c]
        $gone = $false
        foreach ($g in $byComponent[$c]) { if (-not (Get-OfflinePeFileSource -File $g)) { $gone = $true; break } }
        if ($gone) {
            $still++
            if ($it.State -ne [WinPEOCs.ItemState]::Error) { Set-OfflineMissingState $it }
        } elseif ($it.State -ne [WinPEOCs.ItemState]::Error) {
            $it.SetState('Idle')
        }
    }
    $null = Update-OfflineRepoInfo
    if ($res.Cancelled) {
        $script:UI.Done($Req, $false, (LF 'Off_DlCancelled' 0), 'warn')
    } elseif ($res.Failed -gt 0 -or $still -gt 0 -or $plan.Unknown.Count -gt 0) {
        $msg = LF 'Off_DlPartial' $res.Added ([Math]::Max($res.Failed + $plan.Unknown.Count, $still))
        $script:UI.ShowMessage('warn', (L 'Msg_WarnTitle'), $msg)
        $script:UI.Done($Req, $false, $msg, 'warn')
    } else {
        $script:UI.Done($Req, $true, (LF 'Off_DlDone' $res.Added $binName), 'ok')
    }
}

function Invoke-OfflinePeCopy {
    param($Req)
    Assert-OfflineRepo
    $items   = @($Req.GetItems('Items'))
    $buildId = $Req.GetString('BuildId')
    $arch    = $Req.GetString('Arch')
    $lang    = $Req.GetString('Lang')
    $root    = $Req.GetString('Root')
    $skip    = $Req.GetBool('SkipExisting')
    $verify  = $Req.GetBool('Verify')
    if ([string]::IsNullOrWhiteSpace($root)) { throw (L 'Off_NoOutput') }
    Update-OfflineSources

    $byName = @{}
    foreach ($it in $items) { $byName[[string]$it.Name] = $it }
    $files = @(Get-OfflinePeFiles -BuildId $buildId -Arch $arch -Language $lang | Where-Object { $byName.ContainsKey($_.Component) })
    if ($files.Count -eq 0) { throw (LF 'Job_PeNoFiles' "$buildId / $arch / $lang") }

    # Same folder layout as the online edition: <root>\WinPE\<BuildId>\<arch>\WinPE_OCs\...
    $archRoot = Join-Path (Join-Path (Join-Path $root 'WinPE') $buildId) $arch
    Write-UiLog 'info' "WinPE: $buildId / $arch / neutral,$lang · $($items.Count) bileşen, $($files.Count) dosya"
    foreach ($it in $items) {
        $it.FileCount = @($files | Where-Object { $_.Component -eq $it.Name }).Count
        $it.FilesDone = 0
    }

    $pending = New-Object System.Collections.Generic.List[object]
    foreach ($f in $files) {
        $dest = Join-Path $archRoot (ConvertTo-LocalRelativePath $f.RelativePath)
        $it = $byName[$f.Component]
        if ($skip -and $f.Size -gt 0 -and (Test-Path -LiteralPath $dest -PathType Leaf) -and ((Get-Item -LiteralPath $dest).Length -eq $f.Size)) {
            $same = $true
            if ($verify -and $f.Sha1) {
                Set-UiStatus (LF 'Job_Verify' $f.RelativePath)
                $h = [WinPEOCs.Net]::HashFile($dest, 'SHA1', $script:UI.Cancel, $null)
                if ($null -eq $h) { throw (New-Object System.OperationCanceledException) }
                $same = ($h -eq $f.Sha1)
            }
            if ($same) {
                $it.FilesDone = $it.FilesDone + 1
                if ($it.FilesDone -ge $it.FileCount) { $it.SetState('Exists') } else { $it.SetState('Partial') }
                continue
            }
        }
        $pending.Add([PSCustomObject]@{ File = $f; Dest = $dest })
    }

    $total = [long]0
    foreach ($e in $pending) { $total += [long]$e.File.Size }
    $script:UI.BeginTransfer($total)
    $copied = 0; $errors = 0
    $n = $pending.Count; $i = 0
    foreach ($e in $pending) {
        $i++
        if (Test-UiCancel) { break }
        $f = $e.File
        $it = $byName[$f.Component]
        $source = Get-OfflinePeFileSource -File $f
        if (-not $source) {
            $errors++
            $tip = LF 'Off_NotInRepoTip' ([System.IO.Path]::GetFileName((Get-PeBinPath -BuildId $buildId -Arch $arch -Language $f.Language)))
            $it.Fail($tip)
            Write-UiLog 'error' "$($f.RelativePath): $tip"
            $script:UI.AddTransferred([long]$f.Size)
            continue
        }
        if ($it.State -ne [WinPEOCs.ItemState]::Error) { $it.SetState('Downloading') }
        Set-UiStatus (LF 'Job_Download' $i $n $f.RelativePath)
        if ($source.Type -eq 'bin') {
            $sha = if ($f.Sha1) { [string]$f.Sha1 } else { [string]$source.Entry.Sha1 }
            $size = if ($f.Size -gt 0) { [long]$f.Size } else { [long]$source.Entry.OriginalSize }
            $stream = [WinPEOCs.Archive.BinArchive]::OpenEntry($source.Entry)
            try {
                $r = [WinPEOCs.Net]::CopyStream($stream, [long]$source.Entry.OriginalSize, $e.Dest, $size, $sha, $script:UI.Observer($null), $script:UI.Cancel)
            } finally {
                $stream.Dispose()
            }
        } else {
            $sha = if ($verify -or $source.ByName) { [string]$f.Sha1 } else { '' }
            $r = [WinPEOCs.Net]::CopyFile($source.Path, $e.Dest, [long]$f.Size, $sha, $script:UI.Observer($null), $script:UI.Cancel)
        }
        if ($r.Cancelled) { break }
        if (-not $r.Success) {
            $errors++
            $it.Fail($r.Message)
            Write-UiLog 'error' "$($f.RelativePath): $($r.Message)"
            continue
        }
        $copied++
        $it.FilesDone = $it.FilesDone + 1
        if ($it.State -ne [WinPEOCs.ItemState]::Error) {
            if ($it.FilesDone -ge $it.FileCount) { $it.SetState('Done') } else { $it.SetState('Partial') }
        }
    }

    if (Test-UiCancel) {
        foreach ($it in $items) {
            if ($it.State -eq [WinPEOCs.ItemState]::Queued -or $it.State -eq [WinPEOCs.ItemState]::Downloading) { $it.SetState('Cancelled') }
        }
        $script:UI.Done($Req, $false, (L 'Job_Cancelled'), 'warn')
        return
    }
    if ($errors -gt 0) {
        $msg = LF 'Job_PeDoneErr' $copied $errors
        $script:UI.ShowMessage('warn', (L 'Msg_DoneTitle'), ($msg + "`n`n" + $archRoot))
        $script:UI.Done($Req, $false, $msg, 'warn')
    } else {
        $msg = LF 'Job_PeDone' $copied $archRoot
        $script:UI.ShowMessage('ok', (L 'Msg_DoneTitle'), (LF 'Job_PeDoneMsg' $copied $archRoot))
        $script:UI.Done($Req, $true, $msg, 'ok')
    }
}

# Settings > Verify repository: every entry of every .bin archive and every loose catalog file
function Invoke-OfflineRepoCheck {
    param($Req)
    Assert-OfflineRepo
    Update-OfflineSources
    $archives = @($script:BinArchives.Values | Sort-Object -Property Path)
    $loose = New-Object System.Collections.Generic.List[object]
    foreach ($n in $script:LooseByName.Keys) {
        if ($n -notmatch '^([0-9a-f]{40})\.(cab|esd|appx)$') { continue }
        $sha = $Matches[1]
        foreach ($c in $script:LooseByName[$n]) { $loose.Add([PSCustomObject]@{ Path = $c.Path; Sha1 = $sha; Size = $c.Length }) }
    }
    $badArchives = New-Object System.Collections.Generic.List[string]
    foreach ($d in (Get-OfflineBinDirs)) {
        foreach ($bf in @(Get-ChildItem -LiteralPath $d -Filter '*.bin' -File -ErrorAction SilentlyContinue)) {
            if (-not $script:BinArchives.ContainsKey($bf.FullName.ToLowerInvariant())) { $badArchives.Add($bf.Name) }
        }
    }
    $entries = 0
    $total = [long]0
    foreach ($a in $archives) { $entries += $a.Files.Count; foreach ($e in $a.Files) { $total += $e.OriginalSize } }
    foreach ($l in $loose) { $total += $l.Size }
    $n = $entries + $loose.Count
    if ($n -eq 0 -and $badArchives.Count -eq 0) {
        $null = Update-OfflineRepoInfo
        $script:UI.ShowMessage('info', (L 'Msg_SelfTestTitle'), (L 'Off_CheckEmpty'))
        $script:UI.Done($Req, $true, (L 'Off_CheckEmpty'), 'ok')
        return
    }
    $script:UI.BeginTransfer($total)
    $good = 0
    $bad = New-Object System.Collections.Generic.List[string]
    $badEntries = @{}     # archive path -> list of damaged entry names
    $i = 0
    foreach ($a in $archives) {
        $an = [System.IO.Path]::GetFileName($a.Path)
        foreach ($e in $a.Files) {
            $i++
            Assert-UiNotCancelled
            if ($i % 5 -eq 1) {
                Set-UiStatus (LF 'Job_Verify' "$an · $(LF 'Prog_Count' $i $n)")
                $script:UI.Detail((LF 'Prog_Count' $i $n))
            }
            $h = $null
            try {
                $s = [WinPEOCs.Archive.BinArchive]::OpenEntry($e)
                try { $h = [WinPEOCs.Net]::HashStream($s, [long]$e.OriginalSize, 'SHA1', $script:UI.Cancel, $null) } finally { $s.Dispose() }
                if ($null -eq $h) { throw (New-Object System.OperationCanceledException) }
            } catch [System.OperationCanceledException] {
                throw
            } catch {
                $h = 'error'
            }
            if ($h -eq $e.Sha1) {
                $good++
            } else {
                $bad.Add("$an › $($e.Name)")
                if (-not $badEntries.ContainsKey($a.Path)) { $badEntries[$a.Path] = New-Object System.Collections.Generic.List[string] }
                $badEntries[$a.Path].Add($e.Name)
                Write-UiLog 'error' "$(L 'Err_Hash'): $an › $($e.Name)"
            }
            $script:UI.AddTransferred($e.OriginalSize)
        }
    }
    foreach ($l in $loose) {
        $i++
        Assert-UiNotCancelled
        $h = [WinPEOCs.Net]::HashFile($l.Path, 'SHA1', $script:UI.Cancel, $null)
        if ($null -eq $h) { throw (New-Object System.OperationCanceledException) }
        if ($h -eq $l.Sha1) { $good++ } else { $bad.Add($l.Path); Write-UiLog 'error' "$(L 'Err_Hash'): $($l.Path)" }
        $script:UI.AddTransferred($l.Size)
    }
    $script:UI.Detail('')
    $summary = Update-OfflineRepoInfo
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add((LF 'Off_CheckDone' $good $n))
    $lines.Add((LF 'Off_CheckArchives' $archives.Count (Format-Size $total)))
    if ($summary -and $summary.Languages.Count -gt 0) { $lines.Add((LF 'Off_CheckLanguages' ($summary.Languages -join ', '))) }
    foreach ($b in $badArchives) { $lines.Add((LF 'Off_CheckBadArchive' $b)) }
    if ($bad.Count -gt 0) {
        $lines.Add((LF 'Off_CheckBad' $bad.Count))
        foreach ($b in @($bad | Select-Object -First 5)) { $lines.Add("  $b") }
    }
    $kind = if ($bad.Count -gt 0 -or $badArchives.Count -gt 0) { 'error' } else { 'ok' }
    if ($badEntries.Count -eq 0) {
        $script:UI.ShowMessage($kind, (L 'Msg_SelfTestTitle'), ($lines -join "`n"))
        $script:UI.Done($Req, ($kind -eq 'ok'), $lines[0], $kind)
        return
    }

    # Damaged entries count as present, so List would never download them again: offer to drop them
    $removeCount = 0
    foreach ($v in $badEntries.Values) { $removeCount += $v.Count }
    $fix = $script:UI.Confirm('warn', (L 'Msg_SelfTestTitle'), (($lines -join "`n") + "`n`n" + (LF 'Off_FixText' $removeCount)), (L 'Off_FixOk'), (L 'Off_FixNote'), $null)
    if (-not $fix) {
        $script:UI.Done($Req, $false, $lines[0], $kind)
        return
    }
    $removed = 0
    foreach ($binPath in $badEntries.Keys) {
        $w = New-Object WinPEOCs.Archive.BinArchiveWriter($binPath)
        try {
            $null = $w.KeepFrom($binPath)
            foreach ($name in $badEntries[$binPath]) { if ($w.Remove($name)) { $removed++ } }
            if ($w.Count -gt 0) { $w.Commit() }
        } finally {
            $w.Dispose()
        }
        if ($w.Count -eq 0) { Remove-Item -LiteralPath $binPath -Force -ErrorAction SilentlyContinue }
        Write-UiLog 'warn' (LF 'Off_FixDone' $badEntries[$binPath].Count ([System.IO.Path]::GetFileName($binPath)))
    }
    $null = Update-OfflineRepoInfo
    $script:UI.Done($Req, $false, (LF 'Off_FixResult' $removed), 'warn')
}

# --- Offline labels (replace the download wording of the shared UI) and offline messages ---
function Set-OfflineStrings {
    [WinPEOCs.Loc]::AppendTable(@(
        @('App_Sub', 'Çevrimdışı depo', 'Offline repository'),
        @('App_Title', 'WinPE OCs — Çevrimdışı Depo', 'WinPE OCs — Offline Repository'),
        @('Lang_Sub', 'Çevrimdışı depo · eksik dosyalar Microsoft sunucusundan bir kez indirilip şifreli .bin arşivine eklenir', 'Offline repository · missing files are downloaded once from Microsoft and added to an encrypted .bin archive'),
        @('Pe_Sub', 'Çevrimdışı depo · eksik paketler ADK WinPE eklentisinden bir kez indirilip arşive eklenir', 'Offline repository · missing packages are downloaded once from the ADK WinPE add-on and added to the archive'),
        @('Pe_Empty', "Sürüm, mimari ve dil seçip Listele'ye basın.", 'Pick a version, architecture and language, then press List.'),
        @('Pe_EngineLoading', 'Depo yükleniyor…', 'Loading the repository…'),
        @('Btn_Download', 'Kopyala', 'Copy'),
        @('Msg_SelectFiles', 'Lütfen kopyalanacak öğeleri seçin.', 'Please select the items to copy.'),
        @('Msg_ConfirmExit', "Bir işlem sürüyor. İptal edip çıkmak istiyor musunuz?`n`nYarım kalan indirmeler Repo\_temp klasöründe saklanır ve sonraki denemede devam eder.", "An operation is in progress. Cancel it and exit?`n`nPartial downloads are kept in Repo\_temp and resume next time."),
        @('Dlg_PeTitle', 'Kopyalama onayı', 'Confirm copy'),
        @('Dlg_PeText', 'Seçili bileşenler çevrimdışı depodan hedef klasöre kopyalanacak.', 'The selected components will be copied from the offline repository to the target folder.'),
        @('Dlg_CleanTitle', 'Çıktı klasörlerini temizle', 'Clean output folders'),
        @('Dlg_CleanPe', 'WinPE klasöründeki .cab, .esd ve yarım kalmış .part dosyaları silinecek. Depodaki .bin arşivlerine dokunulmaz.', '.cab, .esd and partial .part files in the WinPE folder will be deleted. The .bin archives of the repository are not touched.'),
        @('St_Starting', 'Arayüz hazır · depo yükleniyor…', 'UI ready · loading the repository…'),
        @('St_EngineReady', 'Hazır · depo yüklendi ({0} sn)', 'Ready · repository loaded ({0} s)'),
        @('Job_LangFetch', 'Dosya listesi depodan okunuyor…', 'Reading the file list from the repository…'),
        @('Job_LangFetchDone', '{0} dosya hazır · kaynak: {1}', '{0} files ready · source: {1}'),
        @('Job_PeFetch', 'Windows PE bileşenleri depodan taranıyor…', 'Scanning Windows PE components in the repository…'),
        @('Job_PeFetchDone', '{0} bileşen hazır · kaynak: {1}', '{0} components ready · source: {1}'),
        @('Job_DownloadStart', '{0} dosya kopyalanacak…', 'Copying {0} files…'),
