function Initialize-WinPEOCsUi {
    if ('WinPEOCs.UiHost' -as [type]) { return }

    Ensure-BinArchiveCompiled

    foreach ($asm in 'PresentationFramework', 'PresentationCore', 'WindowsBase', 'System.Xaml') {
        Add-Type -AssemblyName $asm -ErrorAction Stop
    }
    $wpfPaths = @(
        [System.Windows.Window].Assembly.Location,
        [System.Windows.Media.Brush].Assembly.Location,
        [System.Windows.DependencyObject].Assembly.Location,
        [System.Xaml.XamlReader].Assembly.Location
    )
    $refs = New-Object System.Collections.Generic.List[string]
    if ($PSVersionTable.PSEdition -eq 'Core') {
        $refDir = Join-Path $PSHOME 'ref'
        if (Test-Path -LiteralPath $refDir) {
            foreach ($f in Get-ChildItem -LiteralPath $refDir -Filter '*.dll' -File) {
                if (@('WindowsBase.dll', 'PresentationCore.dll', 'PresentationFramework.dll', 'System.Xaml.dll') -contains $f.Name) { continue }
                $refs.Add($f.FullName)
            }
        } else {
            foreach ($n in 'System.Runtime', 'System.Collections', 'System.Collections.Concurrent', 'System.ComponentModel',
                           'System.ComponentModel.Primitives', 'System.ComponentModel.TypeConverter', 'System.ObjectModel',
                           'System.Linq', 'System.Net.Primitives', 'System.Net.Requests', 'System.Net.ServicePoint',
                           'System.Security.Cryptography', 'System.Text.RegularExpressions', 'System.Threading',
                           'System.Threading.Thread', 'System.Runtime.InteropServices', 'System.Diagnostics.Process',
                           'System.Collections.NonGeneric', 'System.Private.CoreLib') {
                $refs.Add($n)
            }
        }
    } else {
        foreach ($n in 'System.dll', 'System.Core.dll', 'System.Xml.dll', 'System.IO.Compression.dll') { $refs.Add($n) }
    }
    foreach ($p in $wpfPaths) { $refs.Add($p) }

    Add-Type -TypeDefinition $script:CsSource -ReferencedAssemblies $refs -IgnoreWarnings -WarningAction SilentlyContinue -ErrorAction Stop
}

function Show-StartupError {
    param([string]$Message)
    Write-Host ''
    Write-Host "WinPE OCs başlatılamadı: $Message" -ForegroundColor Red
    try {
        [void][System.Windows.MessageBox]::Show($Message, 'WinPE OCs', 'OK', 'Error')
    } catch { }
}

if ($NoGui) {
    Ensure-BinArchiveCompiled
    return
}

Write-Host "WinPE OCs $script:AppVersion (çevrimdışı) · arayüz bellekte derleniyor..." -ForegroundColor Cyan
try {
    Initialize-WinPEOCsUi
} catch {
    Show-StartupError ("C# / WPF derlemesi başarısız oldu:`r`n" + $_.Exception.Message)
    return
}

if (-not [WinPEOCs.UiStartOptions].GetField('Offline') -or -not [WinPEOCs.Net].GetMethod('CopyStream')) {
    Show-StartupError 'Bu PowerShell oturumunda WinPE OCs''un daha eski bir sürümü yüklü. Çevrimdışı sürümü yeni bir PowerShell penceresinde başlatın.'
    return
}
Set-OfflineStrings

$repoError = $null
try { $null = Import-OfflineRepo -RepoDir $script:RepoDir } catch { $repoError = $_.Exception.Message }

$psv = $PSVersionTable.PSVersion
$opts = New-Object WinPEOCs.UiStartOptions
$opts.ThemeXaml         = $script:XamlTheme
$opts.LayoutXaml        = $script:XamlLayout
$opts.AppVersion        = $script:AppVersion
$opts.AppRoot           = $script:AppRoot
$opts.DefaultOutputRoot = $script:AppRoot
$opts.ManifestDir       = $script:RepoDir
$opts.SettingsPath      = Join-Path $script:AppDataDir 'gui-offline.settings'
$opts.LogDir            = Join-Path $script:LocalDataDir 'logs'
$opts.RuntimeInfo       = "PowerShell $($psv.Major).$($psv.Minor)"
$opts.Offline           = $true
$opts.OcDependencies    = [string[]]@($script:OcDependencies.GetEnumerator() | ForEach-Object { '{0}|{1}' -f $_.Key, (@($_.Value) -join ',') })
$opts.ForceShowConsole  = [bool]$ShowConsole

if ($script:RepoIndex) {
    $opts.UupRows    = [string[]]@($script:RepoIndex.Rows | ForEach-Object { '{0}|{1}|{2}|{3}|{4}' -f $_.UpdateId, $_.Version, $_.Arch, $_.IsWin11, $_.IsServer })
    $opts.Regions    = [string[]]@($script:RepoIndex.Languages | ForEach-Object { '{0}|{1}' -f $_.Code, $_.Name })
    $opts.PeVersions = [string[]]@($script:RepoIndex.Versions | ForEach-Object { '{0}|{1}|{2}' -f $_.Label, $_.BuildId, $_.IsServer })
} else {
    $opts.UupRows = [string[]]@(); $opts.PeVersions = [string[]]@()
    $opts.Regions = [string[]]@($script:RegionTable | ForEach-Object { '{0}|{1}' -f $_.Region, $_.Language })
}

$launchedForScript = $false
try {
    $cmd = [Environment]::CommandLine
    $self = if ($PSCommandPath) { [System.IO.Path]::GetFileName($PSCommandPath) } else { $null }
    if ($self -and $cmd -and $cmd.IndexOf($self, [StringComparison]::OrdinalIgnoreCase) -ge 0) { $launchedForScript = $true }
} catch { }
$opts.HideConsoleOnStart = $launchedForScript -and ([WinPEOCs.Native]::ConsoleProcessCount -le 1)

try {
    $script:UI = [WinPEOCs.UiHost]::Start($opts)
} catch {
    $err = $_.Exception
    while ($err.InnerException) { $err = $err.InnerException }
    Show-StartupError ("Arayüz açılamadı:`r`n" + $err.Message)
    return
}
$script:UI.Log('info', ([WinPEOCs.Loc]::F('Log_Started', [object[]]@("$script:AppVersion (çevrimdışı)", "PowerShell $psv ($($PSVersionTable.PSEdition))"))))
if ($script:EngineError) { $script:UI.Log('warn', "Motor: $script:EngineError") }

# Repository summary for Settings and the Windows PE selectors
if ($script:RepoIndex) {
    try {
        $summary = Update-OfflineRepoInfo
        $script:UI.SetPeAvailability((Get-OfflinePeAvailability))
        $srcTag = if ($script:RepoIndex.SourceDesc -eq 'embedded') { ' (yerleşik katalog)' } else { " ($($script:RepoIndex.IndexPath))" }
        $script:UI.Log('info', "Depo: $($script:RepoIndex.Dir)$srcTag · $($summary.Contents)")
        foreach ($r in @($script:RepoIndex.Roots | Select-Object -Skip 1)) { $script:UI.Log('info', "Ek klasör: $r") }
    } catch {
        $script:UI.Log('error', "Depo: $($_.Exception.Message)")
    }
} else {
    $script:UI.Log('error', $repoError)
    $script:UI.ShowMessage('error', (L 'Msg_ErrorTitle'), $repoError)
}
$script:UI.EngineReady($script:AppStartWatch.Elapsed.TotalSeconds)

# --- Request loop: handles UI requests in order and ends when the window closes ---
$uiLang = [WinPEOCs.Loc]::Lang
try {
    while ($true) {
        $req = $script:UI.Next(250)
        if ($null -eq $req) {
            if ($script:UI.IsClosed) { break }
            if ($script:RepoIndex -and [WinPEOCs.Loc]::Lang -ne $uiLang) {
                $uiLang = [WinPEOCs.Loc]::Lang
                try { $null = Update-OfflineRepoInfo } catch { }
            }
            continue
        }
        if ($req.Kind -eq 'Exit') { break }
        try {
            switch ($req.Kind) {
                'LangFetch'    { Invoke-OfflineLangFetch -Req $req }
                'LangDownload' { Invoke-OfflineLangCopy -Req $req }
                'LangClean'    { Invoke-GuiClean -Req $req -Kind 'lang' }
                'PeFetch'      { Invoke-OfflinePeFetch -Req $req }
                'PeDownload'   { Invoke-OfflinePeCopy -Req $req }
                'PeClean'      { Invoke-GuiClean -Req $req -Kind 'pe' }
                'SelfTest'     { Invoke-OfflineRepoCheck -Req $req }
                default        { Write-UiLog 'warn' "Bilinmeyen istek: $($req.Kind)" }
            }
        } catch [System.OperationCanceledException] {
            if (-not $req.IsCompleted) { $script:UI.Done($req, $false, (L 'Job_Cancelled'), 'warn') }
        } catch {
            $msg = $_.Exception.Message
            if ($_.Exception -is [System.Management.Automation.RuntimeException] -and $_.Exception.InnerException -is [System.OperationCanceledException]) {
                if (-not $req.IsCompleted) { $script:UI.Done($req, $false, (L 'Job_Cancelled'), 'warn') }
            } elseif (-not $req.IsCompleted) {
                $script:UI.Fail($req, $msg)
            } else {
                Write-UiLog 'error' ('{0}: {1}' -f $req.Kind, $msg)
            }
        } finally {
            if (-not $req.IsCompleted) { $script:UI.Done($req, $true, $null, $null) }
        }
    }
} finally {
    $script:UI.Shutdown()
}
